quests[11524] = { id = 11524, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Unberechenbares Verhalten", description = "Wir sind zwar nicht genug, um das Sanktum der Sonnenweiten einzunehmen, aber ich habe einen Plan, mit dem wir den Kampf zu unseren Gunsten wenden können.\n\nDie unkontrollierten Energien des Sonnenbrunnens verursachten Fehlfunktionen bei den Wachposten, die auf dieser Insel patrouillieren. Die Kristallkerne, die ihr Verhalten steuern, sind irreparabel beschädigt.\n\nIch habe neue Kristalle angefertigt, mit denen wir sie unter unsere Kontrolle bringen werden. Steckt die Kristalle ins Innere der besiegten Wachposten. Wir benötigen jede Hilfe, die wir bekommen können.", sourceObjective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11525] = { id = 11525, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weitere Konvertierungen", description = "Mein Plan, die beschädigten Kristalle der unberechenbaren Wachposten auszutauschen, hat funktioniert. Wir konnten mit ihrer Hilfe das Sanktum der Sonnenweiten einnehmen.\n\nIch habe neue Kristalle angefertigt, die noch mehr von ihnen unter unsere Kontrolle bringen werden. Platziert diese im Inneren besiegter Wachposten. Wir werden sie dann an verschiedene Orte entsenden, um sie dort einzusetzen, sobald sie konvertiert sind.", sourceObjective = "Verteidigerin Xayann beim Sammelpunkt der Zerschmetterten Sonne möchte, dass Ihr die abgestimmten Kristallkerne ins Innere 5 besiegter herumirrender Wachposten steckt und sie so zu freundlichen Einheiten macht.", progress = "Habt Ihr die Wachposten konvertiert, {name}?", completion = "Ausgezeichnet. Die konvertierten Wachposten werden uns bei der Sicherung unseres Gebiets helfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11526] = { id = 11526, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Magistrix wird vermisst", description = "Wir haben eine unserer Agentinnen ausgesandt, um das Teufelsportal in der Mitte des im Süden gelegenen Platzes der Morgenröte zu untersuchen. Sie ist noch nicht zurückgekehrt.\n\nNehmt diese Schriftrolle - eine der Leichen des Feindes trug sie bei sich. Wir nehmen an, dass sie Euch den Zugang durch das Portal gewährt. Schreitet durch das Portal, spürt Magistrix Seyla auf und helft, so gut Ihr nur könnt.", sourceObjective = "Benutzt die erbeutete Schriftrolle der Legion in der Nähe des Portals auf dem Platz der Morgenröte. Findet Magistrix Seyla, sobald Ihr auf der anderen Seite des Portals seid.", progress = "Seid still, {class}. Die Truppen der Legion bewachen die Gegend südlich des Tors.", completion = "Es ist lieb von Theris, dass er sich um mich Sorgen macht, aber wir haben hier größere Probleme - viel größere.", sourceObjectiveStatus = "unverified-source-field" }
quests[11527] = { id = 11527, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meuterei auf der Gnädigen", description = "Aye, wir haben Schwierigkeiten, <Kamerad/Herzchen>. Moine Kanoniere sind am Meutern! Moi Crew un' ich an Deck werden wohl versuchen müssen, Sorlof in den Hintern zu treten und gleichzeitig mit den meuternden Kanonieren unter Deck fertig zu werden.\n\nDu wirst ma' nach unten gehen und dich um die meuternden Seehunde kümmern müssen. Nimm auch ihr Schießpulver mit - wirst es für die Wumme drüben auf'm Poopdeck brauch'n.\n\nMit dir an der fetten Wumme wird Sorlof sicher abnibbeln und die Beute freigeben!", sourceObjective = "Kapitän Ellis an Bord der Gnädigen Schwester im heulenden Fjord möchte, dass Ihr 5 Schießpulverfässer aus dem Frachtraum des Schiffs besorgt.", progress = "Es wimmelt nur so von meuternden Seehunden und Meeresriesen!", completion = "Hoffen wir mal, dass diese abtrünnigen, schmierigen Ratten ihre Lektion gelernt haben! Nun ist's Zeit, dass du dich an die fette Wumme setzt, Kamerad!", sourceObjectiveStatus = "unverified-source-field" }
quests[11528] = { id = 11528, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Winterhauchgeschenk" }
quests[11529] = { id = 11529, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sorlofs Beute", description = "Meine Mannschäft macht die digge Berda für dich feddich, Matrouse. Dat Fräulein hat sich's entweder auf dem Bug oudär auf die andere Saide von die Kuddä gämüdlich gemacht. Na lous, rann an die Kiste und mach dich feuäbereit, wenn Sorlof in Sicht is'!\n\nWenn wiä dann ers' mal die Landradde erwischt haben, wirst du für uns an die Beude rankommen müss'n - wiä können ja nich von dem verdammten Boud runnä! Bring mir die Beude, dann gibt's auch ne kleine Pütz Gold für dich - der Schild...", sourceObjective = "Vernichtet Sorlof mithilfe der Dicken Berta, holt Euch Sorlofs Beute und kehrt mit ihr zu Kapitän Ellis auf der Gnädigen Schwester zurück.", progress = "Mach hinne, me Jung!", completion = "Geschäft is' Geschäft, me Jung!", sourceObjectiveStatus = "unverified-source-field" }
quests[11530] = { id = 11530, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Schild der Aesiriten", description = "Hiä is' der Schild. Ik hoff' mal dat Euch dat Dingens näch' genauso verfluchen wiäd wie es dat mit meiner Mannschäft un' mich gemacht hät. Ihr müssd nou mal nich nach Hause gehn, aber hiä bleiben, dat könnt Ihr nu auch nich'... Ik bin miä sischr, dat es da ein paar Leude geben wiäd, die dat Dingens zurück haben wolln.\n\nNou schaff miä die Schüssl vom Kahn!", sourceObjective = "Bringt den Schild der Aesiriten zu Orfus von Kamagua. Er befindet sich am Uralten Aufzug im heulenden Fjord.", progress = "Ihr seid zurückgekehrt!", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11531] = { id = 11531, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Seltsames Motorteil", description = "Dieses seltsame Motorteil sieht zwar nicht so aus, als würde es in eine Dampfpumpe passen, jedoch scheint alles andere, was Ihr so herumliegen seht, noch weniger dafür geeignet zu sein. Vielleicht weiß K. Lee Kleinfrey mehr darüber.", sourceObjective = "Bringt K. Lee Kleinfrey in Telredor das seltsame Motorteil.", progress = "Du meine Güte! Was habt Ihr denn da, {name}?", completion = "<K. Lee sieht sich das Motorteil an und wirkt für einen Moment abwesend.>\n\nDas ist mal was echt Besonderes. Hm, schwer zu sagen, woher das Ding kommt. Ich behalte es erst einmal für mich und werde Euch für die Unannehmlichkeiten entschädigen.\n\nAber unter uns gesagt, denke ich, dass es am besten wäre, wenn wir niemandem davon erzählen.\n\n<K. Lee zeigt Euch ihr bestes Lächeln.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11532] = { id = 11532, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ablenkungsmanöver an der Todesschneise", description = "Die Legion wird uns angreifen, sobald ihre Truppen im Süden nicht mehr gebunden sind. Im Moment hält die Geißel in der Todesschneise ihre Streitkräfte beschäftigt. Jedoch nicht mehr lange.\n\nIch möchte, dass Ihr mit einem Drachenfalken über die Schneise hinwegfliegt und die Dämonen mithilfe dieser arkanen Ladungen dezimiert.\n\nWenn alles gut geht, werden Kaels Lakaien es nicht einmal bemerken, wenn wir die Waffenkammer einnehmen. Sprecht mit Ayren, dem Drachenfalkenmeister im westlichen Teil des Hafens, sobald Ihr bereit seid loszufliegen.", sourceObjective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", sourceObjectiveStatus = "unverified-source-field" }
quests[11533] = { id = 11533, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Luftangriffe müssen weitergehen", description = "Dank unserer Luftangriffe gegen die Truppen der Legion in der Todesschneise konnten wir dem Feind die Waffenkammer abjagen.\n\nTatsächlich lief die Sache so gut, dass wir unsere Luftangriffe gegen sie weiterführen werden. Nehmt diese arkanen Ladungen und verwendet sie gegen ihre Truppen.\n\nSprecht mit Ayren Wolkenbrecher im Hafen der Sonnenweiten, sobald Ihr abflugbereit seid.", sourceObjective = "Kampfmagierin Arynna möchte, dass Ihr mit Ayren Wolkenbrecher sprecht, sobald Ihr bereit seid, zur Todesschneise zu fliegen. Tötet dort mithilfe der arkanen Ladungen 2 Oberanführer der Grube, 3 Zauberer der Eredar und 12 Rachevollstrecker.", progress = "Habt Ihr Eure Mission erfüllt, {name}?", completion = "Dämonen, die wir heute töten, sind Dämonen, die wir morgen nicht mehr bekämpfen müssen. Weiter so.", sourceObjectiveStatus = "unverified-source-field" }
quests[11534] = { id = 11534, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldung an Nasuun", description = "Ich bin so froh, dass Ihr hier seid, {class}! Nachdem wir dieses Sanktum den Getriebenen weggenommen hatten, beeilten wir uns, ein Portal zu erschaffen, das von Shattrath in der Scherbenwelt aus hierher führt.\n\nMein Lehnsherr Exarch Nasuun leitet die Bemühungen der Offensive, dieses Portal aufrecht zu erhalten. Er hat mich gebeten, ihm die vielversprechendsten Kandidaten zu schicken, die das Zeug dazu haben, bei der Energieversorgung des Portals behilflich zu sein.\n\nReist nach Shattrath und sprecht mit Nasuun. Ihr findet ihn in A'dals Halle auf der Terrasse des Lichts.", sourceObjective = "Händler Portanuus hat Euch gebeten, mit Exarch Nasuun auf der Terrasse des Lichts in Shattrath zu sprechen.", completion = "Portanuus hat Euch geschickt? Gut, wir haben keine Zeit zu verlieren!", sourceObjectiveStatus = "unverified-source-field" }
quests[11535] = { id = 11535, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vorbereitungen", description = "Versorgungsgüter sind auf dem Weg hierher - wird mir zumindest gesagt.\n\nTrotzdem können wir es uns nicht leisten, hier zu warten und zu hoffen, dass Hilfe kommen wird, bevor die Offensive zum Stillstand kommt. Wir müssen das Beste aus dem machen, was uns gegeben ist.\n\nFür meinen Teil benötige ich Erz, um daraus einen Amboss zu fertigen und anzufangen, unsere Rüstungen und Waffen aufzubessern.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt.\n\nWenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", sourceObjective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, 3 Stück Erz aus ihren Truhen zu stehlen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11536] = { id = 11536, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Hört jetzt nicht auf!", description = "Da wir jetzt einen Amboss haben, kann ich so richtig anfangen zu arbeiten.\n\nIch werde das Eisenerz der Dunkelflossen immer gut gebrauchen können, egal wie viele Versorgungsgüter wir bekommen. Wenn wir hier gewinnen wollen, dann benötigen wir regelmäßige Waffen- und Rüstungslieferungen.\n\nAn der Küste im Osten gibt es eine Gruppe Naga, die Erz abbaut und es dann in Truhen an die Legion schickt. Wenn wir ihnen ihr Erz abnehmen, wird das unserem Vorhaben in vielerlei Hinsicht zugutekommen...", sourceObjective = "Schmiedin Hauthaa in der Waffenkammer der Sonnenweiten möchte, dass Ihr Myrmidonen der Dunkelflossen, die sich im Osten befinden, tötet und ihre Schlüssel dazu verwendet, um 3 Stück Erz aus ihren Truhen zu stehlen.", progress = "Habt Ihr das Erz, nach dem ich Euch gefragt habe, eingesammelt?", completion = "Ausgezeichnet! Damit werde ich Rüstungen und Waffen für unsere Soldaten herstellen können.\n\nEure Hilfe ist Gold wert!", sourceObjectiveStatus = "unverified-source-field" }
quests[11537] = { id = 11537, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht muss weitergehen", description = "Wir müssen zusehen, dass wir die Armeen der Legion weiterhin besiegen und entmutigen.\n\nDie Abgesandten des Hasses sind Stoßtruppen der Legion, die immer dann eingesetzt werden, wenn ihre Streitkräfte erhebliche Verluste zu verzeichnen haben. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen auf dem Platz der Morgenröte. Tötet den Abgesandten, sobald Ihr ihm begegnet, und spießt anschließend seinen Körper auf.", sourceObjective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", progress = "Wart Ihr erfolgreich, {name}?", completion = "Euer Engagement ist beispielhaft, {name}. Wir werden den Streitkräften der Brennenden Legion zeigen, wozu wir im Stande sind.", sourceObjectiveStatus = "unverified-source-field" }
quests[11538] = { id = 11538, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Schlacht um die Waffenkammer der Sonnenweiten", description = "Die Brennende Legion hält die Waffenkammer der Sonnenweiten - sie ist von taktischer Wichtigkeit für unseren Einsatz. Solange ihre Moral hoch bleibt, werden wir das Gebäude ihrem Griff nicht entziehen können.\n\nDie Abgesandten des Hasses sind Elitestoßtruppen der Legion, die als Verstärkung für taktisch wichtige Stellungen eingesetzt werden. Wenn sie auf der Bildfläche erscheinen, schart sich der Feind um sie, denn er fürchtet sie mehr als uns.\n\nHeute werden wir das ändern. Nehmt dieses Banner und erschlagt die Dämonen der Legion. Tötet den Abgesandten, sobald Ihr ihm begegnet, und durchspießt seinen Körper.", sourceObjective = "Herold Inuuro möchte, dass Ihr 6 Dämonen der brennenden Legion und den Abgesandten des Hasses auf dem Platz der Morgenröte oder der Waffenkammer der Sonnenweiten niederstreckt. Benutzt das Banner der Zerschmetterten Sonne, um den Körper des Abgesandten des Hasses aufzuspießen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11539] = { id = 11539, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Hafen einnehmen", description = "Die Armee der Dämmerklingen - sie gehört zu Kaels Elitestreitkräften - wurde im Hafen der Sonnenweiten und in Morgenstern stationiert.\n\nDer Hafen ist von höchster strategischer Bedeutung für unsere Pläne. Je mehr Dämmerklingen Ihr also beseitigt, umso mehr helft Ihr uns damit. Kael'thas wird den Tag bereuen, als er sich von seinem Volk abwandte und sich mit der Brennenden Legion einließ.", sourceObjective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Schützen der Dämmerklingen niederstreckt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11540] = { id = 11540, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vernichtet die Dämmerklingen", description = "Wir haben die Armee der Dämmerklingen aus dem Hafen der Sonnenweiten vertrieben. Die Sonnenweiten gehören nun uns. Doch... bin ich nicht vollends zufrieden.\n\nIch möchte, dass Ihr Euch ins westlich gelegene Morgenstern begebt und jeden überlebenden Anhänger der Dämmerklingen erschlagt, der Euch über den Weg läuft. Sie besiegelten ihr Schicksal, als sie Kael an diesen Ort folgten.", sourceObjective = "Magister Ilastar in der Waffenkammer der Sonnenweiten möchte, dass Ihr 6 Beschwörer der Dämmerklingen, 6 Blutritter der Dämmerklingen und 3 Bogenschützen der Dämmerklingen niederstreckt.", completion = "Was geht nur durch Prinz Kael'thas Sonnenwanderers Kopf, wenn er von den Niederlagen seiner Armeen erfährt?\n\nIst es Verzweiflung? Hilflosigkeit? Furcht?\n\nIch hoffe doch, dass dem so ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11541] = { id = 11541, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Belästigung an der Küste der Grünkiemen", description = "Die Naga haben die Küste der Grünkiemen im Südosten erobert. Ihre Frauen, die Sirenen der Dunkelflossen, haben die Murlocs bezaubert und zu ihren Sklaven gemacht.\n\nEs ist meine Pflicht, dafür zu sorgen, dass das, was auch immer die Naga dort treiben, gestört wird. Hier kommt Ihr ins Spiel.\n\n{class}, ich möchte, dass Ihr den weiblichen Naga die Kontrollkugeln abnehmt und sie auf den Boden in der Nähe der Grünkiemensklaven werft, damit die Kugel zerspringt und die Murlocs befreit werden.\n\nIch nehme an, dass die Murlocs erbost sein werden und sich gegen ihre Meister wenden werden.", sourceObjective = "Kapitänin Valindria möchte, dass Ihr 10 Grünkiemensklaven befreit und zu ihr zurückkehrt, sobald Ihr damit fertig seid. Sie befindet sich auf der 'Silbermonds Stolz' im Hafen der Sonnenweiten.", completion = "Das reicht für heute. Zeit und Regelmäßigkeit ist hier der Schlüssel zum Erfolg. Wenn wir sie zu sehr belästigten, würden sie ihre Aufmerksamkeit direkt auf uns richten - und das wollen wir nicht.\n\nKommt morgen wieder zurück, damit wir für ein wenig mehr Belästigung sorgen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11542] = { id = 11542, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Verstärkung auf", description = "Wir stoßen vor und nehmen den Hafen als nächstes ein, um unsere Kontrolle über die Sonnenweiten zu festigen. Leider ist eine Flotte Schiffe mit Reservisten der Dämmerklingen auf dem Weg dorthin, um Kaels Truppen zu verstärken.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie sich nicht großartig verteidigen können.", sourceObjective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet. Fliegt dann über die Unterstützungsflotte der Dämmerklingen hinweg und benutzt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", sourceObjectiveStatus = "unverified-source-field" }
quests[11543] = { id = 11543, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Feind vom Leibe halten", description = "Wir konnten die Sonnenweiten vollständig einnehmen. Leider hat sich eine Flotte Schiffe mit Reservisten der Dämmerklingen auf den Weg gemacht, um den Hafen einzunehmen.\n\nNehmt dieses Öl, geht zu Ayren Wolkenbrecher und besorgt Euch einen Drachenfalken von ihm. Ihr solltet bis in Reichweite der Schiffssegel fliegen und sie dann in Brand setzen können.\n\nLandet auf einem der Schiffe und greift die Reservisten an. Mit brennenden Segeln werden sie keine wirkliche Gegenwehr starten können.", sourceObjective = "Verteidiger Kaalan in der Waffenkammer der Sonnenweiten möchte, dass Ihr mit Ayren Wolkenbrecher redet und über die Flotte mit Verstärkungstruppen der Dämmerklingen hinwegfliegt. Benutzt solange Ihr fliegt das flammende Öl, um die Segel in Brand zu setzen. Erschlagt 6 Reservisten der Dämmerklingen, nachdem Ihr gelandet seid.", progress = "Konntet Ihr Eure Aufgabe erfüllen, {name}?", completion = "Gut gemacht, {name}. Es sollte eine Weile dauern, bis irgendwelche Verstärkungstruppen im Hafen ankommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11544] = { id = 11544, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Waffen von Ata'mal", description = "Die Terrasse von Ata'mal im Osten des Schattenmondtals ist den Draenei heilig. Derzeit ist sie jedoch von Höllenorcs besetzt, die das spezielle Erz, das dort vorkommt, geschürft und daraus Waffen und Rüstungen der Verderbnis hergestellt haben.\n\nIch brauche die Waffen, um eine Legierung mit Nagaerz herzustellen. Unsere Anachoreten haben meinen Amboss mit der Fähigkeit gesegnet, sie zu reinigen.\n\nIhr könnt die Waffen an den Auserwählten, Tötern und Dunkelwirkern des Schattenmondklans finden. Bringt sie hierher, zerlegt und reinigt sie auf meinem Amboss und übergebt mir das gereinigte Resultat.", sourceObjective = "Schmiedin Hauthaa möchte, dass Ihr 5 Stück gereinigtes Metall von Ata'mal herstellt. Um dies zu tun, müsst Ihr Waffen von Ata'mal auf ihrem Amboss in der Waffenkammer der Sonnenweiten auf der Insel von Quel'Danas zerlegen.", progress = "{class}, ich brauche so viel gereinigtes Metall von Ata'mal, wie nur möglich.", completion = "Ich danke Euch, Freund. Nun werde ich mehr von der speziellen Legierung herstellen können, die zur Herstellung der Waffen und Rüstungen unserer Streitkräfte verwendet wird.\n\nAußerdem habe ich hier ein wenig von dem Extrakt, das bei der Herstellung übrig geblieben ist. Ihr werdet es wahrscheinlich sehr nützlich für Eure Waffen finden. Wählt bitte das aus, was Euren Zwecken am besten dient.\n\nKehrt zu mir am morgigen Tage zurück. Ich werde mit Sicherheit mehr Waffen benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11545] = { id = 11545, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine milde Gabe", description = "Wir haben die Sonnenweiten dem Feind entrissen - der endgültige Sieg steht kurz bevor. Der Preis war hoch und viele tapfere Kämpfer gaben dafür ihr Leben.\n\nMein Ziel ist es, sicherzustellen, dass die Gefallenen nicht vergessen werden. Also bitte ich Euch, dass Ihr einen Moment innehaltet, um über eine Spende für eine Gedenkstätte nachzudenken. Alles übrig gebliebene Gold wird an die Witwen und Waisen der Gefallenen gehen.", sourceObjective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", sourceObjectiveStatus = "unverified-source-field" }
quests[11546] = { id = 11546, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geschäft geöffnet", description = "Willkommen, {name}.\n\nEs gibt mehrere Möglichkeiten, wie ich Euch bei Eurem Unterfangen behilflich sein kann.\n\nIch habe zum Beispiel vor Kurzem ein Rezept für ein einzigartiges Elixier entdeckt.\n\nDie Blutbeere ist in vielen Regionen Azeroths ein wildes Gewächs und wurde sehr lange als lästig empfunden. Ich habe jedoch herausgefunden, dass die Pflanze, wenn sie den Kräften des Sonnenbrunnens ausgesetzt wird, besondere Eigenschaften annimmt, die destilliert und anschließend getrunken werden können, um die eigenen Fähigkeiten zu verstärken.\n\nGeht zu den Büschen in der Nähe und bringt mir eine Probe - dann werdet Ihr sehen, was ich meine.", sourceObjective = "Mar'nah im Hafen der Sonnenweiten möchte, dass Ihr 5 Blutbeeren von den Büschen auf Quel'Danas sammelt.", progress = "Habt Ihr diese Beeren schon gesammelt?", completion = "Ausgezeichnet, {name}.\n\nIch hoffe, dass Euch dies bei Eurem Unterfangen helfen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11547] = { id = 11547, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kenne deine Leylinien", description = "Trittbrettfahrer!\n\nAlle wollen sie ihre Wünsche sofort erfüllt haben, ohne auch nur einen Gedanken daran zu verschwenden, wie viel Anstrengung selbst im einfachsten Portal steckt.\n\nVielleicht wird Euch etwas Aufklärung ein wenig mehr Dankbarkeit für meine unermüdlichen Anstrengungen beibringen.\n\nNehmt diesen Kristall und stimmt ihn auf den Blutkristall im Westen ab. Dieselbe Prozedur müsst Ihr dann am Portal auf dem Platz der Morgenröte im Süden und in der Nähe des Nagaschreins an der Küste der Grünkiemen im Südosten wiederholen.\n\nVielleicht werdet Ihr dann Eure heiß geliebten Translokationen mehr schätzen...", sourceObjective = "Astromant Darnarian im Sanktum der Sonnenweiten möchte, dass Ihr den Kristall des Astromanten am Blutkristall, am Portal auf dem Platz der Morgenröte und in der Nähe des Nagaschreins an der Küste der Grünkiemen benutzt.", progress = "Habt Ihr den Kristall schon ausgerichtet, {class}?", completion = "Ja, ja. Sehen wir uns das doch einmal an.\n\nAlles scheint in Ordnung zu sein. Also gut. Hier ist Euer Translokator.\n\nWenn auch nur ein Teil Eurer Messungen fehlerhaft ist, dann ist es unvorhersehbar, wo genau Ihr landen werdet. Aber dann wäret Ihr wohlgemerkt selber schuld.", sourceObjectiveStatus = "unverified-source-field" }
quests[11548] = { id = 11548, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure weitere Unterstützung", description = "Wir haben den Gefallenen zu Ehren ein Denkmal errichtet - ein kleiner Trost für die Familien, die ihre Angehörigen verloren haben.\n\nIch werde damit beginnen, Spenden zu sammeln, um die Waisen und Ehepartner unserer Kriegshelden zu unterstützen. Falls Ihr eine kleine Spende machen könntet, würdet Ihr viel dazu beitragen.", sourceObjective = "Anachoretin Ayuri in den Sonnenweiten auf der Insel des Sonnenbrunnens möchte, dass Ihr 10 Gold spendet.", progress = "Wollt Ihr eine Spende machen?", completion = "Ihr seid eine tugendhafte Seele, {name}. In Zeiten des Krieges und Triumphs werden die Gefallenen nur zu leicht vergessen. Die Freunde und Familien der Toten danken Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11549] = { id = 11549, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein großmütiger Spender", description = "Ihr habt viel für uns getan, {name}. Wir sind Euch für Eure Unterstützung sehr dankbar.\n\nIhr habt vielleicht bemerkt, wie sich die Anachoretin Ayuri dort draußen bemüht. Sie hat ein großes Herz und ist sehr überzeugend, aber die Spenden kommen nicht gerade an das heran, was sie sich erhofft hatte.\n\nFalls Ihr eine große Spende machen würdet, um ihre Sache zu unterstützen, werde ich mich persönlich dafür stark machen, dass Eure Taten in diesem Krieg weit und breit bekannt sein werden. Was sagt Ihr dazu?", sourceObjective = "Anachoret Kairthos möchte, dass Ihr 1000 Gold spendet, um Anachoretin Ayuri in ihrem Vorhaben zu unterstützen. Wenn Ihr die Aufgabe abschließen solltet, werdet Ihr den Namen \"{name} der Zerschmetterten Sonne\" tragen.", progress = "Seid Ihr bereit dazu, den Beitrag zu leisten?", completion = "Ihr seid wahrhaftig eine großzügige Person und ein würdiger Verbündeter. Von nun an sollt Ihr als \"{name} der Zerschmetterten Sonne\" bekannt sein. All diejenigen, die hier kämpften, werden von Euren Taten wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11550] = { id = 11550, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Betrüger betritt die Bühne...", description = "Kael'thas' finstere Pläne konnten unseren größten Anstrengungen zum Trotz ausgeführt werden. Der Sonnenbrunnen wurde wieder entfacht, um die Ankunft des Betrügers vorzubereiten.\n\nDer Gegenstand, der vor mir steht und über dem A'dal schwebt, repräsentiert den derzeitigen Status der Verteidigungsanlagen des Sonnenbrunnens. Es wurden riesige Barrieren errichtet, um unsere Angriffe auf die inneren Hallen zu behindern. Wenn unsere Welt jemals Hilfe benötigen sollte, dann wäre es jetzt.\n\nMeldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas nördlich von Quel'Thalas.", sourceObjective = "Meldet Euch bei Erzmagier Ne'thul auf der Insel von Quel'Danas, nördlich von Quel'Thalas.\n\nSprecht mit Flugmeistern in Eisenschmiede und Silbermond, sie werden Euch dorthin bringen.", completion = "Kil'jaeden stürzt sich mit der geballten Kraft der Brennenden Legion auf diese Welt. Sollte er beschworen werden, wird unsere Welt abermals im Chaos versinken. Eure Unterstützung auf der Insel von Quel'Danas ist entscheidend für unseren Sieg über die Legion.\n\nUnsere Magier arbeiten daran, die Barrieren zu durchbrechen, die uns den Zugang zum Sonnenbrunnen versperren. Leistet Euren Beitrag im Kampf gegen die Streitkräfte der Legion, indem Ihr der Offensive der Zerschmetterten Sonne helft.", sourceObjectiveStatus = "unverified-source-field" }
quests[11554] = { id = 11554, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Freund an der Front", sourceObjective = "Euer Beitrag zur Offensive wurde nicht übersehen, {name}. Die vereinten Kräfte der Aldor und Seher bedanken sich bei Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11555] = { id = 11555, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eure Verbündeten wollen Euer Wohl", sourceObjective = "Ihr beweist Euch weiterhin als würdig in dieser überaus wichtigen Schlacht, {name}. Bitte nehmt dies als Zeichen unserer fortwährenden Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11556] = { id = 11556, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf dem Schlachtfeld zollt man Euch Respekt", sourceObjective = "Ohne Euch hätten wir nie so weit kommen können, {name}. Die vereinten Kräfte der Aldor und Seher sind nicht genug, um die Legion und Kael zu vernichten. Wir sind froh darüber, Verbündete von Eurem Kaliber unter uns zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11557] = { id = 11557, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Alle Kämpfer begegnen Euch mit Ehrfurcht", sourceObjective = "Ihr seid einer unserer allerbesten Kämpfer, {name}. In unserer Armee wird man Euren Namen nicht so schnell vergessen.\n\nIm Namen unserer Streitkräfte bitte ich Euch, dieses kleine Geschenk entgegenzunehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11558] = { id = 11558, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefährliche Liebschaft", description = "Diese Liebesepidemie hat etwas Unnatürliches an sich. Sie ist abscheulich und hat sie erst einmal unsere Verteidigung geschwächt, könnte dies zu einer ernsten Bedrohung für uns alle werden.\n\nSchlimm genug, dass bereits so viele unserer Leute von diesem lächerlichen Verhalten befallen sind. Ich denke, selbst unsere Wächter hat es bereits erwischt, dabei sollten sie gegen derartige Einflüsse immun sein.\n\nGeht zu einem der Wächter und seht, ob er von dieser Dummheit befallen wurde.", sourceObjective = "Besorgt eine modrige Karte des Wächters und bringt sie zu Fenstad Argyle in Unterstadt.", progress = "Waren meine Sorgen berechtigt? Wurden unsere idiotischen Wachen überwältigt?", completion = "Es ist also wahr! Das ist unglaublich, wie konnte das nur passieren? Lasst mich einen Moment nachdenken. Es muss doch eine Ursache für all das geben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11559] = { id = 11559, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Winterflossenhandel", description = "Da Ihr Euch nun mit den Winterflossen verständigen könnt, ist es an der Zeit, Euch einmal vorzustellen. Handel mit ihnen zu treiben, ist mit die beste Art und Weise, dies zu tun.\n\nMurlocs schätzen Muscheln höher als alles andere und Ihr einziger überlebender Händler nennt sich Ahlurglgr. An Eurer Stelle würde ich also eine Handvoll Winterflossenmuscheln sammeln und sie ihm zum Geschenk machen.\n\nDie Muscheln liegen überall im Graben verstreut, können jedoch auch jenseits des Grabens, im Dorf und den Höhlen der Winterflossen, gefunden werden.", sourceObjective = "Sammelt 5 Winterflossenmuscheln und liefert sie bei Ahlurglgr ab. Dieser befindet sich in der Zuflucht der Winterflossen.", progress = "Was ist das denn? Wer seid Ihr?\n\nIhr seid ein - ein {race}! Wie kommt es, dass Ihr unsere Sprache sprechen könnt?", completion = "Die sind für mich? Ist das einer Eurer Tricks, {race}? Nein?\n\nNa dann danke ich Euch! Seid stets willkommen, wenn Ihr noch mehr Muscheln habt und mit mir handeln wollt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11560] = { id = 11560, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh neeiin, die Kaulquappen!", description = "Wie gut, dass Ihr wieder da seid!\n\nAls der Erdrutsch in der Nähe des Dorfes auf der anderen Seite des Wassers die Höhlen freilegte, kam ein gehässiger Hummerstrok namens Claximus aus ihnen herausgekrochen und stahl sich mit den Kaulquappen der Winterflossen davon.\n\nIrgendetwas geschah mit den Murlocs, die ihm in die Höhlen nachfolgten, denn als sie wieder herauskamen, waren sie unter seiner Kontrolle.\n\n{class}, Ihr müsst auf die andere Seite schwimmen, im Dorf und in den Höhlen nach den Kaulquappen der Winterflossen suchen und sie in Sicherheit bringen.\n\nDie Zukunft des Winterflossenstammes liegt in Euren Händen!", sourceObjective = "König Mrgl-Mrgl möchte, dass Ihr 20 Kaulquappen der Winterflossen befreit und anschließend zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen.", completion = "Egal was passiert, die Murlocs der Winterflossen haben eine sichere Zukunft vor sich.\n\nFür Eure Selbstlosigkeit habt Ihr Lob und eine Belohnung verdient, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11561] = { id = 11561, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die da!", description = "Unsere Brüder und Schwestern auf der anderen Seite des Wassers sind zu unseren Todfeinden geworden. Sie haben unsere Kaulquappen entführt, uns aus unserem Dorf vertrieben und mehr von meinem Volk ermordet, als ich zählen kann.\n\nErweist Euch als nützlich, {race}! Schwimmt auf die andere Seite des Grabens und metzelt sie nieder!\n\nErst dann wird es in Frage kommen, Euch hier zu akzeptieren - trotz des Wohlwollens, das Euch der neue König gezeigt hat. Und solltet Ihr es versäumen, dann könnt Ihr genauso gut jetzt gehen und nie mehr wiederkehren!", sourceObjective = "Brglmurgl in der Zuflucht der Winterflossen möchte, dass Ihr insgesamt 15 Murlocs der Winterflossen tötet, egal ob Krieger, Orakel oder Küstenschläger.", completion = "Das freut mich. Ich kann den kupfernen Geruch ihres Blutes an Euren Händen riechen.\n\nDas ist ein guter Anfang, {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11562] = { id = 11562, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Putzmurloc erpresst mich", description = "Ich muss Euch etwas Peinliches gestehen: Ich werde erpresst!\n\nMrmrglmr hatte sich damit einverstanden erklärt, ein paar Dinge von mir zu putzen, und dabei mein Ersatzmurlockostüm in die Finger bekommen. Er hat mir damit gedroht, den anderen Murlocs zu zeigen, wer ich wirklich bin.\n\nIch muss Euch nicht erklären, wie katastrophal das für mich wäre! Abgesehen davon habe ich mir einen Plan ausgedacht, zu dessen Umsetzung wir das Kostüm zurückbekommen müssen.\n\nIch bitte Euch, {name}, geht zu Mrmrglmr und erledigt, was auch immer er von Euch verlangt. Er befindet sich nördlich von hier, auf der anderen Seite der Zuflucht.", sourceObjective = "König Mrgl-Mrgl möchte, dass Ihr mit Mrmrglmr sprecht. Er befindet sich im nordwestlichen Teil der Zuflucht der Winterflossen.", completion = "Ah, Ihr müsst also König Mrgl-Mrgls Speichellecker sein. Ich nehme mal an, dass der Nachtelf Euch hierher geschickt hat, um mich zu beschwichtigen?\n\nGut, ich hab' genau die richtige Arbeit für jemanden, der so mächtig ist wie Ihr!", sourceObjectiveStatus = "unverified-source-field" }
quests[11563] = { id = 11563, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Grmmurggll Mrllggrl Glrggl!!!", description = "Wenn Eure erbärmlichen kleinen Augen für etwas nützlich wären, könntet Ihr sehen, dass wir von den Orcas in der nördlich gelegenen Bucht abgeschlachtet werden!\n\nWenn Euer geschätzter Nachtelfenkönig sein Ersatzkostüm wirklich zurückhaben will, werdet Ihr mir bestimmt einen Gefallen tun und mir den Kopf des Königs der Orcas bringen - Glrggl: Er trotzt den Gezeiten, dem Schicksal und schwimmt... Vernichter der Hoffnung, Hoffnung auf Leben... Welle um Welle: Todesgesänge...!\n\nMacht schnell, {race}, Murlocs der Winterflossen verlieren ihr Leben, während wir hier reden und Zeit vergeuden!", sourceObjective = "Mrmrglmr will, dass Ihr mit Glrggls Kopf zu ihm zurückkehrt. Er befindet sich in der Zuflucht der Winterflossen.", progress = "Wenn Ihr Glrggls Kopf nicht dabei habt, dann verschwendet bloß nicht meine Zeit!", completion = "Nicht übel!\n\nDa der König der Orcas nun tot ist, werden die Wale untereinander um die Herrschaft kämpfen und uns weniger angreifen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11564] = { id = 11564, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Saftiger Orcaeintopf", description = "Man sagt mir, {race}, dass Ihr womöglich hinter Glrggl, dem König der Orcas, her seid.\n\nDas ist ja alles schön und gut, aber wenn Ihr jemals den Eintopf schmecken wollt, für den es sich zu leben lohnt, dann werdet Ihr mir den saftigen Tran der Orcas aus der Glimmerbucht bringen müssen.\n\nBeeilt Euch... Ich hab' noch eine Menge an dem Wal hier herumzuschneiden, wenn Ihr für Eure Mühen belohnt werden wollt.", sourceObjective = "Hackebeil Bmurglbrm hat Euch damit beauftragt, 7 Einheiten saftigen Orcatran zu beschaffen. Bringt sie anschließend zu ihm in die Zuflucht der Winterflossen.", progress = "Habt Ihr genug des benötigten Orcatrans mitgebracht?", completion = "Ah, ja, das dürfte reichen.\n\nStellt die Dinger einfach irgendwo hin. Letzte Nacht ist ein wenig Eintopf übrig geblieben - könnt ein wenig davon haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11565] = { id = 11565, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Ersatzkostüm", description = "Ausgezeichnet. Das Geheimnis Eures Königs wird von mir sicher verwahrt, solange er uns im Kampf gegen unsere Feinde unterstützt.\n\nHier, bringt dies zu ihm. Ich hab es sauber gemacht, obwohl ich keine Ahnung hab, wieso er eine zweite Verkleidung braucht.\n\nVielleicht hat er etwas mit Euch vor?", sourceObjective = "Bringt König Mrgl-Mrgls Ersatzkostüm zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen.", progress = "Habt Ihr das Ersatzkostüm dabei, {name}?", completion = "<Als er das Ersatzkostüm sieht, reibt er seine kostümierten Gliedmaßen aneinander.>\n\nSehr gut gemacht. Nun, zurück zu den wirklich dringlichen Angelegenheiten. Ich habe eine Aufgabe von äußerster Wichtigkeit für Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11566] = { id = 11566, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ergebt Euch... nicht!", description = "Die Zeit ist gekommen, um dieser schrecklichen Situation ein Ende zu bereiten, {name}. Claximus muss sterben, wenn die Murlocs der Winterflossen eine Chance auf eine bessere Zukunft haben sollen!\n\nIch möchte, dass Ihr diesen Murlocanzug nehmt - meinen Ersatz - und in die Höhlen der Winterflossen geht. Tut so, als würdet Ihr Euch ergeben wollen, schwingt die weiße Fahne und die Murlocs werden Euch nicht angreifen.\n\nIhr findet Claximus in der südwestlichsten Ecke der Höhlen. Kümmert Euch um ihn, sobald Ihr nahe genug herangekommen seid, und bringt mir eine seiner Klauen als Beweis dafür, dass die gräuliche Tat vollbracht ist.", sourceObjective = "König Mrgl-Mrgl in der Zuflucht der Winterflossen möchte, dass Ihr ihm die Klaue von Claximus bringt.", progress = "Ist es vollbracht, {class}? Ist Claximus tot?", completion = "Bedauerlich, aber notwendig. Ich werde dann mal die Klaue an mich nehmen, wenn Ihr sie noch habt, {name}.\n\nDanke für all Eure Hilfe. Da Claximus nun besiegt ist, können wir vielleicht die verbliebenen Murlocs wieder vereinigen und diese Höhlen verschließen.\n\nIch bitte Euch, mein Freund, nehmt dies... Es ist das Mindeste, was ich für Euch angesichts Eurer Hilfe tun kann!", sourceObjectiveStatus = "unverified-source-field" }
quests[11567] = { id = 11567, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die uralte Rüstung der Kvaldir", description = "Ich war auf dem Schiff, das die Rüstung hierher bringen sollte. Wir hatten das Schiff gerade erst bestiegen und uns auf den Weg gemacht, als wir von einem Zerstörer der Verlassenen angegriffen wurden.\n\nWir wurden geentert. Sie nahmen das ganze Beutegut an sich und übergaben unser Schiff den Fluten...\n\nDas war das Letzte, was ich je von der Rüstung gesehen habe. Wenn du willst, kannst du mit meinem Bomber vom Halunkeneck zur gefürchteten Insel fliegen, wo der Zerstörer vor Anker liegt. Red' mal draußen mit meiner Frau Alanya - sie ist dein Ticket zur Insel.\n\nUnd falls du das Ding finden solltest, dann wage bloß nicht, es hierher zu bringen!", sourceObjective = "Bergt die uralte Rüstung der Kvaldir und bringt sie zu Orfus von Kamagua im heulenden Fjord.", progress = "Habt Ihr die Rüstung gefunden?", completion = "Wir müssen alle Artefakte zurückbringen, {name}. Wenn wir alle vier an uns gebracht haben, werdet Ihr sie in die Gräber zurücklegen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11568] = { id = 11568, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wieder zur Ruhe kommen lassen", description = "<Orfus reicht Euch einen Ranzen.>\n\nIn diesem Ranzen befinden sich die Artefakte, die Ihr zurückgebracht habt. Findet die Gräber des Schildhügels, die sich weit gen Südosten befinden und aus denen die Gegenstände ursprünglich gestohlen wurden, und legt die Artefakte wieder hinein. Ich hoffe, dass diese Geste den Geistern, die derzeit unsere Jagdgebiete heimsuchen, ein Zeichen sein und sie beschwichtigen wird.\n\nSeid stark, {name}...", sourceObjective = "Verwendet das Bündel mit Vrykulartefakten bei den geplünderten Grabhügeln des Schildhügels und legt das gefrorene Herz Isuldofs, den Schild der Aesiriten, den Stab des Sturmfurors und die uralte Rüstung der Kvaldir wieder zurück.\n\nKehrt zu Orfus von Kamagua am Uralten Aufzug zurück, falls Ihr erfolgreich sein solltet.", completion = "Schlimme Neuigkeiten, {name}. Mein Volk ist in Gefahr und muss gewarnt werden. Diese entarteten Seefahrer werden keine Gnade für die Kalu'ak übrig haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11569] = { id = 11569, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlüsselmeister Urmgrgl", description = "Ich muss aus diesen Höhlen raus! Magisches Zeugs sickert durch die Wände und wirkt sich irgendwie auf unsere Gedanken aus. Es scheint von Kaltarra über uns zu kommen.\n\nIch will nicht kontrolliert werden, will nicht das Schicksal der anderen teilen!\n\nSchlüsselmeister Urmgrgl hält sich weiter unten in der Höhle gen Süden auf. Er trägt den Schlüssel für meinen Käfig bei sich. Bringt den Schlüssel hierher, damit wir meinen Käfig aufsperren und von hier verschwinden können.\n\nBeeilt Euch!", sourceObjective = "Glrglrglr in den Höhlen der Winterflossen möchte, dass Ihr Urmgrgls Schlüssel beschafft.", progress = "Habt Ihr den Schlüssel?\n\nNein, mir sind die anderen egal. Ich will hier nur raus!", completion = "Schnell, gebt her!", sourceObjectiveStatus = "unverified-source-field" }
quests[11570] = { id = 11570, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus den Höhlen der Winterflossen", description = "Das Schloss an meinem Käfig sieht zwar nicht gerade fest aus, doch fliehen würde ich ohne Unterstützung nicht - so dumm bin ich nicht.\n\nWerdet Ihr mir helfen, heil aus diesen Höhlen herauszukommen? Wir haben keine Zeit zu verlieren, {race}.\n\nLasst den König bitte wissen, dass es mir gut geht, wenn Ihr zurück zur Zuflucht gelangt. Er wird Euch sicherlich belohnen.", sourceObjective = "Eskortiert Lurgglbr, bis er in Sicherheit ist, und überbringt anschließend König Mrgl-Mrgl in der Zuflucht der Winterflossen die guten Neuigkeiten.", completion = "Das sind wundervolle Neuigkeiten! Und Ihr meint, Lurgglbr hätte entdeckt, dass die Ausströmungen aus den Höhlen diesen Wahnsinn verursachen?\n\nDas kann nur bedeuten, dass die Magie aus Kaltarra stärker wird. Der Nexuskrieg... die Schlacht zwischen dem blauen Drachenschwarm und den restlichen Drachen weitet sich aus.\n\nBald werden wir uns dem nicht mehr entziehen können!", sourceObjectiveStatus = "unverified-source-field" }
quests[11571] = { id = 11571, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lernen, wie man kommuniziert", description = "Um zu helfen, müsst Ihr Euch zuerst mit dem Dialekt der Winterflossen vertraut machen. Dazu werden wir uns die Kräfte von Natur und Magie zu Nutze machen.\n\nNehmt diese leere Muschel. Am Grunde des Wassergrabens lebt Verbrüher, Elementar des Zorn von Wasser und Luft.\n\nBenutzt die Muschel bei seinen Überresten, um seinen magischen Dampf einzufangen, sobald er besiegt ist. Kehrt mit der vollen Muschel zu mir zurück und ich werde Euch mit dem Wissen der Winterflossenzunge erfüllen.\n\nGlücklicherweise hat mir ein Freund einen Wasseratmungszauber beigebracht, den ich auf Euch wirken werde.", sourceObjective = "König Mrgl-Mrgl hat Euch eine Muschel gegeben, die Ihr bei Verbrühers Überresten benutzen sollt. Kehrt mit der gefüllten Muschel des Königs zu ihm zurück. Er befindet sich in der Zuflucht der Winterflossen.", progress = "Konntet Ihr die Muschel mit Verbrühers Dampf füllen?", completion = "Nun werde ich Verbrühers Essenz dazu benutzen können, Euch meine Sprachkenntnisse der Winterflossen zu vermitteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[11572] = { id = 11572, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rückkehr zu Atuik", description = "Kehrt zu Urahn Atuik nach Kamagua zurück. Er und der Rest meiner Leute müssen vor dem drohenden Unheil aus dem Meer gewarnt werden.\n\n<Orfus zittert vor Angst.>\n\nMit dem Uralten Aufzug könnt Ihr zu ihm gelangen. Bitte beeilt Euch!", sourceObjective = "Überbringt Urahn Atuik in Kamagua die schlechten Nachrichten.", completion = "Die Kalu'ak danken Euch für alles, was Ihr getan habt, {name}. Wir müssen uns jetzt auf den Kampf vorbereiten und unsere Brüder und Schwestern auf der anderen Seite des Meeres vorwarnen.\n\nIch hoffe, dass es noch nicht zu spät ist...", sourceObjectiveStatus = "unverified-source-field" }
quests[11573] = { id = 11573, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orfus der Kamagua", description = "Seid gegrüßt, <Reisender/Reisende>. Ich bin Lunkhauer von den Kalu'ak - oder Tuskarr, wie es in Eurer Sprache heißt. Mein Gefährte und ich wurden erst kürzlich ausgeschickt, um die seltsamen Vorgänge entlang einem unserer Jagdpfade zu untersuchen. Doch als wir auf den Friedhof namens Schildhügel zugingen, wurden wir von den Untoten angegriffen. Ich hatte Glück, es bis zu diesem Lager zu schaffen, jedoch weiß ich nicht, was mit Orfus geschehen ist.\n\nVom Uralten Aufzug aus, südöstlich von hier entlang der Klippen, gingen wir getrennte Wege. Werdet Ihr einmal nachsehen, ob alles mit ihm in Ordnung ist?", sourceObjective = "Sucht am Uralten Aufzug im heulenden Fjord nach Orfus von Kamagua.", completion = "Lunkhauer ist am Leben? Immerhin gibt es heute ein paar gute Nachrichten zu hören...", sourceObjectiveStatus = "unverified-source-field" }
quests[11574] = { id = 11574, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zu knapp für meinen Geschmack", description = "Ich habe ihnen alles erzählt, woran ich mich erinnern kann. Wieso glauben sie mir nicht? Ich habe in der Nähe des Abgrundes nach Kräutern gesucht, als sie wie aus dem Nichts auftauchten - dunkle Magier mit magischen Biestern. Ich war umzingelt!\n\nÜber mir erschien ein riesiger magischer Würfel. Er öffnete sich und sog mich einfach auf. Ich schwöre, es ist die Wahrheit!\n\nGenau als er im Begriff war, sich zu schließen, schossen meine Retter auf den Rücken roter Drachen im Sturzflug vom Himmel. Es war atemberaubend! Meine Entführer wurden verstreut und ich konnte fliehen.\n\nIch habe ihnen niemals für meine Rettung danken können. Ich bitte Euch, {class}, findet sie und sagt ihnen meinen Dank.", sourceObjective = "Endorah möchte, dass Ihr Euch auf das Bernsteinflöz nördlich der Kriegshymnenfeste begebt und ihren Rettern ihren Dank aussprecht.", completion = "Ihr könnt Eurer Freundin erzählen, dass es eine Freude und unsere Pflicht war, sie zu retten.\n\nIhre Begegnung war in meinen Augen nichts als ein kleiner Teil eines großen Gesamtbildes.\n\nDalaran scheut keine Mühe, um dieses Geheimnis zu lüften, aber um ganz ehrlich zu sein, könnten wir etwas Hilfe gebrauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11575] = { id = 11575, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gerade noch rechtzeitig", description = "Ich habe ihnen alles erzählt, woran ich mich erinnern kann. Wieso glauben sie mir nicht? Ich habe in der Nähe des Abgrundes nach Kräutern gesucht, als sie wie aus dem Nichts auftauchten - dunkle Magier mit magischen Biestern. Ich war umzingelt!\n\nÜber mir erschien ein riesiger magischer Würfel. Er öffnete sich und sog mich einfach auf. Ich schwöre, es ist die Wahrheit!\n\nGenau als er im Begriff war, sich zu schließen, schossen meine Retter auf den Rücken roter Drachen im Sturzflug vom Himmel. Es war atemberaubend! Meine Geiselnehmer wurden verstreut und ich konnte fliehen.\n\nIch habe ihnen niemals für meine Rettung danken können. Ich bitte Euch, {class}, findet sie und sagt ihnen meinen Dank.", sourceObjective = "Mücke in der Valianzfeste möchte, dass Ihr Euch auf das Bernsteinflöz im Norden begebt und ihren Rettern ihren Dank aussprecht.", completion = "Ihr könnt Eurer Freundin erzählen, dass es eine Freude und unsere Pflicht war, sie zu retten.\n\nIhre Begegnung war in meinen Augen nichts als ein kleines Teil eines großen Gesamtbildes.\n\nDalaran scheut keine Mühe, um dieses Geheimnis zu lüften, aber um ganz ehrlich zu sein, könnten wir etwas Hilfe gebrauchen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11576] = { id = 11576, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klamm beobachten: Spaltkliffanomalie", description = "Grüße, {race}. Ich bin Garren von Dalaran.\n\nVor nicht allzu langer Zeit war die Klamm ein friedlicher Ort - zumindest in geothermischer Hinsicht. \n\nDoch erst vor Kurzem traten mit alarmierender Regelmäßigkeit Erdbeben und Risse im Boden auf, die ein einzigartiges Energiefeld mit gigantischen Kräften freigesetzt haben.\n\nMeine Aufgabe ist es, diese Anomalien zu beobachten und aufzuzeichnen. Meine Instrumente zeigen an, dass eine weitere an der nach Südwesten ausgerichteten Klippenwand aufgetreten ist.\n\nNehmt dieses Gerät und benutzt es, wenn ihr den neuen Riss feststellt.", sourceObjective = "Garren vom Bernsteinflöz möchte, dass Ihr das Arkanometer bei der Spaltkliffanomalie benutzt.", completion = "Faszinierend!\n\nDies ist bisher der größte Riss.\n\nIch fürchte allerdings, dass uns das Schlimmste noch bevorsteht.", sourceObjectiveStatus = "unverified-source-field" }
quests[11578] = { id = 11578, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Fress\"-Quest (123)aa", sourceObjective = "Tötet Koboldgezücht - und zwar 2 davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11579] = { id = 11579, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die \"Fress\"-Quest (123)aa", sourceObjective = "Tötet Koboldgezücht, und zwar 2 davon.", sourceObjectiveStatus = "unverified-source-field" }
quests[11580] = { id = 11580, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Horde im Silberwald!", sourceObjectiveStatus = "unverified-source-field" }
quests[11581] = { id = 11581, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz in Westfall!", sourceObjectiveStatus = "unverified-source-field" }
quests[11582] = { id = 11582, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Klamm beobachten: Die Kluft", description = "Habt Ihr das gespürt?! Und das war nur das Nachbeben... Ihr hättet vor ein paar Minuten hier sein sollen!\n\nIch fürchte, ich muss Eure Dienste erneut in Anspruch nehmen. Meine Instrumente sagen mir, dass es westlich von hier zu einem gewaltigen Riss gekommen ist, tief unterhalb der Wasseroberfläche.\n\nWie zuvor möchte ich, dass Ihr den Arkanmeter nehmt und die Anomalie ausmesst.\n\nIch werde einen Zauber wirken, der es Euch ermöglicht, unter Wasser zu atmen. Sollte er abklingen, bevor Ihr etwas gefunden habt, so kommt zu mir zurück und ich werde ihn erneuern.", sourceObjective = "Garren vom Bernsteinflöz möchte, dass Ihr den Arkanometer bei der Kluftanomalie benutzt und mit den Messungen zu ihm zurückkehrt.", completion = "Wie groß war es?\n\nDas ist unmöglich! Ich muss das sofort nach Dalaran melden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11583] = { id = 11583, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme von Westfall.", sourceObjectiveStatus = "unverified-source-field" }
quests[11584] = { id = 11584, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ehrt die Flamme", sourceObjective = "Ehrt die Flamme des Silberwaldes.", sourceObjectiveStatus = "unverified-source-field" }
quests[11585] = { id = 11585, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Wacht", description = "Throm-Ka, {race}! Willkommen in der Kriegshymnenfeste. Zu sehen, dass ein solch dekorierter Held der Horde dem Ruf der Pflicht Folge leistet, erfüllt mein Herz mit Stolz!\n\nDiese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Wir haben viele Schlachten schlagen müssen, um hier in Nordend Fuß zu fassen. Von hier aus wird unsere Reise zur Eiskrone beginnen und die Führungskraft von Höllschreis Sohn soll uns zum Erfolg verhelfen!\n\nGarrosh wartet unten auf Eure Ankunft.\n\nLok'tar ogar!", sourceObjective = "Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste.", completion = "Ein Held der Horde, wie?\n\n<Garrosh beschnüffelt die Luft um Euch herum.>\n\nAngst...\n\n<Garrosh spuckt auf den Boden.>\n\nIhr werdet nicht lange durchhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11586] = { id = 11586, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Höllschreis Wacht", description = "Throm-Ka, {race}! Willkommen in der Kriegshymnenfeste. Zu sehen, dass ein solch dekorierter Held der Horde dem Ruf der Pflicht Folge leistet, erfüllt mein Herz mit Stolz!\n\nDiese uneinnehmbare Feste ist ein Beweis für die Hartnäckigkeit der Horde. Wir haben viele Schlachten schlagen müssen, um hier in Nordend Fuß zu fassen. Von hier aus wird unsere Reise zur Eiskrone beginnen und die Führungskraft von Höllschreis Sohn soll uns zum Erfolg verhelfen!\n\nGarrosh wartet unten auf Eure Ankunft.\n\nLok'tar ogar!", sourceObjective = "Sprecht mit Garrosh Höllschrei in der Kriegshymnenfeste.", completion = "Denkt bloß nicht, dass ich vergessen habe, was Ihr für mein Volk in Nagrand getan habt, {name}. Höllschrei vergisst niemals.\n\nDafür stehe ich in Eurer Schuld und aus diesem Grund gebe ich Euch jetzt diese Chance: Lauft! Verlasst diesen Ort und blickt niemals zurück.\n\nKehrt nach Hause zurück und sprecht ein Gebet für die Sterbenden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11587] = { id = 11587, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefängnisausbruch", description = "Grüße, {class}. Ich bin Donathan, ein loyaler Repräsentant Dalarans.\n\nVergebt mir mein abruptes Auftreten, aber wir befinden uns mitten in einer Krise. In ganz Azeroth werden Magier entführt und ich wurde dazu ermächtigt, jeden einzuberufen, der uns dabei helfen kann, hinter dieses Rätsel zu kommen.\n\nDas Lager gleich südlich von uns ist der Ort, an dem die Untersuchung beginnen wird. Ich fordere Euch auf, einen der dort gefangen gehaltenen Magier zu befreien. Dazu müsst Ihr den Magierjägern in der Nähe einen Schlüssel abnehmen und damit das arkane Gefängnis aufsperren.", sourceObjective = "Bibliothekar Donathan vom Bernsteinflöz möchte, dass Ihr den Beryllmagierjägern auf der Beryllspitze den Beryllkerkerschlüssel abnehmt und ihn dazu verwendet, die eingesperrten Magier aus ihren arkanen Gefängnissen zu befreien.", progress = "Ich vertraue darauf, dass Ihr unablässig daran arbeitet, einen gefangenen Magier zu befreien...", completion = "Gut gemacht, {name}.\n\nDie Kirin Tor nehmen die Hilfe, die Ihr geleistet habt, dankend entgegen. Wisset, dass kein Dienst, den Ihr uns erweist, unbelohnt bleiben wird.\n\nBitte, nehmt diese milde Gabe als Zeichen der Wertschätzung Dalarans.", sourceObjectiveStatus = "unverified-source-field" }
quests[11590] = { id = 11590, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entführung", description = "{name}, wir haben ein Problem.\n\nIch habe soeben erfahren, dass einer unserer Erzmagier, der sich auf dem Weg von Dalaran hierher befand, vermisst wird. Natürlich vermuten wir, dass die Magierjäger dahinter stecken.\n\nDie Zeit drängt. Wir müssen umgehend herausfinden, was Lady Evanor zugestoßen ist, wenn wir darauf hoffen wollen, sie zu befreien.\n\nNehmt dieses Gerät. Kehrt zur Beryllspitze zurück und wendet es auf einen Beryllzauberer an, wenn er sich kurz vor dem Tod befindet. Es sollte ihn lange genug binden, damit Ihr ihn zur weiteren Befragung hierher bringen könnt.", sourceObjective = "Donathan möchte, dass Ihr den arkanen Binder auf einen verwundeten Beryllzauberer auf der Beryllspitze anwendet und ihn anschließend auf das Bernsteinflöz bringt.", progress = "Habt Ihr einen Beryllzauberer gefangen genommen, {name}?", completion = "Ausgezeichnete Arbeit, {name}.\n\nEr wird umgehend für das Verhör bereit sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11591] = { id = 11591, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meldet Euch bei Stahlkiefers Karawane", description = "Stahlkiefer, diese minderbemittelte Kanaille, hat versucht unsere Karawane mit Vorräten auf einer Abkürzung durch einen Friedhof der Taunka zu führen!\n\nWir haben gerade Verbindung mit ihnen aufgenommen!\n\nNun ist die Karawane dezimiert - überrannt von den Geistern der Taunka, die aus ihren Gräbern auferstanden, als er über sie trampelte.\n\nBegebt Euch nach Süden und seht, ob Ihr die Situation in den Griff bekommt, {class}. Ich habe Grunzer Zornfaust mit ein paar Anderen losgeschickt, um dort auszuhelfen.\n\nSeht doch einfach mal nach, ob Ihr ihnen zur Hand gehen könnt.", sourceObjective = "Findet Grunzer Zornfaust. Er befindet sich bei Stahlkiefers Karawane.", completion = "Das ist nicht gut, {class}.\n\nFernläufer Stolzhuf meint, dass es sich hier um die Begräbnisstätte seiner geehrten Urahnen handelt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11592] = { id = 11592, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wir schlagen zu!", description = "Einer unserer Orcs namens Stahlkiefer hat versucht, etwas Zeit einzusparen, indem er eine Abkürzung durch unsere Begräbnisstätte nahm. Hoffentlich ist dies nicht ein Verhalten, das die Horde üblicherweise an den Tag legt, {race}, oder die Taunka werden Euer Ende sein!\n\nDoch Ihr seht aus, als wolltet Ihr dabei helfen, die Sache wieder geradezubiegen. Gut!\n\nStahlkiefers verfluchter Geist sucht nun diesen Ort heim und stört die Überreste meiner Ahnen. Wir müssen ihm ein Ende bereiten!\n\nErstattet Eurem Oberanführer Bor'gorok beim Außenposten gen Norden Bericht, falls wir dies überstehen sollten.\n\nSteht Ihr mir bei?", sourceObjective = "Helft Fernläufer Stolzhuf und seinen Räubern des Kriegshymnenklans dabei, den Angriff auf Stahlkiefers Karawane zu überleben, und besiegt den Geist des Truppenkommandanten Stahlkiefer.\n\nMeldet Euch wieder bei Oberanführer Bor'gorok, falls Ihr erfolgreich sein solltet. Er befindet sich im Außenposten Bor'gorok.", completion = "Blut und Donner! Ihr habt unsere frisch geknüpfte Bande mit den Taunka gerettet.\n\nIch danke Euch dafür, dass Ihr die Dinge ins Lot gebracht habt. Aka'Magosh, {name}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11593] = { id = 11593, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geehrten Toten", description = "Unsere Gefallenen haben das Begräbnis eines Helden verdient, doch wir können sie nicht hier auf geheiligtem Taunkaboden begraben.\n\nIch werde zwar nicht von Euch verlangen ihre Leichen hierher zurückzuschleifen, doch nehmt dies und begebt Euch weiter in den Friedhof hinein. Steckt unsere toten Karawanenwachen und -arbeiter in Brand, wenn Ihr sie findet.\n\nEhrt unsere Toten, {class}!", sourceObjective = "Grunzer Zornfaust bei Stahlkiefers Karawane möchte, dass Ihr mit Zornfausts Fackel insgesamt 10 tote Karawanenwachen oder -arbeiter in beliebiger Kombination einäschert.", completion = "Ich danke Euch, {class}. Wir sind die Horde - die Horde lässt ihre Toten nicht im Stich!\n\nEs hätte von vornherein niemals passieren dürfen. Stahlkiefer ist ein Dummkopf!", sourceObjectiveStatus = "unverified-source-field" }
quests[11594] = { id = 11594, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst sie zur Ruhe kommen", description = "Truppenkommandant Stahlkiefers Dummheit hat dieses Chaos verursacht. Was hat er sich dabei gedacht, als er eine Karawane durch eine Begräbnisstätte der Taunka führte?\n\nDoch was geschehen ist, ist geschehen. Und es liegt nun an uns, mit den Konsequenzen fertig zu werden.\n\nOberanführer Bor'gorok hat mich darum gebeten, Fernläufer Stolzhuf in jeder erdenklichen Hinsicht zu unterstützen. Der Fernläufer möchte, dass wir die Geister seiner Ahnen zur Ruhe kommen lassen.\n\nWas sagt Ihr, {class}? Seid Ihr <Manns/stark> genug, mit solch einer einfachen Aufgabe fertig zu werden?", sourceObjective = "Zerstört 20 Taunkageister, also entweder geisterhafte Weise oder wiederauferstandene Fernläufer, und geht anschließend zu Stahlkiefers Karawane und meldet Euch dort bei Grunzer Zornfaust.", completion = "Gut gemacht, {class}! Ihr müsst ja über enorme Kampferfahrung verfügen, wenn ihr es mit den Untoten aufnehmt. Und falls nicht, trifft es spätestens jetzt zu.\n\nIhr werdet sie gebrauchen können, wenn Ihr in Nordend überleben wollt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11595] = { id = 11595, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Kriegshymnenfeste", description = "Höllschrei trägt die Last der Horde auf seinen Schultern. Lasst Euch von seinem Temperament nicht von Euren Pflichten abbringen, {name}.\n\n<Saurfang nickt Euch zu.>\n\nHabt Ihr gedacht, dass ich den Namen eines Helden von Orgrimmar vergessen würde? Es kommt nicht jeden Tag vor, dass ich das Vergnügen habe, den Kopf Nefarians aufzuspießen!\n\nDie Geißel hat mit ihrem Angriff auf diese Festung begonnen. Unsere Soldaten halten zwar stand, benötigen jedoch dringend Verstärkung. Meldet Euch bei Razgor. Er ist direkt außerhalb der Kriegshymnenfeste stationiert.", sourceObjective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", completion = "<Oberanführer Razgor salutiert.>\n\nEuer Ruf eilt Euch voraus, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11596] = { id = 11596, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Kriegshymnenfeste", description = "Lasst Euch von Höllschrei nicht von Euren Pflichten als Soldat der Horde abbringen, {race}. Er trägt eine schreckliche Last in dieser gefrorenen Einöde, da der Ausgang seines Angriffs den Sieg über die Geißel oder die Auslöschung allen Lebens auf Azeroth bedeutet. Aus diesem Grund benötigen wir Eure Stärke und Weisheit.\n\nDie Geißel hat mit ihrem Angriff auf diese Festung begonnen. Unsere Soldaten halten zwar stand, benötigen jedoch dringend Verstärkung. Meldet Euch bei Razgor. Er ist direkt außerhalb der Kriegshymnenfeste stationiert.", sourceObjective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", completion = "Gerade rechtzeitig... Die Zahl der Neruber scheint sich vor gerade einer Woche verdoppelt zu haben. Wir könnten jede Hilfe gebrauchen, die wir hier draußen kriegen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11597] = { id = 11597, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Verteidigung der Kriegshymnenfeste", description = "Es scheint, als würden wir uns immer in den aussichtslosesten Situationen treffen, Skarabäusfürst. Wart Ihr bei unserem letzten Treffen nicht dabei, die Welt vor dem sicheren Untergang zu retten?\n\n<Saurfang fängt an zu kichern.>\n\nEure Unterstützung ist sehr willkommen hier in Nordend, trotz allem, was der junge Häuptling sagen mag.\n\nWenn wir nur ein Dutzend mehr Soldaten mit Eurer Stärke hätten, würden wir jetzt in Orgrimmar zusammen um ein Feuer herum sitzen.\n\nMeldet Euch bei Oberanführer Razgor. Er befindet sich gleich draußen am Haupteingang der im Süden gelegenen Kriegshymnenfeste.", sourceObjective = "Meldet Euch bei Oberanführer Razgor in der Hütte auf der Südseite der Kriegshymnenfeste.", sourceObjectiveStatus = "unverified-source-field" }
quests[11598] = { id = 11598, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Großfelsbruch zurückerobern", description = "Während die Kriegshymnenfeste zu allen Seiten hin durch zehn Fuß hohe Wälle aus Stein und Stahl geschützt ist, ist dieser Steinbruch ein leichtes Ziel und Angriffen der Neruber ausgeliefert.\n\n<Razgor deutet in Richtung Westen.>\n\nJenseits dieses Steinbruchs stehen tausende Diener der Geißel und warten auf den Angriffsbefehl. Sollten die Neruber unsere inneren Verteidigungsanlagen überwinden, werden wir von Arthas' untoten Legionen überrannt.\n\nWir dürfen das nicht zulassen - weshalb Ihr zum Angriff übergehen und die Neruber im Steinbruch abschlachten müsst.\n\nBlut und Donner, <Soldat/Soldatin>! Nehmt beides mit auf den Weg.", sourceObjective = "Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 15 Neruber der Nerub'ar tötet.", completion = "Ihr habt ihren Vormarsch gebremst, doch bestimmt werden sich ihnen noch viele im Kampf anschließen. Konntet Ihr irgendwelche von den Eiersäcken finden, als Ihr im Steinbruch wart?", sourceObjectiveStatus = "unverified-source-field" }
quests[11599] = { id = 11599, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mein Bruder Thassarian", description = "Ich habe kürzlich von William Allerton, einem Familienfreund, Nachricht erhalten, dass mein Bruder am selben Tag wie er den Dienst an der Waffe hier in der Valianzfeste angetreten hat. Die Sache ist nur... mein Bruder ist bereits seit Jahren tot.\n\nAlles, was ich besaß, habe ich verkauft, um nach Thassarian zu suchen, nur um dann von den örtlichen Behörden Steine in den Weg gelegt zu bekommen. Mir wurde sogar mit einer Festnahme gedroht, falls ich weiterhin herumschnüffeln sollte.\n\nIch brauche jemanden, dem die Obrigkeiten wohlgesonnen sind... jemanden wie Euch. Wenn Ihr mir dabei helfen könntet - ich habe gehört, dass Williams in der Mine von Fernhain stationiert ist.", sourceObjective = "Sucht nach William Allerton im Inneren der Mine von Fernhain.", completion = "Die Leiche passt zu Leryssas Beschreibung von William Allerton. Seltsamerweise finden sich keine Biss- oder Kratzspuren an ihm.", sourceObjectiveStatus = "unverified-source-field" }
quests[11600] = { id = 11600, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der verstorbene William Allerton", description = "Williams Hals wurde von einem scharfen Gegenstand durchschnitten.\n\nWeitere Nachforschung gibt einen einzelnen Hinweis preis, der Leryssa nützlich sein könnte - ein Einberufungsbescheid mit dem Namen William Allerton.", sourceObjective = "Bringt den Einberufungsbescheid zu Leryssa in die Valianzfeste in der boreanischen Tundra.", progress = "Ihr habt mit William gesprochen, {name}?", completion = "Ihr denkt also, dass Williams Tod, den er durch die Geißel gefunden hat, purer Zufall war? Da ist was faul dran, so viel ist sicher.\n\nIrgendetwas geht vor sich. Wir müssen Thassarian finden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11601] = { id = 11601, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verloren und wiedergefunden", description = "Der arme Herr Allerton könnte uns dabei helfen, meinen Bruder zu finden.\n\n<Leryssa enthüllt ein großes Buch, einem Rekrutierungsregister nicht unähnlich.>\n\nHab's mir ausgeliehen, ok? Wollen doch mal sehen, ob dieser Einberufungsbescheid ein Datum hat.\n\nWilliam sah Thassarian in der Schlange, als sie eingezogen wurden. Ihre Einträge müssen dicht nebeneinander stehen... hier ist er!\n\nEr wurde... Einheit S zugewiesen? Alle anderen Einheiten wurden nach Städten der Allianz benannt.\n\nWas für eine Einheit ist das? Wohin wurden sie geschickt? Wir sollten uns umhören. Findet heraus, ob die Gastwirte irgendetwas gehört haben.", sourceObjective = "Sprecht mit James Diakon im Gasthaus der Valianzfeste.", completion = "Kann Euch leider nicht weiterhelfen, mein Freund. Aber vielleicht kenne ich jemanden, der es kann.", sourceObjectiveStatus = "unverified-source-field" }
quests[11602] = { id = 11602, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von der Quelle abschneiden", description = "Die Luftaufklärung des Steinbruchs berichtet, dass die Neruber ihre Eier auf den Gerüsten, welche die Basis umgeben, verstauen. Kluge Biester sind das... Sie bewahren ihre Eier an trockenen, hoch gelegenen Plätzen auf, abseits vom Brennpunkt des Konflikts.\n\nIhr werdet wieder dorthin gehen und ihre Eier ausfindig machen müssen. Findet sie, zerschmettert und zerschlagt sie.\n\nJeder Eiersack, den Ihr zerstört, bedeutet, dass sich zwanzig Neruber weniger an unseren Leichen gütlich tun.", sourceObjective = "Oberanführer Razgor in der Kriegshymnenfeste möchte, dass Ihr 10 Eiersäcke der Nerub'ar zerstört.", completion = "Trotz unserer Bemühungen kommen immer mehr. So kann es nicht weitergehen, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11603] = { id = 11603, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In vino veritas", description = "Das Militär war alles, was dem alten Paßbrand blieb. Selbst nachdem er in den Ruhestand gegangen war, klammerte er sich daran wie an sein eigenes Leben.\n\nEr kennt den Namen jedes Generals, jeder Einheit, Brigade und Abteilung... einfach alles. Er ist der Mann, nach dem Ihr sucht.\n\nDas Problem ist nur, dass er vom Schicksal gezeichnet ist. Er spricht mit niemandem, außer er bekommt seinen Wein der Kul Tiras. Erinnert ihn an die Zeiten, als er bei der Marine war.\n\nIch habe schon seit Monaten keine Lieferung mehr bekommen. Das letzte Schiff aus Kul Tiras ist nordöstlich von hier gesunken. Versucht doch eine Flasche von dort zu bergen und sie Paßbrand zu bringen.", sourceObjective = "Bergt eine Flasche Wein der Kul Tiras aus dem gesunkenen Schiffswrack nordöstlich der Valianzfeste und bringt sie zum alten Paßbrand im Gasthaus der Valianzfeste.", progress = "<Der alte Mann sieht mit ausdruckslosem Blick zu Euch auf.>", completion = "Mmmmm... nicht zu bitter... nicht zu trocken... das ist wie in alten Tagen, als ich gemeinsam mit den Jungs beim Militär war.", sourceObjectiveStatus = "unverified-source-field" }
quests[11604] = { id = 11604, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Deserteur", description = "Einheit S... Einheit S... hmmm... ergibt keinen Sinn... sollte nach einer Stadt benannt sein...\n\nDunkelhain wurde in die Drachenöde geschickt. Die Goldhainjungs in den Fjord. Wo hab ich das nochmal gehört...\n\nAch ja... der Deserteur! Da ist ein Fahnenflüchtiger im Gefängnis der Kaserne. Wurde erst vor Kurzem hineingeworfen. Sagte immer wieder, dass \"S\" für Selbstmord stünde.\n\nSucht nach dem Deserteur. Er hat vielleicht ein paar Informationen für Euch.", sourceObjective = "Findet das Gefängnis in der inneren Festung der Valianzfeste und sprecht mit dem Deserteur.", completion = "Was'n los? Probleme hab' ich genug!", sourceObjectiveStatus = "unverified-source-field" }
quests[11605] = { id = 11605, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die geehrten Ahnen", description = "<Eine fern klingende Stimme hallt in Eurem Kopf wider, als Ihr Euch die Steinstatue anseht.>\n\nLasst Euch nicht erschrecken, <Fremder/Fremde>. Ich bin Ältester Atkanok, ein uralter Ahne des Tuskarrvolkes, ein geübter Handwerker zu meiner Zeit und seit Jahrhunderten der Wächter dieses Steinbruchs.\n\nDer Steinbruch wurde überrannt, wodurch meine Statuen nicht fertig gebaut werden konnten, während die Geister der Ahnen auf der Welt umherwandeln. Werdet Ihr mir helfen, dies wieder zurecht zu biegen?\n\nAls Erstes muss ich die Namen der wandelnden Ahnen wissen. Sucht nach den Markierungen in der Nähe der Statuen.", sourceObjective = "Ältester Atkanok außerhalb des Froststeinbruchs möchte, dass Ihr die Statuen des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret identifiziert.", progress = "<Die ferne Stimme erklingt wieder.>\n\nHabt Ihr die Namen der umherwandelnden Ältesten herausfinden können?", completion = "<Die Stimme des Ältesten Atkanok grüßt Euch, als Ihr seiner Statue nähertretet.>\n\nGut gemacht, {name}. Da wir nun die Namen der umherwandelnden Ältesten haben, können wir mit den durch die Angriffe gestörten Zeremonien weitermachen. Bevor die Geister der Ältesten jedoch zu ihren Steinen geführt werden können, müssen wir die Geister der ermordeten Handwerker und Schamanen besänftigen. Sonst erhören die Geister der Ahnen den Ruf der Zeremonie womöglich nie.", sourceObjectiveStatus = "unverified-source-field" }
quests[11606] = { id = 11606, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geduld ist eine Tugend, die wir nicht brauchen", description = "Wir können so viele Neruber töten und so viele Eier zerstören, wie wir wollen - immer werden neue nachkommen, solange wir ihre Tunnel und Versorgungsschächte nicht sprengen. Natürlich können wir das nicht machen, wenn wir keine schwere Munition haben. Unglücklicherweise wird der Großteil unseres Vorrats von den Goblins und Schmieden für unsere Belagerungspanzer und Waffen verwendet.\n\nDoch zufälligerweise haben wir einen beträchtlichen Vorrat von dem Zeug drüben im Großfelsbruch, unter all dem nerubischen Mist. Ihr müsst nur dorthin gehen und es mir bringen.", sourceObjective = "Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr 15 Kisten mit Munition des Kriegshymnenklans besorgt.", progress = "Uns rennt die Zeit davon, {class}.", completion = "Wenn meine Berechnungen stimmen - was sie oft nicht tun -, dann werdet Ihr ungefähr 10 bis 20 Zephyriumtiefenladungen benötigen.\n\nAch, und Ihr werdet die Süßen in ihren Schlundlöchern platzieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11607] = { id = 11607, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verlorene Geister", description = "Bei dem Angriff auf den Steinbruch wurden die Handwerker und Schamanen, die dort arbeiteten, getötet. Die Gewalt riss die Geisterwelt in absolutes Chaos und wir werden den Ahnen nicht den Weg nach Hause weisen können, wenn wir keinen Weg finden, die Geister der Ermordeten zu besänftigen.\n\nDie Angreifer selbst schenken den Geistern keine Beachtung, doch ihre Begleiter, die Beryllhunde, können die Geister spüren und lassen kein Auge von ihnen ab.\n\nRäumt die Beryllhunde aus dem Weg und befreit mithilfe der rohen Energie, die übrig bleibt, die Geister der Unschuldigen aus ihrem Gefängnis.", sourceObjective = "Ältester Atkanok am äußeren Rand des Froststeinbruchs möchte, dass ihr die Geister von 3 Handwerkern von Kaskala und 3 Schamanen von Kaskala befreit.", progress = "Wie ergeht es den Geistern der Unschuldigen?", completion = "Ich kann spüren, dass der Aufruhr in der Geisterwelt sich zu legen beginnt. Ihr habt gute Arbeit geleistet, {name}. Die Geister der Ahnen können sich glücklich schätzen, Eure Hilfe in diesen Zeiten der Not zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11608] = { id = 11608, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Begrabt diese Kakerlaken!", description = "Norden, Süden, Osten und Westen: Dort liegen die Orte, um die Ihr Euch Sorgen machen solltet. Diese Festung, die sich mitten im Großfelsbruch befindet, ist von vier ideal gelegenen Schlundlöchern der Nerub'ar umringt.\n\n<Holgoth reicht Euch ein Bündel.>\n\nGeht sehr vorsichtig mit diesem Paket um, {name}. Ein falscher Handgriff und Ihr seid Hundefutter.\n\nIn dem Bündel befinden sich Zephyriumsprengsätze. Begebt Euch zu jedem der Schlundlöcher der Nerub'ar und platziert eine Ladung in der Mitte. Wenn alles gut geht, werden die Tunnel einstürzen.\n\nNun bewegt Euch!", sourceObjective = "Rüstmeister Holgoth in der Kriegshymnenfeste möchte, dass Ihr mithilfe des Bündels mit Zephyriumsprengsätzen die Schlundlöcher der Nerub'ar zerstört. Diese befinden sich südlich, östlich, westlich und nördlich der Kriegshymnenfeste.", completion = "Das wird sie aufhalten - zumindest denke ich, dass es das wird. Wie dem auch sei, Ihr habt Euren Teil erledigt. Und das ist alles, was sich ein Orc wünschen kann, oder nicht?", sourceObjectiveStatus = "unverified-source-field" }
quests[11609] = { id = 11609, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Reste beseitigen", description = "Nun, da die Geister der ermordeten Handwerker und Schamanen zur Ruhe gekommen sind, gibt es nichts, was uns davon abhalten könnte, die durch den Angriff unterbrochenen Zeremonien abzuschließen. Ihr müsst die Rolle übernehmen, die traditionell einem Schamanen der Tuskarr vorbehalten ist, und Ihr müsst über alle notwendigen Ritualgegenstände verfügen.\n\nWir haben keine Zeit, neue zu fertigen, also werdet Ihr den Steinbruch nach den Gegenständen absuchen, die von den Opfern des Angriffs zurückgelassen wurden. Geht mit den Objekten vorsichtig um, {name}, denn einige sind Hunderte von Jahren alt. Womöglich werdet Ihr sie den Händen der Eindringlinge entreißen müssen.", sourceObjective = "Bringt Ältester Atkanok 6 Ritualobjekte der Tuskarr. Er befindet sich außerhalb des Froststeinbruchs.", progress = "Habt Ihr alle benötigten Ritualgegenstände besorgen können?", completion = "<Ihr haltet die Objekte vor der Statue des Ältesten Atkanok hoch.>\n\nDas wird genügen, obwohl sie sich in einem traurigen Zustand befinden. Einige von ihnen wurden Jahrhunderte lang benutzt, um am Ende von Barbaren gestohlen und ramponiert zu werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11610] = { id = 11610, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ahnen nach Hause führen", description = "Dank Eurer Hilfe können die Geister der Ahnen nun zu ihren rechtmäßigen Stätten geführt werden, den Statuen, die von den Handwerkern der Kaskala und Schamanen liebevoll hergestellt wurden.\n\nDie Zeremonien für diese Ahnen wurden während des Angriffs auf den Steinbruch unterbrochen und Ihr werdet sie zu Ende bringen müssen. Nehmt die Objekte, die Ihr aus dem Steinbruch beschafft habt, stellt Euch vor die Statuen mit den Namensschildern und tragt diesen Sprechgesang vor.\n\n<Worte in einer fremden Sprache durchströmen Euren Kopf, doch Ihr habt keine Schwierigkeiten, Euch an sie zu erinnern.>", sourceObjective = "Ältester Atkanok möchte, dass Ihr die Geister des Ältesten Kesuk, Ältesten Sagani und Ältesten Takret zu ihren Steinmonumenten geleitet.", completion = "Die Ahnen haben ihre Statuen gefunden und Euch gebührt ihr Dank, {name}. Die Handwerker von Kaskala werden in den Steinbruch zurückkehren und sicherstellen, dass die Blutlinie der Ahnen ungebrochen weitergeht. Für unseren Teil werden wir, die Ahnen, Euch weiterhin mit Interesse beobachten, da Euer Weg anscheinend gerade erst begonnen hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11611] = { id = 11611, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Von der Geißel eingenommen", description = "<Mortuus seufzt.>\n\nPeons... Wir könnten genauso gut ein Schild aufstellen, das den Nerub'ar eine freie Mahlzeit verspricht.\n\nSeht, das Problem mit Peons ist, dass sie: (1.) dumm wie Brot sind und sie (2.) schwächer sind als ein aussätziger Gnom. Kein Wunder, dass die Geißel sich sie als Erstes vorknöpft.\n\nDas versetzt mich in eine relativ prekäre Lage: Ohne Peons kommt die Arbeit zum Erliegen. Keine Peons, kein Bau.\n\nFindet und befreit meine Peons, {race}. Falls sie am Leben sind, solltet Ihr sie im Großfelsbruch in Netze eingesponnen vorfinden.", sourceObjective = "Großknecht Mortuus in der Kriegshymnenfeste möchte, dass Ihr 5 Peons des Kriegshymnenklans befreit.", progress = "Keine Peons, keine Bauten. Und nein, wir werden sie nicht durch Goblins ersetzen. Viel zu teuer...", completion = "Die meisten von ihnen haben es zurückgeschafft. Zumindest diejenigen, die klug genug waren, um zu wissen, dass wir uns in dem gigantischen Stein- und Stahlgebäude befinden...\n\nAbgesehen davon habt Ihr gute Arbeit geleistet. Habe gehört, dass Ihr mehr als ein Dutzend von ihnen da rausgeholt habt.\n\nOh ja, wie soll ich sagen... Ihr seid hier in der Feste in aller Munde...", sourceObjectiveStatus = "unverified-source-field" }
quests[11612] = { id = 11612, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Steinbruch zurückerobern", description = "Ihr seid hier gerne gesehen, {class}. Mein Name ist Etaruk und ich war einmal ein Handwerker hier im Froststeinbruch.\n\nMeine Gefährten und ich waren gerade dabei, mehrere neue Statuen für die aller neuesten Riten vorzubereiten, als wir sahen, wie diese geheimnisvollen blauen Plattformen über unser Plateau geflogen kamen.\n\nAls sie landeten, strömte ein Schwarm von Magiern, die sich auf ihnen befanden, in den Steinbruch, plünderten und ermordeten meine Freunde. Wenn wir sie nicht aufhalten, werden sie unsere Statuen zerstören und sich mit unseren Artefakten davonmachen. Werdet Ihr mir dabei helfen, die Eindringlinge zu besiegen?", sourceObjective = "Etaruk möchte, dass Ihr 12 Beryllschatzjäger tötet. Er befindet sich in der Nähe des Eingangs zum Froststeinbruch.", progress = "Habt Ihr damit begonnen, den Steinbruch von unseren Feinden zu befreien?", completion = "Da nun diese seltsamen Magier wissen, dass die Leute von Kaskala und ihre Alliierten den Steinbruch nicht so leicht aufgeben werden, müssen wir uns erst recht bemühen und sie endgültig besiegen.\n\nMeine Brüder in Kaskala wurden auch angegriffen und werden uns nicht unterstützen können. Doch mit Eurer Hilfe, {name}, können wir die Plünderer überwältigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11613] = { id = 11613, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Karuks Schwur", description = "Sie nennen sich selbst die Kvaldir. Mein Volk erzählt sich Legenden über sie. Wir nennen sie die Tuk-Hariq - die Läufer des Nebels.\n\nMein Dorf wurde von diesen riesigen Dunstkerlen zerstört. Jeder, den ich kannte, wurde von ihnen erschlagen, auch mein Vater Ariut.\n\nDas Gesetz der Tuskarr fordert von mir Vergeltung an jenen zu üben, die das Blut meiner Verwandten vergossen.\n\nIch bin nichts weiter als ein Fischer und habe noch nicht die Reifeprüfung zum Mann hinter mir... Ich kann den niederträchtigen Kvaldir noch nicht auf Augenhöhe begegnen.\n\nIch stünde tief in Eurer Schuld, wenn Ihr in meinem Namen Blutrache übtet.", sourceObjective = "Karuk möchte, dass Ihr 6 Räuber der Skadir und 5 Langbootsmänner der Skadir tötet.", progress = "Wart Ihr erfolgreich, {race}? Die Kvaldir sind grausame {class}. Erwartet kein Pardon von ihnen.", completion = "Ihr habt meinem Volk einen großen Gefallen erwiesen, {name}. Ich muss Euch jedoch noch um eine Sache bitten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11614] = { id = 11614, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schweigen ist Gold", description = "Wir sind auf Befehl von Varimathras hier! Die Mission der Schattenpirscher ist einfach: spionieren. Nun, spionieren und ein kleiner Meuchelmord am Rande.\n\nEiner meiner besten Agenten wird vermisst. Ich habe schon seit Tagen nichts mehr von ihm gehört, weshalb ich das Schlimmste befürchte. Und ich meine nicht den Tod - sein Tod wäre ideal! Ich befürchte, dass er uns hintergeht... vielleicht sogar zum Verräter wurde.\n\nSein letzter bekannter Aufenthaltsort ist der nördlich gelegene Großfelsbruch. Er war im Begriff, sensible Informationen über die Neruber zu sammeln. Findet ihn...\n\nam besten tot...", sourceObjective = "Findet Schattenpirscher Luther im Großfelsbruch.", completion = "Viel toter geht's wohl kaum... Seltsamerweise haben die Neruber die Leiche nicht verschlungen.\n\nNach genauer Untersuchung sehr Ihr, dass Luther seinen Tod selbst herbeigeführt hat - mit tödlichem Gift. Klug. Neruber werden sich nicht in die Nähe dieser vergifteten Leiche wagen.\n\nIhr bemerkt, dass Luther ein Tagebuch in Händen hält.", sourceObjectiveStatus = "unverified-source-field" }
quests[11615] = { id = 11615, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Nerub'ar", description = "Ihr blättert durch die Seiten des Buchs und sucht nach Allem, das von Interesse sein könnte. Auf der letzten Seite stolpert Ihr über mehrere Einträge hektischen Gekritzels.\n\nNekrolords. Habe mindestens ein Dutzend gezählt.\n\nHöfe im Westen sind eine Art Brutstätte der Geißel.\n\nUnzählige Opfer.\n\nDenke, die haben es auf mich abgesehen. Habe mich auf zur Feste gemacht. Lebend bekommen die mich nicht.\n\nSchreckensgift - Haemotoxin. Die werden eine Überraschung erleben, wenn sie mich beißen.\n\nBringt dieses Schreiben zu Barthus.", sourceObjective = "Bringt Luthers Tagebuch zu Schattenpirscher Barthus in der Kriegshymnenfeste.", progress = "Ist er tot?", completion = "<Barthus schlägt die letzte Seite des Tagebuchs auf und fängt an zu lesen.>\n\nDas sind sehr schlechte Neuigkeiten. Höllschrei muss umgehend davon erfahren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11616] = { id = 11616, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nachricht an Höllschrei", description = "<Barthus reißt die letzte Seite heraus und rollt sie zusammen.>\n\nBringt dies sofort zu Höllschrei! In der Zwischenzeit werde ich eine Gruppe ausschicken, die die Höfe auskundschaften soll.\n\nIhr müsst Höllschrei auf jeden Fall davon unterrichten, dass wir Verstärkung benötigen werden.", sourceObjective = "Bringt Barthus' Notiz zu Höllschrei in der Kriegshymnenfeste.", progress = "Was hat diese Störung zu bedeuten? Bürdet mir keinen Unsinn auf!", completion = "<Höllschrei liest den Tagebucheintrag.>\n\nIst das alles?", sourceObjectiveStatus = "unverified-source-field" }
quests[11617] = { id = 11617, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ihre Flucht vereiteln", description = "Ich bin mir sicher, dass Ihr diese blauen und weißen Plattformen, die über dem Steinbruch schweben, gesehen habt. Sie dienen Magiertötern als Transportmittel für ihre Truppenlandungen und nun werden sie mit Artefakten und Fragmenten unserer Statuen beladen.\n\nWir müssen sie aufhalten, bevor sie den Steinbruch verlassen.\n\nDie kleinen Kreaturen, die im Steinbruch herumgraben, tragen Sprengstoff bei sich. Nehmt ihnen das Zeugs ab und zerstört die drei schwebenden Plattformen. Der Anführer hält von einer vierten, gelandeten Plattform aus Ausschau, doch um ihn werden wir uns erst später kümmern.", sourceObjective = "Etaruk möchte, dass ihr die nördliche Plattform, die östliche Plattform und die westliche Plattform zerstört. Er befindet sich außerhalb des Froststeinbruchs.", completion = "Für die Magierjäger wird es schwerer, den Steinbruch zu plündern und unsere Artefakte zu stehlen, als gedacht. Mit Eurer Hilfe, werden wir den Steinbruch zurückerobern und die Dinge wieder richtig stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11618] = { id = 11618, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verstärkung trifft ein...", description = "<Höllschrei schüttelt seinen Kopf.>\n\nIhr habt es vielleicht nicht bemerkt, aber wir versuchen hier, einen Krieg zu gewinnen, {race}. Ich benötige alle verfügbaren Soldaten an den Brandherden des Konflikts. Das bedeutet, dass wir keine echten Soldaten für kleinere Übergriffe abziehen können.\n\n<Höllschrei hält inne und denkt nach.>\n\nWenn Barthus Verstärkung am Hof will...\n\n<Höllschrei klatscht seine Hände zusammen.>\n\n...wird er sie bekommen! Meldet Euch bei Barthus' Auftragsmördern, die sich westlich von hier bei den Höfen aufhalten. Lasst sie wissen, dass Verstärkung eingetroffen ist.", sourceObjective = "Macht Schattenpirscher Ickoris ausfindig. Er befindet sich bei den Höfen des Kriegshymnenklans westlich der Kriegshymnenfeste.", completion = "Das ist alles? Ein {race}? Höllschrei hat nur einen einzigen {class} geschickt?\n\nWenn ich noch eine Kinnlade hätte, wäre sie jetzt auf den Boden gefallen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11619] = { id = 11619, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gamel der Grausame", description = "Mein eigener Vater wurde vom Anführer dieser Plünderer getötet - man nennt ihn Gamel den Grausamen. Er hat das Innere der Höhle an diesem Strand zu seinem Heim gemacht.\n\nIhr habt Euch bereits um seine Männer gekümmert. Führt zu Ende, was Ihr angefangen habt, {name}. Rächt meinen Vater und ich werde mit Euch meinen restlichen Besitz teilen.", sourceObjective = "Karuk möchte, dass Ihr Gamel den Grausamen tötet. Er befindet sich am Strand der Peitschennarbe.", progress = "Habt Ihr Gamel besiegt, {class}?", completion = "Ihr habt es vollbracht, {name}! Die Geister der getöteten Tuskarr können nun in Frieden ruhen - ihr Tod wurde gerächt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11620] = { id = 11620, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eines Vaters Wort", description = "Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, {race}. Man munkelt, dass die Kvaldir im Tempel in der westlichen Gegend des Strandes eine Nagapriesterin am Leben gelassen haben.\n\nSie wird ohne Zweifel gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht erwartet mein Vater, dass sie auf irgendeine Weise mit Euch kooperieren wird.", sourceObjective = "Geht zum Schrein der Schuppen auf dem Strand der Peitschennarbe und haltet dort nach Veehja Ausschau.", completion = "Hsssssssssssss! Seid Ihr hier, um Euch über mich lustig zu machen, {race}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11621] = { id = 11621, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Leviroths Tafel", description = "Ihr seht Euch die Radierungen auf der Tafel genau an und sucht nach verständlichen Textpassagen. Endlich findet Ihr folgendes Fragment:\n\n\"Für ihn, der in den dunkelsten Gewässern haust, werden die Söhne des Nebels Tausende von Seelen fordern, bis schließlich sein Abgesandter erwacht.\"\n\nKaruk könnte an dieser Information interessiert sein.", sourceObjective = "Kehrt zu Karuk zurück und überbringt ihm die Information, die Ihr auf der Tafel gefunden habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11622] = { id = 11622, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheimnisse der Peitschennarbe", description = "Es gibt jemanden, der ein wenig Licht ins Dunkel bringen könnte, {race}. Man munkelt, dass die Kvaldir eine Handvoll von Nagapriesterinnen im Inneren des Tempels am Leben gelassen haben.\n\nDie Hohepriesterin Veehja wird zweifellos gute Gründe haben, ihre ungebetenen Kvaldirgäste zu hassen. Vielleicht kann sie Euch mehr darüber sagen, was die Schrift auf der Tafel zu bedeuten hat.", sourceObjective = "Sucht in den Ruinen der Peitschennarbe in der boreanischen Tundra nach Veehja und sprecht mit ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[11623] = { id = 11623, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Besuch beim Kurator", description = "Der Anführer der Magierjägertruppen ist eine gefürchtete Kreatur namens Kurator Insivius. Mein Volk hat seit Generationen zu Land und zu Wasser unzählige Biester gejagt, doch ich habe noch nie etwas gesehen, das diesem Kurator auf irgendeine Art und Weise ähnelt.\n\nEr ist mit einer der fliegenden Scheiben am oberen Rand des Steinbruchs gelandet und überwacht von dort aus die Operation. {name}, ich kann nur glauben, dass die Ahnen selbst Euch zu mir geschickt haben, um mir dabei zu helfen, diese Magierjäger ein für alle Mal aus diesem Steinbruch zu verjagen.", sourceObjective = "Etaruk am äußeren Rand des Frostfelssteinbruchs möchte, dass Ihr Kurator Insivius tötet.", completion = "Der Kurator und seine Männer müssen gedacht haben, dass sie bei Plünderungen im Steinbruch leichtes Spiel haben würden, doch Ihr habt sie eines Besseren belehrt, {name}. Ich bin Euch für Eure Hilfe zutiefst dankbar und bin mir sicher, dass die Ahnen weiterhin auf Euch Acht geben werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11624] = { id = 11624, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Himmel wird es wissen", description = "Ich muss herausfinden, was meinem Meister Weissager Grimmläufer zugestoßen ist!\n\nKurz zuvor war er dabei, die Magnatauren im nahegelegenen Magmut zu beobachten. Doch gerade ist einer seiner Grunzer zurückgekehrt und meint, dass der Trupp zerschlagen wurde und der Weissager in die Tiefen dieses Ortes verschleppt wurde.\n\nBevor ich Euch jedoch auf eine Selbstmordmission schicke, möchte ich die Geister befragen, um mehr zu erfahren.\n\nEs gibt ein Luftelementar namens Imperean in den westlich gelegenen Ruinen von Eldra'nath. Es ist weise und könnte Euch vielleicht die Informationen geben, nach denen Ihr sucht.", sourceObjective = "Sprecht mit Imperean in den Ruinen von Eldra'nath.", completion = "Wie töricht von Euch, hierher zu kommen, kleiner {race}.\n\nWonach verlangt es Euch?", sourceObjectiveStatus = "unverified-source-field" }
quests[11625] = { id = 11625, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Dreizack von Naz'jan", description = "Fünfhundert Jahre ist es her, seit Azshara ihm die Tiefen des Gewässers unter uns zum Kerker machte. Doch nun trachten die Barbaren danach, das Werk unserer Königin zunichte zu machen!\n\nSie haben unsere Stadt erobert und damit begonnen, meine Brüder ihrem dunklen Gott zu opfern! Als alle Naga schon geopfert waren, da griffen sie nach den Tuskarr - ihre Geister werden keine Ruhe finden!\n\nIch werde Euch helfen, denn für mich wäre es, als trinke ich einen großen Schluck, um meinen Durst nach Rache zu stillen. Ihr Anführer Ragnar hält sich im Nordosten des Gebietes der Peitschennarbe auf. Er nennt einen goldenen Dreizack sein Eigen. Bringt ihn mir!", sourceObjective = "Veehja möchte, dass Ihr zur nordöstlichsten Ecke der Ruinen der Peitschennarbe geht und nach Ragnar Drakkarlund sucht. Tötet ihn und nehmt ihm den Dreizack von Naz'jan ab.", progress = "Habt Ihr den Dreizack bei Euch?", completion = "Aussssssgezeichnet! Wir werden Kvaldirs Bestien töten! Ich werde dieser Brut schon zeigen, was passiert, wenn man sich mit einer Priesterin der Schuppe anlegt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11626] = { id = 11626, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Abgesandte", description = "Raj Naz'jan war der Imperator der Peitschennarbe, als Leviroth eingekerkert wurde. Azshara selbst segnete seinen Dreizack, so dass er die Bestie töten würde, sollte sie jemals entkommen.\n\nNun tragt Ihr ihn, {race}. So sehr es mich anwidert, doch ich werde meine Rache an diesen barbarischen Riesenmännern haben.\n\nNehmt den Dreizack und begebt Euch nördlich der Ruinen der Peitschennarbe in die Tiefen. Leviroth befindet sich unterhalb des Eisberges, der den Ruinen am nächsten ist.\n\nStreckt ihn nieder und treibt den Dreizack tief in sein Fleisch! Kehrt anschließend zu dem, der Euch ausgesandt hat, zurück. Ich möchte Euch nicht wieder sehen.", sourceObjective = "Sucht nach Leviroth unter einem Eisberg, der gleich nördlich der Ruinen der Peitschennarbe im Wasser treibt. Erschlagt ihn mit dem Dreizack von Naz'jan und kehrt zu Karuk in die Gegend nördlich des Strands der Peitschennarbe zurück.", completion = "Die Geister meines Volkes können nun in Frieden ruhen. Ihr habt mir dabei geholfen, meinem Vater Ehre zu erweisen... Vielleicht werde ich eines Tages genauso stark sein wie Ihr.", sourceObjectiveStatus = "unverified-source-field" }
quests[11627] = { id = 11627, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Siedepunkt", description = "Ihr seid also auf Informationen aus: Aufenthaltsort und Zustand Eures 'Weissagers'. Um seine eigenen Probleme vorauszusehen, hat es wohl nicht ganz gereicht.\n\nNichtsdestotrotz werde ich Euch helfen, dieses Wissen zu erlangen. Doch zuerst werdet Ihr etwas für mich tun.\n\nZweifellos habt Ihr den Krieg zwischen Feuer und Wasser im Süden gesehen. Brodler bringt Neers Teich unablässig zum Kochen und die zwei kämpfen nun schon seit einer Ewigkeit.\n\nBegebt Euch zur Kohlschwarzen Anhöhe und zum Kochenden Teich und bringt die beiden dazu, dass sie mit ihrem Gezanke aufhören.", sourceObjective = "Imperean möchte, dass Ihr Brodler und Neer unterwerft. Kehrt zu ihm zurück, sobald sie sich Euch ergeben haben. Er befindet sich in den Ruinen von Eldra'nath.", completion = "Es freut mich, obwohl sie zweifellos ein wenig weiterstreiten werden.\n\nEs gibt jedoch noch etwas anderes, das Ihr erledigen müsst, bevor Ihr zu Eurer Geisterflüsterin zurückkehren könnt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11628] = { id = 11628, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Mantel der Geißel", description = "Im Nordosten zeichnet sich die Tempelstadt En'kilah, Sitz der Geißel in der boreanischen Tundra, drohend am Horizont ab. Aus dem Schutz ihrer Mauern heraus hat der Kommandant der Geißel seine Neruber ausgesandt, um uns einzukesseln.\n\nWeiterhin defensiv zu bleiben, wäre der Untergang für meine Leute, doch meine Ratgeber unterscheiden sich in ihren Strategien. Durm würde blindlings hineinstürmen, während die Weise Aeire ein heimliches Vorgehen vorziehen würde.\n\nDie Tempelstadt hat das Land und die Kreaturen rings um sich verdorben. Aeire glaubt, dass die Pelze der verseuchten Mammuts als Mantel dienen könnten, mit dessen Hilfe ein Eindringling versteckt werden könnte.", sourceObjective = "Häuptling Orkan in Taunka'le möchte, dass Ihr ihm 5 verseuchte Mammutpelze bringt.", progress = "Habt Ihr mir die Mammutpelze gebracht?", completion = "So sehr ich mich auch dagegen sträube, solche von Krankheiten nur so strotzenden Dinger ins Dorf zu bringen, sie könnten uns doch einen Vorteil gegenüber unseren Feinden verschaffen.\n\n<Der Häuptling deutet auf die Weise Aeire und winkt die Pelze mit Verachtung von sich.>\n\nWährend sie die Pelze vorbereitet, müssen wir etwas Anderes herstellen - den Umhang.", sourceObjectiveStatus = "unverified-source-field" }
quests[11629] = { id = 11629, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kehrt zur Geisterflüsterin zurück", description = "Ihr habt getan, was von Euch verlangt wurde, und nun gebe ich Euch, wonach es Euch verlangt.\n\nLiefert diese Urluft bei der Geisterflüsterin im Außenposten Bor'gorok ab. Wenn sie weise ist, wird sie ein Ritual kennen, mit dem Ihr die Informationen, nach denen Ihr sucht, bekommen könnt.", sourceObjective = "Liefert Impereans Urluft bei der Geisterflüsterin Fletschfang im Außenposten Bor'gorok ab.", progress = "{name}, Ihr seid zurückgekehrt. Was habt Ihr erfahren?\n\nWas ist das für ein Geräusch?", completion = "Imperean hat Euch seine eigene Urluft gegeben? Ich kann seine heulenden Winde hören!\n\nIch kenne ein Ritual, für das wir es benutzen können. Wir müssen uns beeilen, bevor seine Urluft sich selbst in Stücke reißt!", sourceObjectiveStatus = "unverified-source-field" }
quests[11630] = { id = 11630, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Erde", description = "Die Weise Aeire glaubt, dass, falls wir die Bälge mit der verdorbenen Erde außerhalb der Tempelstadt härten, sie daraus einen Mantel herstellen könnte, durch den die meisten Diener der Geißel Eure Gegenwart ignorieren werden. Ihr solltet dann gut dazu passen, meint sie.\n\nSie wird besser Recht haben. Es ist die einzige Chance, die wir haben, um Informationen zu sammeln und einen Gegenschlag zu planen.\n\nIhr solltet die Erde, die sie benötigt, in den Gegenden südlich und westlich der Festung finden. Bringt sie zu mir, wenn Ihr genug gesammelt habt.", sourceObjective = "Bringt 8 Klumpen verseuchte Erde zu Häuptling Orkan in Taunka'le.", progress = "Habt Ihr die Erde bei Euch, welche die Weise Aeire benötigt, um den Umhang fertig zu stellen?", completion = "<Häuptling Orkan nimmt die Klumpen Erde, die Ihr gesammelt habt, vorsichtig entgegen.>\n\nWir sollten die Dinger so schnell wie möglich zur Weisen Aeire bringen.\n\nDer Häuptling grunzt und gibt ein Murren von sich und tut so, als würde ihn der verdorbene Schmutz nicht stören.>\n\nWir können nie wissen, wann der Kommandant der Geißel seinen finalen Angriff auf das Dorf starten wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11631] = { id = 11631, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Vision der Luft", description = "Hier, {name}, ich habe die Urluft auf Euch abgestimmt.\n\nÖffnet in Anwesenheit meines Totems der Luft Eure Seele und konzentriert Euch auf Weissager Grimmläufers Schicksal.\n\nDer Geist des Windes berührt alles - wenn wir Glück haben, wird man Euch eine Vision gestatten.", sourceObjective = "Vollzieht mithilfe von Impereans Urluft ein Ritual bei Fletschfangs Totem im Außenposten Bor'gorok, um Informationen über Weissager Grimmläufer zu beschaffen.\n\nSprecht anschließend mit Geistredner Fletschfang.", progress = "Bringt die Urluft wieder zu mir, wenn Ihr das Gefühl habt, genug gesehen zu haben.", completion = "Sie haben seinen Geist in Ketten gelegt. {name}, wir müssen seiner Qual ein Ende setzen!\n\nIhr müsst Euch in das Herz Magmuts begeben und einen Weg finden, ihn zu befreien!", sourceObjectiveStatus = "unverified-source-field" }
quests[11632] = { id = 11632, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was der kalte Wind mit sich bringt...", description = "Ihr haltet das Knochenpanzerfragment von Ith'rix dem Ernter in Euren Händen und erkennt, dass dies erst der Anfang ist. Selbst jetzt spürt Ihr, dass der Sieg nur von kurzer Dauer sein wird. Der Lichkönig wird sicherlich noch Tausende Biester wie Ith'rix haben, die nur darauf warten, auf die Horde losgelassen zu werden.\n\nNehmt Eure Trophäe und präsentiert sie Hochfürst Saurfang in der Kriegshymnenfeste. Er sollte davon in Kenntnis gesetzt werden, dass Ihr einen mächtigen Agenten der Geißel besiegt habt.", sourceObjective = "Bringt Ith'rix' gehärteten Knochenpanzer zu Hochfürst Saurfang in der Kriegshymnenfeste.", progress = "Was habt Ihr denn da?", completion = "<Ein Grinsen zieht sich über Saurfangs Gesicht.>\n\nKommt mir bekannt vor... Mit der Macht von Kalimdor wurden in der Wüste von Silithus tausend Insekten wie dieses hier zertrampelt.\n\nDer Ort hier ist anders, die Umwelt anders, doch die Ergebnisse werden dieselben sein.\n\n<Saurfang inspiziert Euch.>\n\nIhr werdet die Horde in Nordend Stolz machen und ihr alle Ehre bereiten, {name}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11633] = { id = 11633, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dabei sein ist alles", description = "Die Weise Aeire hat das Tuch fertig gestellt. Nehmt es mit und begebt Euch zur Tempelstadt En'kilah. Werft es Euch über, sobald Ihr Euch in der Stadt befindet, um Euch vor den meisten der dort hausenden Dienern der Geißel zu verbergen. Das wird unsere beste Möglichkeit sein, Informationen über die Befestigungen und Anführer unserer Feinde zu sammeln.\n\nKundschaftet die drei großen Säulen der Stadt aus, während Ihr den Umhang übergezogen habt. Das Tuch wird Euch von den meisten Dienern der Geißel beschützen, doch die Monstrositäten der En'kilah werden Euch finden, wenn Ihr zu nah an sie herankommt.", sourceObjective = "Häuptling Orkan in Taunka'le möchte, dass Ihr das magieerfüllte Tuch der Geißel in der Tempelstadt En'kilah überwerft und die Säule des Blutes, die Säule der Pein und die Säule der Fäulnis auskundschaftet.", completion = "<Häuptling Orkan hört Euch aufmerksam zu, als Ihr von Euren Beobachtungen berichtet.>\n\nDie Informationen, die Ihr gesammelt habt, werden uns bei der Planung unseres Angriffs auf die Tempelstadt helfen. Wir werden einen Weg finden müssen, die von Euch identifizierten Offiziere zu besiegen und Zugang zu dieser Nekropole zu erhalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11634] = { id = 11634, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Windreitermeister To'bor", description = "Ihr seid ganz schön hart, {name}. Ich denke, dass Eure Talente woanders besser aufgehoben wären - ich spreche von der Wurzel des ganzen verdammten Problems!\n\n<Razgor deutet in Richtung Westen.>\n\nDort befinden sich tausend Diener der Geißel, mindestens zwei schwebende Todesmaschinen und wer weiß was sonst noch.\n\nAber Ihr werdet es herausfinden und Euch darum kümmern... Das ist richtig, Ihr werdet der Armee der Geißel, die gerade dabei ist, unsere Tür einzutreten, die Hölle heiß machen.\n\nGeht zur Spitze der Kriegshymnenfeste und meldet Euch bei Windmeister To'bor. Er wird Euch erwarten.", sourceObjective = "Meldet Euch bei Windmeister To'bor in der Kriegshymnenfeste.", completion = "He, Mann! Hab dich erwartet.\n\n<To'bor deutet gen Westen.>\n\nWirf mal 'nen kurzen Blick da rüber. Auf der ander'n Seite der Tundra ist der Tod, Mann... Tod.", sourceObjectiveStatus = "unverified-source-field" }
quests[11635] = { id = 11635, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Weissager Grimmläufers Geist", description = "Ihr müsst nach Magmut im Osten.\n\nIhr müsst in die Tiefen der Höhlen hinabsteigen.\n\nIhr müsst mit dem Geist von Weissager Grimmläufer sprechen!", sourceObjective = "Sprecht mit dem Geist von Weissager Grimmläufer im Inneren von Magmut.", completion = "Ich danke Euch für die Atempause, {class}. Wenn wahre Freiheit für mich doch nur so einfach zu erringen wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[11636] = { id = 11636, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ritt auf dem magischen Teppich", description = "Danke, Maan. Ich sprech von Belagerungsmaschinen! An der Westküste bei Garroshs Landeplatz ham wir schwere Panzer stationiert. Wir werden Euch zu diesen Panzern bring'n und Ihr werdet einen davon benutz'n, um der Geißel zu zeig'n, was passiert, wenn die Horde Gerechtigkeit walt'n lässt!\n\nDer einzig schwierige Teil des Ganzen wird's sein, Euch dorthin zu bring'n. Kommt nich' in Frage, dass wir Euch auf einem unserer Windreiter dorthin schick'n. Zu riskant.\n\nSeht Ihr das Feenwesen da drüben? Den elfischen Blondschopf? Yanni heißt der, Maan. Er kann Euch sicher zur Küste bring'n. Sprecht mit Vernichter Grek'lor, sobald Ihr dort seid!", sourceObjective = "Sprecht mit Yanni in der Kriegshymnenfeste, um die sichere Reise zur Küste zu arrangieren. Sprecht mit Vernichter Grek'lor, sobald Ihr bei Garroshs Landeplatz angekommen seid.", completion = "DEN TOTEN KEINE GNADE!\n\nKeiner von denen hatte den Mumm, zurückzubleiben und unsere prächtigen Panzer zu verteidigen, nachdem Höllschrei die Küste für 'verdammt' erklärte. Zumeist ist es hier ruhig, da sich die Geißel gerade neu formiert, um schließlich die Kriegshymnenfeste anzugreifen. Manchmal begegnet mir ein vereinzelter Zombie oder Ghul, aber die machen's normalerweise nicht lange.\n\nNatürlich ist da dann auch der Nebel...\n\n<Grek'lor erschaudert.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11637] = { id = 11637, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Kaganishu", description = "Nachdem mein kleiner Trupp Grunzer getötet wurde, schleppte man mich hier runter und vollzog ein Ritual, an dessen Ende mein Tod stand. Derjenige, der dafür verantwortlich ist, heißt Kaganishu.\n\nIhr habt zwar seine Schamanengehilfen bezwungen, doch mein Geist ist noch immer an diesen Ort gebunden. Nachdem er mich erschlug, nahm er meinen Körper und erschuf daraus einen Fetisch, der mich jetzt hier gefangen hält. Mit seiner Hilfe lernt Kaganishu all das, was ich über Schamanismus weiß.\n\nIhr müsst ihm den Fetisch wegnehmen und ihn auf meinen Geist anwenden. Kaganishu befindet sich in den Höhlen hier in der Nähe.\n\nNur dann werde ich wirklich frei sein.", sourceObjective = "Findet Kaganishus Fetisch und wendet ihn auf die Überreste von Weissager Grimmläufer an.\n\nIhr werdet nach Magmut gehen und den Fetisch Weissager Grimmläufers Geist geben müssen.", progress = "Beeilt Euch, {class}, wendet den Fetisch auf mich an, bevor es zu spät ist.", completion = "Ich bin frei. Vielen Dank, {name}.\n\nUnd nun habe ich eine letzte Bitte an Euch.", sourceObjectiveStatus = "unverified-source-field" }
quests[11638] = { id = 11638, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt meine Überreste zurück", description = "{name}, würdet Ihr, nun da mein Geist befreit wurde, mir die Ehre erweisen und meine Überreste zu Geisterflüsterin Fletschfang bringen? Sie liegen auf dem Boden zu meinen Füßen.\n\nIch spüre, dass die Geisterflüsterin sich noch immer im Außenposten Bor'gorok gen Westen befindet, dort wo ich sie zum letzten Mal sah.", sourceObjective = "Bringt Weissager Grimmläufers Überreste, die zu Füßen seines Geistes liegen, zur Geisterflüsterin Fletschfang im Außenposten Bor'gorok.", progress = "Ihr kehrt früher zurück, als ich erwartet habe. Was habt Ihr erfahren können?", completion = "Ich danke Euch dafür, dass Ihr seinen Geist aus Kaganishus Griff befreit habt und mit seinen Überresten zurückgekommen seid. Wir verfügen über wenig, mit dem wir Euch belohnen könnten, doch Ihr dürft nehmen, was auch immer Ihr zu Gesicht bekommt.\n\nUnd nun werde ich ihn zurück zu den Lebenden befördern - dort wo er hingehört.", sourceObjectiveStatus = "unverified-source-field" }
quests[11639] = { id = 11639, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Rache an Magmut", description = "Der Oberanführer verbietet dem Schamanen, meine Wunden zu heilen. Er sagt, es sei eine gute Lektion für mich und gebe mir Zeit, um über mein Versagen nachzusinnen.\n\nDoch Ihr könntet mich und all jene, die in Magmut fielen, rächen!\n\nIch weiß, dass die Geisterflüsterin will, dass Ihr Euch dorthin begebt und den Weissager befreit.\n\nEs ist ganz in der Nähe im Osten. Geht, {class}... Geht und erschlagt die Magnatauren und ihre Schneebolddiener. Stellt die Ehre des Außenpostens wieder her!", sourceObjective = "Tötet 10 Schamanen der Magmut, 5 Futterwühler der Magmut, 3 Zermalmer der Magmut und 3 Gefährtinnen von Magmutregar. Kehrt anschließend zu Ortrosh im Außenposten Bor'gorok zurück.", completion = "Die Toten werden durch unsere Taten geehrt, {name}.\n\n\n\nVielleicht kann ich jetzt wieder zu dem Krieger werden, der ich einst war.", sourceObjectiveStatus = "unverified-source-field" }
quests[11640] = { id = 11640, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Worte der Macht", description = "In den Säulen, die Ihr beschrieben habt, hausen die Oberleutnants des Anführers der Geißel: die Hohepriester. Sie befehligen nicht nur die Truppen der Geißel, sondern besitzen auch den Schlüssel zur Nekropole über ihnen und damit auch zum Meister.\n\nEin endloser Strom von Dienern der Geißel wird uns überrennen, wenn wir nicht ihren Anführer finden und besiegen können. Ich kann meine Leute nicht schutzlos zurücklassen, egal wie sehr Durm auch den Kampf zum Feind tragen möchte. Es fällt also Euch zu, {name}, die Hohepriester zu töten und die Schriftrollen, die sie bei sich tragen, an Euch zu nehmen.", sourceObjective = "Bringt die Rolle von Hohepriester Naferset, die Rolle von Hohepriester Talet-Kha und die Rolle von Hohepriester Andorath zu Häuptling Orkan in Taunka'le.", progress = "Wir müssen in diese Nekropole hineinkommen, wenn wir durch die Reihen der Geißel brechen wollen und den Weg für die Dorfbewohner freimachen wollen.", completion = "<Häuptling Orkan liest den Text, der auf den Schriftrollen geschrieben steht.>\n\n'Shabtir bakh sokhen.'\n\nWorte der uralten, harten Sprache der Neruber und derjenigen, die darin begabt sind.\n\n'Der Diener unterwirft sich des Meisters Autorität.' Dies sind die Worte, die Euch den Eintritt in die Nekropole gewähren werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11641] = { id = 11641, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein mutiger Schlag", description = "Von Anfang an habe ich dazu geraten, dass Häuptling Orkan unsere mächtigen Krieger sammeln und unseren Feind in seiner Basis angreifen soll. Mein Ratschlag drang in taube Ohren und er hat bewiesen, dass er lieber Zeit verplempert, wie es die Weise Aeire vorgeschlagen hat.\n\nIch werde nicht länger warten. Wenn Häuptling Orkan zu feige ist, unsere Krieger in die Schlacht zu schicken, dann werdet vielleicht Ihr dazu bereit sein, ihm zu zeigen, dass ein Frontalangriff Erfolg haben kann. Erstürmt die Tempelstadt En'kilah und erschlagt alles, was sich Euch in den Weg stellt, {name}.", sourceObjective = "Erschlagt 15 Ghule der En'kilah und 5 Nekromanten der En'kilah und meldet Euch dann wieder bei Durm Eisbalg. Er befindet sich in Taunka'le.", completion = "Ihr habt Eure Furchtlosigkeit bewiesen und Euer Können im Kampf gezeigt. Ich glaube, dass Ihr einen guten Krieger der Taunka abgeben würdet. Ich wünschte nur, dass der Häuptling dasselbe Verständnis aufbringen könnte.\n\nAngesichts der Tatsache, dass wir verzweifelt versuchen das Dorf zu evakuieren, bevor es von der Geißel überrannt wird, können wir uns glücklich schätzen, Euch als Verbündeten an unserer Seite zu wissen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11642] = { id = 11642, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Panzer reparieren sich nicht von selbst", description = "Wir müssen diese Panzer wieder zum Laufen bringen! Die werden sich nicht von selbst reparieren. Mobu wird sich darum kümmern. Sprecht mit ihm und seht nach, was er braucht. Vielleicht könnt Ihr ihn dazu bringen, endlich seinen Mund zu halten, bevor er mich endgültig zum Ausrasten bringt und ich ihn entzwei spalte!", sourceObjective = "Sprecht mit Mobu auf Garroshs Landeplatz.", completion = "Ihr seid der neue Panzerfahrer? Ich hab' nichts dagegen! Wir müssen diese Dinger nur wieder zum Laufen bringen. Ähm, ja, wenn Ihr Euch ohne Panzer auf die Ebene von Nasam wagt, seid Ihr so gut wie tot.", sourceObjectiveStatus = "unverified-source-field" }
quests[11643] = { id = 11643, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mobus pneumatisches Panzertransjigamarick", description = "Die Schraubenschlüssel sind zu nichts zu gebrauchen, {class}. Ich brauche mein pneumatisches Panzertransjigamarick, um diese Dinger wieder zum Laufen zu bekommen! Unglücklicherweise hab ich es in meiner alten Bude auf der anderen Seite dieses Landeplatzes gelassen. Das ist die heruntergekommene Hütte neben den Ställen. Ihr werdet dorthin gehen und sie für mich holen müssen, weil ich in diesem Nebel ganz sicher nirgendwo hingehen werde.\n\nOh ja, {class}, nehmt Euch vor dem Nebel in Acht. Der Nebel ist es, der diese Küsten in Stücke riss.", sourceObjective = "Mobu an der Echoküste in der boreanischen Tundra möchte, dass Ihr sein pneumatisches Panzertransjigamarick beschafft.", progress = "Habt Ihr das P.P.T. gefunden?", completion = "Gute Arbeit, {class}! Wo hab' ich nur diese Ersatzteile gelassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11644] = { id = 11644, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Superstarke Metallplatten!", description = "Ich brauche Metall, um diese Panzer zusammenzuflicken! Superstarke Metallplatten liegen überall auf Garroshs Landeplatz und auf dem Grund der Bucht verstreut.\n\nSeid nur vorsichtig, wenn Ihr dort draußen seid und nach Platten sucht. Der Nebel ist... ähm... AGGRESSIV! Der Nebel war es, der den Landeplatz und die angrenzende Tuskarrsiedlung zerstörte. Arme, kleine Tuskarr...", sourceObjective = "Mobu an der Echoküste in der boreanischen Tundra möchte, dass Ihr 10 superstarke Metallplatten sammelt.", progress = "Vergesst nicht: Der Nebel ist böse!", completion = "Gute Arbeit, {class}! Wo hab' ich nur diese Ersatzteile gelassen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11645] = { id = 11645, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Dreckige, stinkende Schneebolde!", description = "Diese dreckigen, stinkenden Schneebolde... die haben alle meine Vorräte geklaut!\n\nWelche Schneebolde fragt Ihr? Sie sehen wie Kobolde aus, nur, dass sie den Magnatauren dienen, irgendwie sogar auf sie Acht geben. Ich weiß - seltsam!\n\nAber egal. Wollt Ihr mir aushelfen? Ich weiß, dass die kleinen Kriecher sich mit meinem ganzen Zeugs davongestohlen haben. Dumm von mir zu denken, dass sie an der Nordseite des Landeplatzes sicher wären.\n\nWieso tut Ihr mir nicht einen Gefallen und begebt Euch in Richtung Norden zu ihrem dummen Magnamut. Ich werde auch Gold dafür lockermachen, wenn Ihr mir all mein Zeug schnell zurückbringt!", sourceObjective = "Bringt 10 von Pfiffis Werkzeugen zu Pfiffi Wackelspross. Sie befindet sich bei der Landebahn Kurbelzisch.", progress = "Habt Ihr alle meine Vorräte dabei, {class}? Ich kann einfach NICHTS machen, wenn ich nicht all mein Zeug hab'!", completion = "Oh, {name}, Ihr seid einfach der Beste!\n\nHier, wie versprochen: Eure Bezahlung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11646] = { id = 11646, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die boreanische Inquisition", description = "Hört genau zu, {name}, denn wir haben keine Zeit zu verlieren.\n\nEuer Gefangener wird hier in unserem Turm auf die Vernehmung vorbereitet. Eure Hilfe könnte vonnöten sein, falls wir uns begrenzter Zusammenarbeit gegenübersehen.\n\nMacht Euch auf den Weg dorthin, wo er festgehalten wird, und sagt Bibliothekar Normantis, dass ich Euch zu seiner Unterstützung geschickt habe.", sourceObjective = "Donathan hat Euch befohlen, Bibliothekar Normantis Eure Hilfe anzubieten. Er befindet sich im Magierturm auf dem Bernsteinflöz.", completion = "Es war weise von Donathan, Euch zu schicken, {class}.\n\nWie sich zeigt, habe ich gerade Verwendung für jemanden außerhalb der Kirin Tor.", sourceObjectiveStatus = "unverified-source-field" }
quests[11647] = { id = 11647, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Kessel neutralisieren", description = "Die Seuchenkesseln innerhalb der Tempelstadt En'kilah bereiten mir große Sorgen, {name}. Es steht fest, dass Häuptling Orkan Eurem Urteil und Wissen über unseren Feind traut. Würdet Ihr mir bei den Kesseln zur Hand gehen, wenn Ihr schon dabei seid, dem Häuptling bei der Umsetzung seiner Pläne in der Tempelstadt zu helfen?\n\nIch habe ein Totem vorbereitet, das den Inhalt der Kessel angreift und neutralisiert. Alles, was Ihr tun müsst, ist, die Kessel zu finden und das Totem bei jedem zu benutzen. Jede Waffe der Geißel, die wir zerstören, bringt uns dem Sieg einen Schritt näher.", sourceObjective = "Die Weise Aeire in Taunka'le möchte, dass Ihr mithilfe ihres Totems den Kessel im Osten, den Kessel in der Mitte und den Kessel im Westen der Tempelstadt En'kilah neutralisiert.", completion = "<Die Weise Aeire nimmt das Totem von Euch entgegen.>\n\nHat das Totem funktioniert? Es vorzubereiten hat uralte Magie beansprucht, die von den Weisen seit Generationen nicht mehr angewandt wurde. Von all dem überlieferten Wissen findet heute nur noch ein Bruchteil Anwendung.", sourceObjectiveStatus = "unverified-source-field" }
quests[11648] = { id = 11648, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Überredungskunst", description = "Wie praktisch, dass Ihr hier seid, {race}.\n\nIhr müsst verstehen, dass der Verhaltenskodex der Kirin Tor unser Ergreifen 'extremer' Mittel nicht duldet - selbst in Zeiten der Verzweiflung wie diesen.\n\nIhr jedoch als Außenstehender seid nicht an solche Einschränkungen gebunden und könntet jedes Mittel einsetzen, um an Informationen heranzukommen.\n\nTut, was Ihr tun müsst. Wir müssen umgehend in Erfahrung bringen, wo Lady Evanor gefangen gehalten wird!\n\nIch werde mich in der Zwischenzeit mit dem Ordnen dieser Regale beschäftigen. Oh ja, und hier, vielleicht nützt Euch dieses alte Ding...", sourceObjective = "Bibliothekar Normantis vom Bernsteinflöz möchte, dass Ihr den Neuralinjektor so lange auf den eingesperrten Beryllzauberer anwendet, bis er den Aufenthaltsort von Lady Evanor verrät.", progress = "Nun? Wisst Ihr, wo sich Lady Evanor aufhält?", completion = "Ausgezeichnet! Es war äußerst wichtig, dass wir diese Informationen erhalten.\n\nGut gemacht, {class}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11649] = { id = 11649, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Partikel der Wutentbrannten", description = "Da wir uns um ihre kleine Streiterei gekümmert haben, bleibt noch übrig, dass wir Euch und Eurer Geisterflüsterin helfen.\n\nWie Ihr seht, wurden meine Vasallen vom anhaltenden Krieg zwischen Feuer und Wasser erzürnt. Das wird sich so bald auch nicht ändern, doch für Euch wird es von Vorteil sein.\n\nUm Euch zu helfen, benötigen wir ihre Partikel. Dringt tiefer in die Ruinen ein und beschafft sie Euch von den Sturmwesen.", sourceObjective = "Beschafft 5 Sturmpartikel und bringt sie zu Imperean in den Ruinen von Eldra'nath.", progress = "Sobald Ihr die benötigten Partikel habt, werde ich sie mit einem Teil meiner Essenz verbinden. Das Resultat wird Euch das geben, was Ihr benötigt.", completion = "Ich bedauere den Verlust dieser Sturmwesen, doch ich halte mein Wort... selbst gegenüber einem Sterblichen wie Euch.\n\nNun lasst uns doch mal sehen, ob wir etwas Nützliches fertigen können.", sourceObjectiveStatus = "unverified-source-field" }
quests[11650] = { id = 11650, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nur noch ein paar Kleinigkeiten...", description = "Wie Ihr vielleicht gemerkt habt, haben wir den Landeplatz auf der südlichen Grenze eines Magnataurenbaus errichtet!\n\n<Pfiffi murmelt etwas Gemeines über Kurbelzisch.>\n\nDer Alte hat mir die Verantwortung übertragen, eine... ähhm... kreative Lösung für dieses Problem zu finden. Denn wenn wir nicht bald was gegen sie unternehmen, werden sie runterkommen und uns alle Gliedmaßen einzeln ausreißen!\n\nHier kommt Ihr also ins Spiel. Ich möchte, dass Ihr mir alles auf dieser Einkaufsliste besorgt. Bitte.", sourceObjective = "Findet Pfiffis Werkzeuge, einen überladenen Kondensatoren und eine Handvoll von Felsnars Kies. Bringt dies alles zu Pfiffi Wackelspross, die sich auf Kurbelzischs Landebahn aufhält.", progress = "Wieso fällt es mir schwer, Euch zu glauben, dass Ihr alle Gegenstände auf meiner Liste eingesammelt habt?", completion = "Nun gut, das ist schon besser! Das Einzige, was wir jetzt noch machen müssen, ist, all das Zeugs hier zusammenzubauen.\n\nJa, alles klar, als ob Ihr mir dabei helfen würdet.\n\nImmer mit der Ruhe, das wird nur 'ne Sekunde dauern, da ich ja jetzt meine Werkzeuge wieder habe!", sourceObjectiveStatus = "unverified-source-field" }
quests[11651] = { id = 11651, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Danke vielmals...", description = "Vielen Dank für all Eure Hilfe, Kumpel. Ihr könnt Grek'lor sagen, dass die Panzer einsatzbereit sind. Hoffentlich könnt Ihr diesen Ort ein für alle Mal säubern!", sourceObjective = "Sprecht mit Vernichter Grek'lor an der Echoküste.", completion = "Aufgrund des gegenwärtigen Zustands unserer Transport- und Schiffswege, konnten wir keine einzige Belagerungsmaschine zur Kriegshymnenfeste schaffen. Diese Panzer sind alle, die von der ursprünglichen Expedition übrig geblieben sind. Nun, da sie einsatzbereit sind, werdet Ihr sie dazu benutzen, die Offensive in der Ebene von Nasam zurückzuschlagen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11652] = { id = 11652, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Ebene von Nasam", description = "Springt in einen der Panzer und fahrt auf die südlich von hier gelegene Ebene von Nasam, sobald Ihr bereit seid.\n\nMacht vom Waffenarsenal des Panzers Gebrauch, um die Armee der Geißel auszuschalten. Solltet Ihr in Schwierigkeiten geraten, wird sie der \"Fleischklopfer\" in Stücke reißen und die Landminen werden ihnen den Todesstoß versetzen! Sollten Euch ein paar unserer Soldaten über den Weg laufen, dann schnappt sie Euch! Und noch etwas: Überall in dem Gebiet können Treibstofftanks gefunden werden.\n\nVersucht nah genug an das Gebäude in der Mitte heranzukommen und seht nach, was dort vor sich geht.\n\nGeht zu Höllschrei, falls Ihr das alles durchsteht!", sourceObjective = "Tötet mithilfe des Belagerungspanzers der Horde 100 Soldaten der Geißel und rettet 3 verletze Soldaten des Kriegshymnenklans auf der Ebene von Nasam. Außerdem müsst Ihr herausfinden, wer der Anführer des Angriffs der Geißel ist.\n\nMeldet Euch bei Garrosh Höllschrei in der Kriegshymnenfeste, solltet Ihr Erfolg haben.", completion = "Kel'Thuzad? Es ist also wahr - Naxxramas kehrt wieder zurück...\n\nVielleicht habe ich Euch unterschätzt, {name}. Ihr habt der Horde einen großen Dienst erwiesen. Der Kriegshäuptling wäre stolz auf Euch!\n\n\n\nWenn Kel'Thuzad diese Diener der Geißel kontrolliert, ist nicht abzusehen, was der Lichkönig sonst noch für uns auf Lager hat... Ich brauche Zeit, um mir diese neue Information durch den Kopf gehen zu lassen, {name}. Ihr könnt wegtreten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11653] = { id = 11653, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ha! ... Jetzt seid Ihr nicht mehr so groß!", description = "Das wird's ihr zeigen, <Chef/Chefin>! So, das hier müsst Ihr also für mich machen...\n\nNehmt meinen Blaster und begebt Euch in Richtung Norden nach Magmut. Wenn wir irgendeine Chance gegen diese Monster haben wollen, dann müssen wir sie einen Kopf kürzer machen... um es mal so zu sagen.\n\nUm abzuschätzen, wie effektiv das ist, müsst Ihr für mich die Magnatauren töten, während die Effekte des Blasters noch immer auf sie wirken. Die Zermalmer oder Gefährtinnen werden genügen, den Nachwuchs könnt Ihr ignorieren... die sind zu klein, um sich darüber Sorgen machen zu müssen.", sourceObjective = "Testet Pfiffis ultrafortschrittlichen prototypischen Verkürzungsblaster an 5 Zermalmern der Magmut oder Gefährtinnen von Magmutregar aus. Kehrt wieder zu Ihr zurück, sobald Ihr das erledigt habt. Sie befindet sich auf der Landebahn Kurbelzisch.", progress = "Seid Ihr Euch sicher, dass Ihr den Blaster an genug dieser monströsen Biester ausgetestet habt?", completion = "Was meint Ihr damit: Es hat nicht funktioniert?!\n\nAber... aber...\n\n<Pfiffi fängt an zu weinen.>\n\nOkay, damit können wir fertig werden. Ich bin ein großes Mädchen. Zeit, über den Tellerrand hinaus zu sehen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11654] = { id = 11654, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Säule des Blutes", description = "Als Ihr die Phiole mit Blut, die Ihr gefunden habt, untersucht, fällt Euch auf, dass der Inhalt noch immer warm ist. Das Opfer muss gerade eben erst Blut gelassen haben und noch immer am Leben sein.\n\nWelchen Nutzen hat die Geißel für Blut? Sie waren in der Vergangenheit nie an lebenden Gefangenen interessiert. Wenn Ihr den Ursprung des Blutes finden könnt, dann könnt Ihr vielleicht herausfinden, was die Geißel vorhat.", sourceObjective = "Sucht in der Säule des Blutes nach weiteren Informationen über die Phiole mit frischem Blut.", progress = "Wie... wie habt Ihr mich gefunden?", completion = "<Der Schneefährtenleser der Taunka wirkt geschwächt und kann Euch gerade noch antworten.>\n\nIch habe nicht... lange. Vielleicht... Vielleicht könnt Ihr sie aufhalten... bevor...", sourceObjectiveStatus = "unverified-source-field" }
quests[11655] = { id = 11655, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "In den Nebel hinein", description = "Auf der anderen Seite des Nebels gen Norden werdet Ihr Garroshs Landebahn vorfinden. Im Süden liegen die Ruinen meiner alten Heimat Pal'ea. Beide Orte wurden von den Kvaldir, einer uralten Macht, ausgeplündert.\n\nDiese Furcht erregenden Barbaren erschlugen gnadenlos alle meine Brüder und Schwestern und trieben Eure Leute ins Landesinnere.\n\nAlles, was von den Tuskarr aus Pal'ea übrig bleibt, sind die persönlichen Hinterlassenschaften, Relikte sozusagen, die von den Kvaldir mitgenommen wurden. Wir sind zwar kein rachsüchtiges Volk, doch Gerechtigkeit muss walten. Die Relikte der Tuskarr müssen zu mir zurückgebracht werden. Begebt Euch in den Nebel und findet sie...", sourceObjective = "Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr Kvaldir tötet und 8 Relikte der Tuskarr beschafft.", progress = "Mit Blut und Ruhm müsst Ihr dienen... Bringt die Relikte der Tuskarr wieder zurück.", completion = "<Waltor wird von Trauer ergriffen.>\n\nSchutt und Asche... das ist alles, was sie zurückgelassen haben. Ihnen muss eine Lektion erteilt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11656] = { id = 11656, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt ein Zeichen und verbrennt sie", description = "Die Magie der Tuskarr ist dem Schamanismus, wie er von Eurem Volke genannt wird, ähnlich. Während wir den Elementen im Vergleich zu Euch auf verschiedene Art und Weise dienen, ist die Macht, die wir beschwören können, eindrucksvoll.\n\n<Waltor hantiert mit einem fackelähnlichen Stab vor Euch herum.>\n\nIch möchte, dass Ihr mit dieser Tuskarrfackel in den Nebel zurückkehrt und einen Schlag gegen die Schiffe der Kvaldir führt. Ihr werdet drei ihrer Schiffe gen Norden, bei Garroshs Landeplatz auf der anderen Seite des Nebels, angedockt vorfinden, und ein weiteres in Richtung Süden, vor der Küste Pal'eas. Steckt Ihre Schiffe in Brand und setzt damit ein Zeichen! Damit es ein jeder sehen kann!", sourceObjective = "Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr die Tuskarrfackel benutzt und die Schiffe der Kvaldir bei Pal'ea und Garroshs Landeplatz verbrennt. Ihr müsst die folgenden Schiffe verbrennen: Die Schlangenschlund, die Kur Drakkar, die Bors Hammer und die Bors Amboss.", completion = "Den Kvaldir zu zeigen, dass wir ihnen Widerstand leisten, ist vielleicht das, was wir brauchen, um mein Volk in den anderen Lagern zu retten. Vielleicht werden die Kvaldir ihr Handeln überdenken, wenn sie glauben, dass es Vergeltung nach sich ziehen wird.", sourceObjectiveStatus = "unverified-source-field" }
quests[11657] = { id = 11657, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackeln fangen", description = "Da Ihr ja nun eine Fackel werfen könnt, lasst uns doch einmal sehen, ob Ihr auch eine fangen könnt!\n\nNehmt diesen Stapel unangezündete Fackeln, geht zum Freudenfeuer und werft eine davon hoch in die Luft! Fangt sie wieder auf, bevor sie auf den Boden fällt... und werft sie wieder in die Höhe! Fangt vier nacheinander und kommt wieder zu mir zurück.\n\nSeid vorsichtig! Die Fackeln sind gefährlich, wenn sie auf dem Boden aufkommen! Und fangt sie alle auf! Wenn eine davon auf den Boden fällt, müsst Ihr zurück zum Freudenfeuer und von vorn anfangen. Viel Glück.", sourceObjective = "Fangt nacheinander 4 Fackeln und sprecht anschließend mit dem Feuerschluckmeister.", progress = "Fackeln zu fangen macht jede Menge Spaß, meint Ihr nicht? Seid jedoch vorsichtig! Ihr wollt bestimmt nicht angesengt werden!", completion = "Habt Ihr Euch verbrannt? Falls ja, dann werdet Ihr es Euch in Zukunft zweimal überlegen, bevor Ihr mit Feuer herumspielt...\n\nScherz! Gut gemacht! Es ist nun offiziell: Ihr seid ein Feuerjongleur des Freudenfeuers. Nun geht und amüsiert Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11658] = { id = 11658, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Plan B", description = "Okay, keine Panik! Der Blaster hat vielleicht nicht funktioniert, aber uns stehen noch immer Möglichkeiten offen.\n\n<Pfiffi schnippt mit den Fingern.>\n\nWir werden die Aufmerksamkeit von der Landebahn weglenken! Um das zu bewerkstelligen, brauchen wir zuerst ein paar Dinge.\n\n<Wackelspross mustert Euch von Kopf bis Fuß.>\n\nStahlkiefers Karawane gleich im Westen hat dummerweise eine Abkürzung durch einen Taunkafriedhof genommen und wurde von deren wiederauferstandenen Geistern zerstört.\n\nBegebt Euch dorthin und nehmt den toten Orcs ein paar Gewänder ab. Nehmt auch eines ihrer Banner mit!", sourceObjective = "Sammelt 10 Kriegshymnenausrüstungen und ein Kriegshymnenbanner. Bringt sie zurück zu Pfiffi Wackelspross an der Landebahn Kurbelzisch.", progress = "Wir werden viele ihrer Gewänder brauchen, wenn das hier funktionieren soll... Wir müssen einfach nur etwas finden, das Euch passt!\n\nUnd dann werd' ich einfach mal einen Hauch meiner genialen Ingenieursfertigkeit hinzufügen und puff ist Euer Aussehen wie für die Rolle, die Ihr spielen müsst, geschaffen.", completion = "Fein, aber diese Kleider stinken!\n\nMich persönlich würdet Ihr nie und nimmer in solchen Fetzen rumrennen sehen. Aber wir werden aus all den Dingern eines heraussuchen müssen, dass zu Eurer... Figur passt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11659] = { id = 11659, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zerschmettert die Kugeln!", description = "Sie lassen... die Gefangenen ausbluten... geben das Blut... in diese Kugeln.\n\n<Grumm schließt kurz die Augen und lehnt seinen Kopf zurück.>\n\nDas Blut... hoch zur Nekropole gebracht... um Blutprinzen satt zu machen...\n\n<Grumm ringt nach Luft.>\n\nVer-Versprecht mir... dass Ihr... Blutkugeln... zerstört... Nachricht an... Junek.\n\n<Der Schneefährtenleser fällt in Ohnmacht.>", sourceObjective = "Zerstört 5 Blutkugeln und meldet Euch anschließend bei Schneefährtenleser Junek in Taunka'le.", completion = "Ich hatte befürchtet, dass sie Grumm gefangen genommen haben, doch ich hätte niemals gedacht, dass sie ihm solch schreckliche Dinge antun würden. Ich habe noch nie miterlebt, dass ein Krieger eine verlorene Schlacht mit der Geißel überlebt.\n\nIch danke Euch dafür, mir berichtet zu haben, welch Schicksal ihn ereilte, {name}. Er war ein mächtiger Krieger und wir werden ihn als solchen in Erinnerung behalten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11660] = { id = 11660, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Horn des uralten Seemanns", description = "Ein Leutnant der Kvaldir namens Orabus führte den Überfall auf mein Volk bei Pal'ea an. Er beaufsichtigte die Zerstörung beider Dörfer und verschwand anschließend im Nebel.\n\nIn diesen ersten Tagen ging das Wort um, dass ein Horn existiere, das Orabus den Nebelwirkern der Kvaldir zum Geschenk machte. Dieses Horn kann dazu benutzt werden, ihn, falls nötig, zu beschwören.\n\nWir müssen dieses Horn den Nebelwirkern der Kvaldir wegnehmen und Orabus heraufbeschwören. Wenn er zerstört ist, könnten sich die Barbaren vielleicht zurückziehen.\n\nSucht nach den Nebelwirkern im südlich gelegenen Pal'ea.", sourceObjective = "Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr ihm das Horn des uralten Seemanns bringt.", progress = "Findet das Horn des uralten Seemanns!", completion = "Ihr müsst mithilfe des Horns des uralten Seemanns Orabus anrufen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11661] = { id = 11661, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Orabus der Steuermann", description = "Nehmt das Horn an Euch und reist gen Westen zur Landebrücke des Kriegshymnenklans. Geht zum Ende der Landebrücke, presst das Horn an Eure Lippen und stoßt hinein. Das Geräusch sollte Orabus wecken.\n\nErschlagt das grauenhafte Ungetüm und kehrt zu mir zurück!", sourceObjective = "Waltor von Pal'ea an der Echoküste in der boreanischen Tundra möchte, dass Ihr mithilfe des Horns des uralten Seemanns Orabus den Steuermann beschwört. Erschlagt Orabus den Steuermann, sobald er beschworen ist.", completion = "Es scheint, als hätte der Verlust ihres Leutnants sie nur wachgerüttelt. Sie sind wütender und aggressiver als je zuvor!\n\n<Walter seufzt.>\n\nIhr habt getan, was in Eurer Macht stand, {class}. Das Allermindeste, was Ihr verdient habt, ist eine Entschädigung dafür, dass Ihr sie dezimiert habt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11662] = { id = 11662, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Sucht nach Karuk!", description = "Ein weiterer Überlebender von Pal'ea mit Namen Karuk hat sich auf den Weg zur Hauptbasis der Kvaldir in der boreanischen Tundra gemacht - weit südlich von hier, dort, wo der Schnee einst reichlich war. Karuk versteckt sich irgendwo auf den Klippen, die am Strand der Peitschennarbe emporragen.\n\nSucht nach Karuk und lasst ihn wissen, was Ihr hier an der Echoküste für mein Volk geleistet habt.\n\nDer sicherste Weg zu Karuk führt durch Eure Festung. Von der Kriegshymnenfeste aus folgt Ihr der Straße in Richtung Süden bis zum Strand der Peitschennarbe.", sourceObjective = "Sucht Karuk am Strand der Peitschennarbe auf.", completion = "Es war klug von Waltor, Euch zu mir zu schicken, {race}. Die Götter schenken denjenigen ein Lächeln, die Gerechtigkeit walten lassen. Ihr werdet derjenige sein, durch welchen die Boshaften ihre gerechte Strafe erhalten werden!", sourceObjectiveStatus = "unverified-source-field" }
quests[11663] = { id = 11663, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Geheime Nachrichten teilen", description = "Ich danke Euch, {class}! Die Informationen, die Ihr herausbekommen habt, sind von entscheidender Bedeutung für die Kirin Tor.\n\nKehrt umgehend zu Donathan zurück, während wir uns Gedanken darüber machen, wie wir Lady Evanor nun befreien können.", sourceObjective = "Normantis möchte, dass Ihr Euch bei Bibliothekar Donathan auf dem Bernsteinflöz meldet.", completion = "Vergebt mir, {name}. Ich weiß, dass das unangenehme Arbeit war.\n\nWäre unsere Lage hier nicht so verzweifelt, hätte ich Euch nie darum gebeten, uns auf solch einer Art und Weise beizustehen.\n\nSo... Was habt Ihr entdeckt?", sourceObjectiveStatus = "unverified-source-field" }
quests[11664] = { id = 11664, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Flucht aus dem Nebel", description = "Ich kann die Kreaturen des Nebels draußen hören. Ihre Schreie treiben mich in den Wahnsinn, doch eine Flucht will ich nicht wagen. Und wo würde ich überhaupt hingehen? Wie lange würde es dauern, bis sie mich einholen und wie die anderen hinrichten?\n\nWie weit, so frage ich mich, ist der Nebel eigentlich schon gekrochen, <Fremder/Fremde>? Hat er schon den gesamten Kontinent erfasst?\n\nWäret Ihr willens, mir dabei zu helfen, dem Nebel zu entfliehen? Ich denke, dass ich uns zurück zu meinem Vater führen kann. Ich spüre seinen Lebensgeist noch immer. Er befindet sich in der Nähe.", sourceObjective = "Begleitet Muhtoo die Jüngere und helft ihr, aus dem Nebel herauszukommen. Sprecht mit dem Ältesten Muhtoo, solltet Ihr Muhtoo die Jüngere in Sicherheit gebracht haben.", completion = "Die Winde flüstern es, {name}. Euer Name ist den Elementen bekannt. Ihr habt Muhtoo an diesem heutigen Tage einen großen Dienst erwiesen und sollt dafür belohnt werden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11665] = { id = 11665, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Krokilisken in der Stadt", description = "Hallo, <Junge/Mädchen>. Ich bin froh, dass Ihr vorbeigeschaut habt, um mit einem alten Mann zu sprechen - zuhause gibt es Schwierigkeiten.\n\nEin fliegender Händler hat neulich eine Ladung Krokiliskenbabys an ein paar leichtgläubige Kinder verkauft. Krokilisken sind wilde Bestien. Viele sind entkommen und halten sich jetzt in den Wasserwegen der Stadt verborgen.\n\nNehmt Eure stärkste Angelrute, werft sie in Sturmwind oder Orgrimmar aus und bringt einen der kleinen Teufel zurück zu mir. Ich kann es kaum erwarten, einen zu sehen.", sourceObjective = "Bringt dem alten Barlo ein Krokiliskenbaby. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Schon Kroks in den Abwasserkanälen gefangen?", completion = "Was für eine miese kleine Kreatur! Ich bin mir sicher, dass der Rokk irgendwas Leckeres aus ihr machen wird.\n\nIch mach natürlich nur Spaß.\n\n<Der alte Barlo zwinkert neckisch.>", sourceObjectiveStatus = "unverified-source-field" }
quests[11666] = { id = 11666, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Köderbanditen", description = "Ihr wisst wahrscheinlich alles über den goldenen Stachelflosser - in den Flüssen von Terokkar kommen sie recht häufig vor, außerdem sind sie eine Delikatesse für Priester. Es gibt jedoch einen, von dem Ihr noch nicht gehört habt: den schwarzen Stachelflosser.\n\nDer Fisch ist berüchtigt für seine Gerissenheit und dafür, dass er schwierig einzufangen ist. Ihr müsst Eure Angelschnur in letzter Sekunde einziehen, denn sie knabbern am Köder, bevor sie sich ihn schnappen.\n\nWerft Eure Angelrute in den Gewässern von Terokkar aus und bringt mir einen schwarzen Stachelflosser. In Seen braucht Ihr gar nicht erst zu suchen - der Flitzer kommt nur in Fließgewässern vor.", sourceObjective = "Bringt dem alten Barlo einen schwarzen Stachelflosser. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Wie fischt sich's denn heute, mein Junge?", completion = "Nun sieh mal einer an... Ihr habt einen Großen gefangen! Dieser alte Mann wird heute Abend gut essen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11667] = { id = 11667, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Eine, der entkam", description = "Feigenschimmers Matschflosser ist ein erstaunlich schneller Gründler, den man in den Gewässern von Nagrand anfindet. Sie wachsen ihr ganzes Leben lang und sind als Kämpfer sehr bekannt.\n\nVor Jahren fing ich den größten Matschflosser der Welt, da bin ich mir sicher... Doch dann brachte er meine Leine zum Reißen und kam davon.\n\nEinem Angler Eures Kalibers muss man nicht sagen, was zu tun ist - Euer Schicksal erwartet Euch an den Seen von Nagrand.", sourceObjective = "Fangt den größten Matschflosser der Welt und bringt ihn zum alten Barlo. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Sagt mir, dass Ihr ihn gefangen habt. Bitte sagt mir, dass Ihr den Mistkarpfen gefangen habt.", completion = "Da ist er! Diese Narbe würde ich immer wiedererkennen.\n\nAber um ganz ehrlich zu sein, habe ich ihn mir... größer vorgestellt. Tja - denke, dass ich ihn freilassen und es an einem anderen Tag noch einmal versuchen werde.", sourceObjectiveStatus = "unverified-source-field" }
quests[11668] = { id = 11668, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Garnelenfangen ist nicht einfach", description = "In den Seen der Zangarmarschen gibt es viele große Fische. Habt Ihr Euch jemals darüber Gedanken gemacht, was sie fressen?\n\nGarnelen - riesige Süßwassergarnelen. Der Rokk hat mir erzählt, dass man unendlich viele Garnelengerichte zubereiten kann.\n\nGarnelen sind jedoch zu klein, als dass man sie mit einer Angelschnur fangen könnte. Hier also der Trick: Schneidet eine aufgedunsene Stachelkiemenforelle auf und Ihr werdet, wenn Ihr Glück habt, die eine oder andere Garnele darin finden.", sourceObjective = "Bringt dem alten Barlo 10 riesige Süßwassergarnelen. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Was haben wir denn heute gefangen, mein Junge?", completion = "Ihr könnt mit Haken und Messer gut umgehen. Reicht mir die süßen Leckerbissen und ich werde Euch davon kosten lassen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11669] = { id = 11669, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Teufelsblutfilet", description = "Dieser alte Mann wird bald jagen gehen. Ich werde mir vor Azsharas Küste einen Mammuthai fangen.\n\nDie Sache ist nur, dass ich ein Toxin benötige, das auf einer Speerspitze haften bleibt, wenn man sich unter Wasser befindet. Um so etwas herzustellen, benötige ich die Drüsen eines giftigen Fischs: dem Teufelsblutschnapper.\n\nSolch ein abscheulicher Fisch gedeiht nur in den Gewässern der Höllenfeuerhalbinsel und des Schattenmondtals. Bringt mir das Mordsding und ihr macht aus mir einen glücklichen alten Mann.", sourceObjective = "Bringt dem alten Barlo einen monströsen Teufelsblutschnapper. Ihr könnt ihn beim Angeln am Silmyrsee nordöstlich von Shattrath finden.", progress = "Der Teufelsblut ist ein Wunder der Evolution. Er kann in allen Gewässern und sogar Lava überleben. Fischer sind seine einzigen natürlichen Feinde.\n\nGlück beim Beutefang gehabt?", completion = "Das ist der größte und hässlichste Fisch, den ich je gesehen habe. Ich kann mir gar nicht vorstellen, was Ihr als Köder benutzt habt.\n\nLegt das Biest einfach auf den Boden und ich werde mich darum kümmern, sobald ich mir sicher sein kann, dass es tot ist.", sourceObjectiveStatus = "unverified-source-field" }
quests[11670] = { id = 11670, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Es waren die Orcs, ganz ehrlich!", description = "Ich habe aus all den Gewändern, die Ihr... ähm... gefunden habt, eine Verkleidung gefertigt, mit der Ihr wie ein Orc des Kriegshymnenklans aussehen werdet. Ich hatte die geniale Idee, sie mit ein paar alten Sachen zu kombinieren, die noch von den letzten Schlotternächten herumlagen, also sollte sie idiotensicher sein!\n\nHier, in diesem Sack befindet sich die Verkleidung und das Banner, das Ihr gefunden habt. Begebt Euch ins Innere von Magmut und erschlagt Magmutregar, den Häuptling der Magnatauren.\n\nWenn Ihr sie davon überzeugen wollt, dass sie ihre Aufmerksamkeit den Orcs des Kriegshymnenklans schenken sollen, werdet Ihr das Banner aufstellen müssen, solange Ihr verkleidet seid.", sourceObjective = "Spießt Magmutregars Leiche mit dem Kriegshymnenbanner auf, während Ihr als Orc des Kriegshymnenklans verkleidet seid. Kehrt anschließend zu Pfiffi Wackelspross zurück und bringt die Verkleidung mit. Sie befindet sich auf der Landebahn Kurbelzisch.", progress = "Es ist also vorbei? Ihr habt die Drecksarbeit gemacht und sie den Orcs vom Außenposten Bor'gorok in die Schuhe geschoben.", completion = "Du lieber Himmel, Ihr habt es getan!\n\nNun gut, diese lästigen Magnatauren und ihre Schneeboldlakaien sollten ihre Aufmerksamkeit auf die Horde richten.\n\nWie kann ich mich dafür jemals bei Euch erkenntlich zeigen, {name}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11671] = { id = 11671, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Wettlauf gegen die Zeit", description = "Es stimmt also: Sie haben sie.\n\nKeine Frage, was getan werden muss, {race}. Wir WERDEN sie befreien.\n\nIch muss hier bleiben und bei den Rettungsvorbereitungen helfen. Also wende ich mich noch einmal an Euch; dieses Mal mit der Bitte, den Gefängnisschlüssel zu finden. Alles, was wir über diese Salrand wissen, ist, dass sie nicht verletzt werden kann, solange ihr Schild noch intakt ist.\n\nWir haben einen speziellen Sprengsatz so präpariert, dass er sie ihres Schutzes berauben wird, damit Ihr Eure Pflicht tun könnt. Kehrt zu mir zurück, wenn Ihr den Schlüssel habt.\n\nBeeilt Euch, {name}. Lady Evanor erleidet Qualen!", sourceObjective = "Donathan vom Bernsteinflöz hat Euch damit beauftragt, mithilfe des Beryllschilddetonators den Schild auf der Beryllspitze zu zerstören. Danach sollt Ihr Salrand besiegen und ihr den Schlüssel abnehmen, den sie bei sich trägt.", progress = "Habt Ihr Salrands Schlüssel bei Euch?", completion = "Zerbrochen?\n\nLasst mich einmal sehen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11672] = { id = 11672, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eingezogen", description = "Ihr seid zur Einberufung gekommen, richtig? Normalerweise müsstet Ihr genauso wie alle anderen Rekruten in einer Reihe stehen. Normalerweise hättet Ihr Pech, weil das Rekrutierungsregister abhanden gekommen ist und ich niemanden aufnehmen kann, bis die neuen Bücher ankommen.\n\nDoch glücklicherweise, {name}, habe ich von Euch und Euren Taten in der Scherbenwelt gehört. Um ehrlich zu sein, seid Ihr den anderen Trotteln bei Weitem überlegen. In Reih und Glied stehen ist nichts für Euch.\n\nGeht zur Kaserne und sprecht mit General Arlos. Er wird mehr als froh darüber sein, jemanden Eures Kalibers zu treffen.", sourceObjective = "Trefft Euch mit General Arlos im Inneren der Kaserne in der Valianzfeste.", completion = "Wir haben Eure Ankunft erwartet, {name}. Willkommen in Nordend.", sourceObjectiveStatus = "unverified-source-field" }
quests[11673] = { id = 11673, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Holt mich hier raus!", description = "Ich habe gewusst, dass sie früher oder später jemanden schicken würden... später natürlich, wie sich zeigt.\n\nIch bin hierher gekommen, um mit den Schneebolden zu verhandeln, doch ihr wichtigster Schamane Kaganishu hat sich stattdessen dazu entschlossen, dass ich wohl besser als Leckerbissen für Magmutregar geeignet wäre.\n\nWartet... Wie bitte?! Sie haben Euch gar nicht geschickt?!\n\nHABEN SIE MICH ETWA VERGESSEN?!\n\nOkay, Ihr seid jetzt hier - das ist das einzig Wichtige.\n\nSobald Ihr diese Kette zerbrochen habt, werden wir uns auf den Weg zurück zur Landebahn machen. Dann könnt Ihr Kurbelzisch mitteilen, dass ich heil zurück bin.\n\nDas heißt, falls er sich überhaupt an mich erinnert.", sourceObjective = "Bringt Bonker Wechselvolt in Sicherheit und meldet Euch bei Kurbelzisch Vollgas auf der Landebahn Kurbelzisch.", completion = "Hä? Was?\n\nBonker wer?\n\nIch hab' keine Ahnung, von wem Ihr da sprecht, aber ich nehm' Euch beim Wort. Wenn Ihr ihn oder sie aus Magmuts Grube befreit habt, dann nehme ich mal an, Ihr habt Euch eine Belohnung verdient.\n\nLasst mich einmal nachsehen, was hier so herumliegt.", sourceObjectiveStatus = "unverified-source-field" }
quests[11674] = { id = 11674, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Weise Hochmesa wird vermisst", description = "Viele neue Rätsel erzählt man sich nun landauf, landab. Eine unserer Weisen, Hochmesa, ist törichterweise mit einem Fernläufer gen Norden gegangen, um etwas Merkwürdiges bei den Höhlen des Todes zu untersuchen.\n\nWas sind das für Höhlen, fragt Ihr? Sie sind ein Heiligtum der Magnatauren, wo diese sich im Alter hinbegeben, um zu sterben. Vor ein paar Tagen sah sie in deren Nähe etwas vom Himmel fallen.\n\nWenn Ihr ein Freund der Taunka seid, so möchte ich Euch bitten, sie zu finden und ihr zu helfen. Sie ist nicht so dickköpfig, dass sie Eure Hilfe ablehnen würde.", sourceObjective = "Findet die Weise Hochmesa in der Nähe der Höhlen des Todes.", completion = "Die Großmutter hat Euch geschickt? Sie muss von mir enttäuscht sein.\n\nDoch als ich das große Objekt vom Himmel fallen sah, konnte ich nicht auf eine ganze Gruppe Fernläufer und Schneefährtenleser als Begleitung warten. Wissen wartet auf niemanden.", sourceObjectiveStatus = "unverified-source-field" }
quests[11675] = { id = 11675, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein würdiges Ende", description = "Die Magnatauren bei den Höhlen des Todes haben sich mit einer Seuche infiziert. Wir müssen die Ursache finden, doch zuerst müssen wir ihrem Leiden ein Ende setzen.\n\n{race}, Ihr müsst in Richtung Norden die Hänge vor uns hinaufgehen und so viele der armen Kreaturen erschlagen wie nur möglich.", sourceObjective = "Erschlagt 10 verseuchte Magnatauren und kehrt anschließend zur Weisen Hochmesa gleich südlich der Höhlen des Todes zurück.", completion = "Was können wir sonst machen, außer sie von ihrem Leiden zu befreien? Auf jeden Fall kamen sie hierher, um zu sterben, also trauert nicht um sie. Zumindest habt Ihr sie in Würde sterben lassen.\n\nNun müssen wir der Ursache der Seuche ein Ende bereiten.", sourceObjectiveStatus = "unverified-source-field" }
quests[11676] = { id = 11676, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gnadenvolle Freiheit", description = "Die Soldaten, die sie verschont haben, werden in Käfigen festgehalten, die überall auf diesem Ackerland verstreut herumstehen. Dank einiger Meisterstreiche in Sachen Diebstahl konnten wir zwar an ein paar Schlüssel gelangen, doch wir kommen einfach nicht an die Gefangenen heran, ohne uns Angriffen auszusetzen.\n\nWir benötigen Euer \"Geschick\", um diese Schlüssel zu sichern und die Gefangenen zu befreien. Schlagt den Nekrolords und Monstrositäten die Schädel ein und nehmt ihnen die Schlüssel ab. Befreit anschließend die Gefangenen mit diesen Schlüsseln.", sourceObjective = "Schattenpirscher Canarius auf den Höfen des Kriegshymnenklans möchte, dass Ihr 5 Gefangene der Geißel befreit.", completion = "Jeder befreite Gefangene ist eine untote Monstrosität weniger, um die wir uns kümmern müssen, {name}. Ihr habt der Horde einen großen Dienst erwiesen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11677] = { id = 11677, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Haltet die Seuche auf", description = "Ich bin davon überzeugt, dass die Seuche von etwas ausgeht, das sich in den Höhlen dort oben befindet.\n\n{class}, nehmt diese Samen. Normalerweise verwende ich sie zum Schutz gegen die Geißel, doch vielleicht kann man mit ihnen auch die Höhle von all jenen Übeln befreien, die dort vor sich gehen.\n\nFindet den Quell dieser Seuche und werft sie dort hinein.", sourceObjective = "Die Weise Hochmesa gleich südlich der Höhlen des Todes möchte, dass Ihr Hochmesas reinigende Samen auf den Seuchenkessel in den Höhlen des Todes anwendet, um ihn zu neutralisieren.", completion = "<Die Weise lässt ihren Kopf hängen und seufzt vor Erleichterung.>\n\nDas ist ein guter Anfang. Wenn es doch nur unser einziges Problem wäre.", sourceObjectiveStatus = "unverified-source-field" }
quests[11678] = { id = 11678, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Findet Borstenhorn", description = "Borstenhorn hätte schon längst zurückkommen sollen.\n\nDer andere Grund, wieso wir hierher gekommen sind, war die Untersuchung des Gebäudes der Geißel im Westen, das vom Himmel gefallen ist. Er ist impulsiv und hat sich höchstwahrscheinlich in Schwierigkeiten gebracht.\n\n{name}, geht dorthin und findet ihn, bitte.", sourceObjective = "Sucht in Talramas nach Fernläufer Borstenhorn.", completion = "Ich bin... nicht... lange für diese... Welt, kleiner {race}.", sourceObjectiveStatus = "unverified-source-field" }
quests[11679] = { id = 11679, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Den Schlüssel neu schmieden", description = "Verspätungen, Verspätungen... genau das, was wir uns gerade nicht leisten können!\n\nSo sehr ich es hasse, Lord Surristrasz zu stören, er ist die einzige Hoffnung, unsere geliebte Evanor zu retten.\n\nBringt die Schlüsselfragmente zu ihm und hofft, dass er guter Laune ist.\n\nBeeilt Euch, {class}, unsere Angriffstruppe wartet.", sourceObjective = "Donathan möchte, dass Ihr mit Surristrasz auf dem Bernsteinflöz sprecht.", progress = "Du wagst dich in meine Nähe, Sterblicher?\n\nBete und hoffe um deiner ungeborenen Kinder Willen, dass dein Anliegen die Mühe wert ist.", completion = "Die frivolen Spiele, die du hier treibst, führen zu nichts...\n\nDu und deine Verbündeten in Dalaran tappen im Dunkeln, während die Zukunft dieser Welt im Begriff ist, der Dunkelheit zu verfallen.\n\nUnd dennoch, die Sache könnte meinen Drachen die nötige Unterhaltung bieten.\n\nZeig mir diesen Schlüssel...", sourceObjectiveStatus = "unverified-source-field" }
quests[11680] = { id = 11680, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Jemanden unter seine Fittiche nehmen", description = "Der Schlüssel ist neu geschmiedet.\n\nNun hört meinen Rat, {race}. Vollbringt die Tat oder krepiert beim Versuch, denn sollte einem meiner Drachen auch nur eine einzige Schuppe gekrümmt werden, werde ich Euch persönlich zur Rechenschaft ziehen.\n\nHinfort mit Euch.", sourceObjective = "Gebt Kriegsmagier AnzimSalrands Schlüssel, wenn Ihr bereit seid, Evanor zu befreien.\n\nBereitgestellter Gegenstand:", completion = "Das ist es - der Schlüssel ist unser!", sourceObjectiveStatus = "unverified-source-field" }
quests[11681] = { id = 11681, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Evanor retten", description = "Endlich greifen wir an!\n\nSobald wir den Platz gesäubert haben, werde ich den Schlüssel verwenden.\n\nIhr müsst dafür sorgen, dass Lady Evanor sicher ist, nachdem sie befreit wurde.\n\nBeeilt Euch, lasst uns losfliegen!", sourceObjective = "Anzim vom Bernsteinflöz möchte, dass Ihr gemeinsam mit seinen Kriegsmagiern losfliegt, um Lady Evanor auf der Beryllspitze zu befreien. Danach sollt Ihr Euch bei Ihr im Magierturm auf dem Bernsteinflöz melden.", completion = "Eure Heldentaten werden nicht vergessen werden, {class}.\n\nBitte, nehmt dies und habt meine aufrichtige Dankbarkeit.", sourceObjectiveStatus = "unverified-source-field" }
quests[11682] = { id = 11682, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Drachengespräche", description = "Ich bin mir über Eure jüngsten Taten im Klaren, {name}, und möchte Euch noch einmal dafür danken.\n\nWas diese örtliche Bedrohung angeht, haben wir alles erfahren, was wir über sie erfahren können. Doch nun zu wichtigeren Angelegenheiten...\n\nAzeroth braucht Euch. Die Region gleich westlich von hier ist das Zentrum einer ernsten Krise.\n\nIch werde Lord Surristrasz über die Details in Kenntnis setzen. Ihr müsst umgehend mit ihm sprechen.\n\nViel Glück, <Freund/Freundin> von Dalaran.", sourceObjective = "Lady Evanor hat Euch ausgesandt, um mit Surristrasz vom Bernsteinflöz zu sprechen.", completion = "So, {race}. Wir werden wieder miteinander sprechen.\n\nWenn ich meinen Bericht erzählt habe, werdet Ihr Euch wünschen, ihn nie gehört zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11683] = { id = 11683, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gefallene Nekropole", description = "Von der gefallenen Nekropole im Westen kann man nur annehmen, dass sie noch immer voll von Schergen der Geißel ist.\n\nWährend Ihr in Talramas seid, {class}, möchte ich Euch bitten, alle Diener des Lichkönigs zu erledigen, die Ihr dort und in den umgebenden Teichen finden könnt.", sourceObjective = "Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zur Weisen Hochmesa zurück, welche sich gleich südlich der Höhlen des Todes befindet.", completion = "Habt Dank, {name}.\n\nDer Lichkönig und seine Geißel liegen auf Nordend wie eine Pest. Wir dürfen nicht ruhen, ehe alle vollkommen vernichtet sind und wir ihm den Garaus gemacht haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11684] = { id = 11684, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufspüren der Schlundlöcher", description = "Könnt Ihr die Beben in der Erde spüren?\n\nDie Neruber der Geißel bewegen sich tief unter der Erde. Sie sind im Südwesten, in den Geysirfeldern, wieder hervorgekommen und schikanieren die von Häuptling Orkan ausgeschickten Patrouillen.\n\n<Der Taunkaälteste bietet Euch eine abgenutzte Karte an.>\n\nVielleicht kann ein Einzelner dort siegen, wo die Patrouillen versagt haben. Nehmt dies mit Euch zu den Geysirfeldern und tragt die Positionen der nerubischen Schlundlöcher ein.", sourceObjective = "Großvater Mahan in Taunka'le möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt.", progress = "Habt ihr die Positionen der Schlundlöcher eingetragen?", completion = "<Großvater Mahan nimmt die Karte entgegen, bewegt sich aber kein Stück, um sie zu untersuchen...>\n\nEure Informationen werden wir später einsetzen können, wenn wir bereit sind, den Plan umzusetzen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11685] = { id = 11685, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Herz der Elemente", description = "Jetzt, da wir die genaue Position der Schlundlöcher der Neruber kennen, können wir diese einstürzen lassen, um die Offensive der Geißel zum erliegen zu bringen und ihre Streitkräfte hart zu treffen. Windzähmerin Barah kennt einen Weg, Elementare zu zügeln, um die von den Nerubern benutzten Tunnel zu zerstören, doch sie wird Eure Hilfe benötigen.\n\nSüdöstlich des Dorfes, nahe der Küste hinter den gefrorenen Weiten werdet Ihr eine Region finden, die von gefrorenen Erdelementaren beherrscht wird. Die Herzen dieser Elemente sind genau das, was Windzähmerin Barah braucht.", sourceObjective = "Bringt 5 Elementarherzen zu Windzähmerin Barah in Taunka'le.", progress = "Großvater Mahan hat mir mitgeteilt, dass Ihr zugestimmt habt, dabei zu helfen, die Tunnel zum Einsturz zu bringen.", completion = "Das sollte ausreichen, um den Kern eines mächtigen Elementar zu erschaffen, doch Stein allein wird meinem Elementar kein Leben einhauchen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11686] = { id = 11686, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Höfe des Kriegshymnenklans", description = "Luthers Notizen nach benutzt die Geißel diesen Ort jetzt als Brutstätte für die Monster, die man über die Felder trampeln sieht.\n\n<Ickoris schaudert es.>\n\nDiese Monster waren einst Orcs... Tauren...\n\nBevor wir einen Plan schmieden können, benötigen wir mehr Informationen. Ich möchte, dass Ihr drei Stätten untersucht, die von der Geißel heimgesucht werden: die Kornkammer des Kriegshymnenklans südwestlich von uns, Torps Bauernhof direkt in unserem Westen und der alte Schlachthof des Kriegshymnenklans nördlich von hier.\n\nKehrt zu mir zurück, sobald Ihr diese ausgespäht habt.", sourceObjective = "Schattenpirscher Ickoris bei den Höfen des Kriegshymnenklans möchte, dass Ihr die Kornkammer des Kriegshymnenklans, Torps Bauernhof und den Schlachthof des Kriegshymnenklans ausspäht.", completion = "Das ist weitaus schlimmer als das, was in Luthers Tagebuch stand. Dieser Ort wimmelt von Schergen der Geißel und sie infizieren alles, was sie anfassen.\n\n<Ickoris nickt.>\n\nEs wird noch schlimmer - wenn man sich das überhaupt vorstellen kann...", sourceObjectiveStatus = "unverified-source-field" }
quests[11687] = { id = 11687, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Doktor und der Lichfürst", description = "Es gibt zwei... die... getötet... werden müssen.\n\nDer Doktor und... der Lichfürst... sind... dort oben. Findet sie... vernichtet sie… bevor...\n\n... es... zu spät ist...", sourceObjective = "Vernichtet Doktor Klingengrinser und Lichfürst Frostwinter und kehrt anschließend zur Weisen Hochmesa zurück. Sie befindet sich gleich südlich der Höhlen des Todes.", completion = "Borstenhorn ist tot?!\n\nIch hätte ihn niemals alleine dorthin gehen lassen dürfen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11688] = { id = 11688, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verdammte, dreckige Schweine", description = "Seht sie Euch nur an! Meine wunderschönen Kodos können sich nicht gegen diese dreckigen Schweine verteidigen, sie sind hilflos! Ihr müsst mir etwas Zeit verschaffen, {race}. Ich denke, ich kann die Kodos von dieser Krankheit heilen, aber Ihr müsst diese untoten Schweine von ihnen fern halten, sonst bleibt kein Kodo mehr übrig, um geheilt zu werden!\n\nBewegt Euch da raus und bringt diese Schweine unter die Erde - dauerhaft!", sourceObjective = "Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 10 untote Schweine tötet.", progress = "Ich brauche mehr Zeit! Haltet diese Schweine von meinen Kodos fern!", completion = "Ich glaube, ich bin soweit, {race}!", sourceObjectiveStatus = "unverified-source-field" }
quests[11689] = { id = 11689, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Schlechte Nachrichten überbringen", description = "Die Großmutter wird davon erfahren müssen, {name}.\n\nWürdet Ihr bitte nach Taunka'le zurückkehren? Sagt Ihr, dass ich bald nachkommen werde.", sourceObjective = "Sprecht mit Großmutter Taiga in Taunka'le.", completion = "Welch Nachricht überbringt Ihr mir von Hochmesa?\n\n<Ihr erklärt, was Ihr wisst, und überbringt der Großmutter die schlechten Nachrichten über Fernläufer Borstenhorn.>\n\nMein... mein Enkel!\n\n<Die Großmutter gibt sich Mühe, die Fassung zu wahren.>\n\nEr starb einen ehrenhaften Tod, den Tod eines Taunka!\n\nIhr wart der Letzte, der bei ihm gewesen ist, {name}. Also soll er auf ewig ein Teil von Euch sein. Habt meinen Dank dafür, seine letzten Wünsche erfüllt zu haben.", sourceObjectiveStatus = "unverified-source-field" }
quests[11690] = { id = 11690, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bringt sie lebend zurück", description = "Nehmt diese Reittrense, {name}. Ihr werdet merken, dass ich einen kleinen Medizinspender in das Mundstück eingearbeitet habe. Das Ding wird die Infektion heilen, sobald der Kodo darauf beißt. Sobald Ihr sie geheilt habt, müsst Ihr sie nach Hause reiten. Sie werden nicht bei Kräften sein, also müsst Ihr sie sanft hierher bewegen.\n\nBringt mir meine Babys zurück, {name}!\n\nEins noch, Ihr habt 10 Minuten! Das Gegenmittel im Inneren der Trense bleibt nur so lange wirksam.", sourceObjective = "Bauer Torp bei den Höfen des Kriegshymnenklans möchte, dass Ihr 8 infizierte Kodobestien rettet.", progress = "Holt sie aus diesen von der Geißel verseuchten Feldern!", completion = "Ihr seid ein wahrer Held, {name}. Ohne Euch wären meine Kodos da draußen gestorben. Ihr habt meinen Dank und den Dank aller Soldaten und Reisenden, die diese Kodos benutzen werden, um unsere Stellung in Nordend zu stärken!", sourceObjectiveStatus = "unverified-source-field" }
quests[11691] = { id = 11691, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Beschwört Ahune", description = "Ich und meine Schamanen haben all unsere Kräfte für die Schlacht mit dem Frostfürsten gesammelt. Ihr werdet die Faust der Erdenmutter sein, {name}.\n\nNehmt dieses Magmatotem und benutzt es in der Nähe des Eisbrockens im Nordosten. Ahune leitet seine Kraft durch diesen Brocken. Unsere Hoffnung ist, dass das Totem seine Verbindung mit der Elementarebene durchtrennen wird.\n\nWenn wir Glück haben, dann könnten wir ihn vielleicht besiegen.\n\nMacht Euch bereit, {name}. Wenn Ahune uns gegenübersteht, wird sein Zorn gewaltig sein.", sourceObjective = "Bringt dieses Magmatotem des Irdenen Rings zum Eisbrocken.", progress = "Dieser Eissplitter lässt das tiefe  Rumpeln und Knacken gewaltiger Gletscherzungen erklingen. Seine Kälte lässt Eure Gedanken erstarren und treibt sie in einen leblosen, endlosen Winter.", completion = "Das Magmatotem zerbirst in drei einzelne Flammen, als Ihr es in die Nähe des Eisbrockens bringt. Der Brocken schimmert - und löst sich anschließend in Luft auf...", sourceObjectiveStatus = "unverified-source-field" }
quests[11692] = { id = 11692, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bei Bixie einchecken", description = "Ihr seid <ein gemachter Held/eine gemachte Heldin>. Ich hab' noch ein anderes Problem!\n\nMeine Chefin Tinky ist gemeinsam mit Bixie Zangkeuler nach Osten gegangen und ich bekomme das Sendesignal von diesem Dings einfach NICHT zum Laufen! Tinky ist die Einzige, die es reparieren kann, und es muss wirklich einwandfrei laufen.\n\nDenkt Ihr, dass Ihr sie finden könntet? Bixie meinte irgendwas davon, einem alten Magnatauren zu einem Ort namens 'Die Höhlen des Todes' folgen zu wollen.\n\nIch schätze mal, dass Ihr sie dort finden werdet.\n\nSprecht mit Kara Sternengala; sie wird dafür sorgen, dass man Euch dorthin bringt.", sourceObjective = "Mordle Zahnrad möchte, dass Ihr Bixie Zangkeuler aufsucht, die sich südlich der Höhlen des Todes befindet.", completion = "Womit kann ich dienen, {class}?", sourceObjectiveStatus = "unverified-source-field" }
quests[11693] = { id = 11693, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Oh, großartig... verseuchte Magnatauren!", description = "Tinky und ich sind hierher gekommen, um Jagd auf einen alten Magnatauren zu machen. Offenbar sind diese Höhlen dort oben der Ort, den sie zum Sterben aufsuchen.\n\nAuf keinen Fall hatten wir gewusst, dass sie dort drin verseucht werden. Wir können hier keine umherstreunenden verseuchten Wesen gebrauchen - ist nicht gesund.\n\nSagt mal, wieso könnt Ihr nicht ein paar von den Dingern beseitigen, während ich versuche herauszufinden, wie es weitergehen soll?", sourceObjective = "Tötet 10 verseuchte Magnatauren. Kehrt anschließend zu Bixie Zangkeuler südlich der Höhlen des Todes.", completion = "Gute Arbeit, aber ich würde mir an Eurer Stelle bei nächster Gelegenheit eine Dusche gönnen.\n\nNa, dann lasst uns mal das Problem hier draußen richtig anpacken.", sourceObjectiveStatus = "unverified-source-field" }
quests[11694] = { id = 11694, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Irgendetwas geht in diesen Höhlen vor", description = "Während Ihr Euch also um diese verseuchten Biester gekümmert habt, hab' ich mich mal in diesen Höhlen dort oben umgesehen.\n\nSie werden von Kultisten verseucht!\n\nDa gibt es einen Kessel, in dem sie irgend so ein übles Zeug brauen. Ich hab' ein Pulver bei mir, das ich normalerweise als Gegengift verwende und das ich mit ein paar anderen Sachen vermischt habe. Ich denke, dass sich damit das Gebräu neutralisieren lässt!\n\nNehmt es mit Euch, geht zu einer der Höhlen dort oben und seht nach, ob es funktioniert.", sourceObjective = "Bixie Zangkeuler möchte, dass Ihr Bixies Desinfektionspuder in den Seuchenkessel in den Höhlen des Todes schüttet, um ihn zu neutralisieren. Bixie schleicht gleich südlich der Höhlen des Todes herum.", progress = "Die Zeit verrinnt, {class}. Das Letzte, was wir gebrauchen können, sind verseuchte Magnatauren, gegen die wir kämpfen müssen.\n\nDie Normalen sind schon schlimm genug!", completion = "Ich hab' gewusst, dass etwas in Euch steckt. Nun, es gibt da noch eine Sache, um die Ihr Euch für mich kümmern müsst.", sourceObjectiveStatus = "unverified-source-field" }
quests[11695] = { id = 11695, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Das Horn des Elementarfurors", description = "Ich kann aus diesen Stücken leblosen Steins das Ebenbild eines Elementars erschaffen, doch ihm Leben einzuhauchen, ist etwas anderes. Um das zu tun benötigen wir Hilfe und ein bisschen Glück.\n\nDer Legende nach soll einst ein großer Held der Taunka auf der Suche nach einem uralten Artefakt namens \"Horn des Elementarfurors\" gewesen sein. Ich werde Euch eine Schriftrolle mit der Abschrift dieser Geschichte leihen. Ich weiß zwar nicht, ob etwas Wahres an ihr dran ist, doch uns bleibt nichts anderes übrig. Falls die Legende stimmen sollte, dann könnten die Hornteile auf den Flutebenen nördlich und südwestlich des Dorfes zu finden sein.", sourceObjective = "Tötet Häuptling Burbelgobbel und Häuptling Gurgelboggel, nehmt ihnen die untere und obere Hornhälfte ab und bringt sie zu Windzähmerin Barah in Taunka'le.", progress = "Konntet Ihr das Horn finden? Ist die Legende wahr?", completion = "<Barah nimmt beide Hälften des Horns entgegen und versucht, sie zusammenzufügen.>\n\nSturmhuf wäre stolz auf Euch, {name}. Vielleicht werde ich, wenn wir uns um die Geißel gekümmert haben, das Horn mit auf eine Pilgerfahrt zu Sturmhufs Grab nehmen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11696] = { id = 11696, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ahune ist hier!", description = "{name}, Eure Gegenwart ist ein Segen. Ahune befindet sich in den Höhlen und sammelt Kräfte für seinen Angriff. Truppen des Irdenen Rings wurden vorausgeschickt, doch alleine werden sie ihn nicht besiegen können.\n\nErkundet die Höhlen, {name}. Findet unsere Schamanen des Irdenen Rings und meldet Euch bei ihrer Anführerin, Luma Himmelsmutter. Mit vereinten Kräften werden wir Ahune vielleicht besiegen können, bevor es zu spät ist.", sourceObjective = "Findet Luma Himmelsmutter in den Sklavenunterkünften.", completion = "Ahunes Kälte breitet sich in diesen Höhlen aus, {name} - ein Vorgeschmack des eisigen Todes, der uns erwarten würde, sollte er seine volle Stärke erlangen. Erdenmutter sei Dank, dass sie Euch gesandt hat.", sourceObjectiveStatus = "unverified-source-field" }
quests[11697] = { id = 11697, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mist, Tinky ist in die Nekropole gelaufen!", description = "Ich habe Tinky gewarnt, nicht alleine loszuziehen, doch sie musste ja einfach die verunglückte Nekropole im Westen untersuchen.\n\nIch bin 100% sicher, dass diese Kultisten aus diesem Ding rausgekommen sind, weshalb ich jetzt 100% sicher bin, dass Tinky in Schwierigkeiten steckt!\n\nSie ist die Top-Ingenieurin der Landebahn. Ohne sie sind wir verdammt!\n\nIch würde ja selber gehen, doch eines dieser Dinger hat mir schon wieder Fesseln angelegt, bevor ich verschwinden konnte. {name}, falls sie irgendwer da rausholen kann, seid Ihr es!", sourceObjective = "Sucht Tinky Dochtpfiff im Inneren von Talramas.", completion = "Hey Ihr! Wer seid Ihr?\n\nBixie hat Euch geschickt? Ausgezeichnet, dann holen wir mich mal hier raus!", sourceObjectiveStatus = "unverified-source-field" }
quests[11698] = { id = 11698, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Man kann auch gleich die Geißel auslöschen", description = "Falls die Kultisten oben in diesen Höhlen den Absturz überlebt haben, dann kann man nur annehmen, dass die gefallene Nekropole im Westen noch immer voll von Schergen der Geißel ist. Es gibt sie bestimmt auch massenweise bei den Teichen, die sich dort befinden!\n\nWährend Ihr in Talramas seid, {class}, meint Ihr, Ihr könntet alle Lakaien des Lichkönigs, die Ihr dort findet, platt machen?", sourceObjective = "Vernichtet bei den Eiterteichen und in Talramas 20 Diener der Geißel jeglicher Art. Kehrt dann zu Bixie Zangkeuler zurück, welche sich gleich südlich der Höhlen des Todes befindet.", completion = "Danke, {name}.\n\nDer Lichkönig und seine Geißel sind wirklich Furcht einflößend, doch wir können nicht ruhen, ehe sie nicht in frischen Gräbern ruhen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11699] = { id = 11699, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Bin in diesem verdammten Käfig gefangen... aber nicht mehr lange!", description = "Die Kultisten haben mich in diesen Käfig gehext und er hat kein Türgitter. Sie wussten jedoch nicht, dass ich der Hauptingenieuer für Transmaterie auf der Landebahn bin!\n\nMit Eurer Hilfe und ein wenig Schmalz werde ich schon bald hier raus sein.\n\nIch werde einen Motorkernkristall von einem der Ghule hier benötigen, ein magisches Gyroskop ihrer Doktoren und einen Geißelsteuerungsstein von ihrem Lichfürsten ganz oben.\n\nMit dem ganzen Zeug sollte ich ein Portalgerät basteln können, mit dem ich auf gnomische Art entkommen und wieder zu Kurbelzisch gelangen kann!", sourceObjective = "Findet einen Motorkernkristall, ein magisches Gyroskop und einen Geißelsteuerungsstein. Liefert die Gegenstände anschließend bei Tinky Dochtpfiff in Talramas ab.", progress = "Habt Ihr das ganze Zeug mitgebracht?", completion = "Hervorragend! Jetzt nur noch eine Modifikation hier und eine kleine Änderung da...", sourceObjectiveStatus = "unverified-source-field" }
quests[11700] = { id = 11700, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lasst es Bixie wissen", description = "Mein böser Zwilling ist irgendwo da draußen.\n\nIch bin mir ziemlich sicher, dass sie noch nicht zurück bei der Landebahn ist. Vielmehr, wo immer es sie hin verschlagen hat, sie ist jetzt an einem Ort, an dem es viel kälter ist als hier. Doch ich konnte sie nur für einen kurzen Moment \"fühlen\".\n\nNun gut, ich werde das Ding neu konfigurieren und mich selbst schon bald zurück zur Landebahn teleportieren. Meint Ihr, Ihr könntet in der Zwischenzeit nach Osten zu Bixie gehen und sie wissen lassen, dass ich sie dort treffen werde?\n\nDanke, {name}!", sourceObjective = "Sprecht mit Bixie Zangkeuler gleich südlich der Höhlen des Todes.", completion = "Tinky hat einen bösen Zwilling?!\n\nNun, wenn sie sagt, dass es ihr gut geht und dass sie bald selbst zurück zur Landebahn kommt, soll mir das Recht sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11701] = { id = 11701, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Zurück zum Landeplatz", description = "Nun gut, ich denke, dass ich mich auch wieder auf den Weg zurück zum Landeplatz mache. Mit meiner Verletzung am Bein werde ich sicherlich ein wenig länger brauchen.\n\nSagt mir, denkt Ihr, dass Ihr vor mir dort ankommen und dem alten Kurbelzisch die guten Neuigkeiten überbringen könntet? Ich wette, dass Euch auch eine Belohnung winken wird.\n\nDanke, {name}!", sourceObjective = "Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch in der boreanischen Tundra.", completion = "Das sind Neuigkeiten, {name}. Ein Wunder, dass bei all den Problemen hier draußen der Landeplatz nicht schon längst von der Landkarte getilgt wurde.\n\nDoch Dank Euch, gibt es nun einen Gegner weniger, um den wir uns den Kopf zerbrechen müssen.\n\nFür Anlässe wie diesen hier habe ich ein paar spezielle Gegenstände aufgehoben. Wieso sucht Ihr Euch nicht einfach einen aus?", sourceObjectiveStatus = "unverified-source-field" }
quests[11702] = { id = 11702, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Mrgl-Mrgl", description = "Das wiad sich schräg anhöan, {class}, aber da wiad es einen Murloc geben, dea fragen wiad, ob wia ihm helfen könn'n!\n\nMan nennt ihn König Mrgl-Mrgl, dea Anführa dea Wintaflossen. Er und seine Leute wurden aus dem Dorf gejagt und sie wollan, dass Ia kommt und ihn'n helft.\n\nIa findat ihn, wenn Ia nach Westan geht und de Klippen runterlauft. Ea hängt im Süden dea Zuflucht dea Winterflossen ab.", sourceObjective = "Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen.", completion = "Endlich - Hilfe! Und dem Anschein nach Horde.\n\nDas passt... Eure Leute sind sehr geübt, wenn es ums Kämpfen geht. Davon werden wir jede Menge benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11703] = { id = 11703, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gelangt zu Getry", description = "Der für die Entführung und Verwandlung unserer Hordesoldaten in untote Monster verantwortliche Agent der Geißel nutzt die nordwestliche Farm als Brutstätte. Schattenpirscher Getry hat die ganze letzte Woche die Machenschaften dieses Monsters verfolgt und ein paar entscheidende Informationen gesammelt, mit deren Hilfe wir die Bedrohung womöglich aus der Welt schaffen können.\n\nGelangt zu Getry und seht nach, ob Ihr verhindern könnt, dass dort am laufenden Band neue Diener der Geißel produziert werden. Ihr findet Getry bei dem verlassenen Turm an der nordwestlichen Grenze dieser Höfe.", sourceObjective = "Geht zu den Höfen des Kriegshymnenklans und findet Schattenpirscher Getry.", completion = "<Getry mustert Euch von Kopf bis Fuß.>\n\nDas ist alles, was Ickoris schicken konnte?", sourceObjectiveStatus = "unverified-source-field" }
quests[11704] = { id = 11704, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "König Mrgl-Mrgl", description = "Das ist mal seltsam, {class}, aber da wird es einen Murloc geben, der Euch um Hilfe bitten wird!\n\nMan nennt ihn König Mrgl-Mrgl, der Anführer der Winterflossen. Es scheint, als hätte man seine Leute und ihn aus ihrem Dorf verjagt - nun wollen sie jemanden, der ihnen hilft.\n\nUnd dieser Jemand seid Ihr!\n\nIhr findet die Zuflucht der Winterflossen und den König in westlicher Richtung. Geht einfach die Straße entlang, bis Ihr die Klippen erreicht, und steigt sie in der Nähe des Kochenden Teiches hinab.", sourceObjective = "Sprecht mit König Mrgl-Mrgl. Dieser befindet sich in der Zuflucht der Winterflossen.", completion = "Endlich - Hilfe! Und dem Anschein nach Allianz.\n\nGut so... Eure Leute sind sehr geübt, wenn es ums Kämpfen geht. Davon werden wir jede Menge benötigen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11705] = { id = 11705, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Törichtes Unterfangen", description = "Das ist Wahnsinn. Wie kann man von uns erwarten, dass wir uns mit einem Nekrolord der Geißel und einer unbekannten Zahl an Gefolgsleuten anlegen?\n\n<Getry schluchzt.>\n\nWenn Ickoris Euch schickt, dann muss er Euch für große Taten in der Lage halten. Vielleicht verursacht Ihr hier und heute ja ein Wunder, was?\n\nWenn Ihr soweit seid, steigen wir hinunter und treten Varidus gegenüber.\n\nWenn wir es in einem Stück aus dieser Misere heraus schaffen, meldet Euch bei Höllschrei in der Kriegshymnenfeste.", sourceObjective = "Helft Getry dabei, Varidus den Flenser bei den Höfen des Kriegshymnenklans zu besiegen.\n\nFalls Ihr erfolgreich sein solltet, erstattet Garrosh Höllschrei Bericht.", completion = "Und Ihr seid siegreich zurückgekehrt, genau wie ich dachte! Ich habe es Saurfang ja gesagt, dass Ihr spitze seid.\n\n<Höllschrei grunzt besserwisserisch.>\n\nVielleicht wird das dem alten Hund zeigen, dass er nicht auf alles eine Antwort hat, was?", sourceObjectiveStatus = "unverified-source-field" }
quests[11706] = { id = 11706, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Kollaps", description = "Ich habe Alluvius mithilfe des Horns des Elementarfurors erschaffen und gebunden. Geht zum südlichsten Schlundloch und lasst das Horn erschallen - er wird seinem Ruf gehorchen.\n\nDas Erdbeben, das Alluvius hervorrufen wird, sollte die nerubischen Tunnel zum Einsturz bringen und ihrem Flankenangriff ein Ende setzen. Ich wäre nicht überrascht, wenn sich der Hauptmann der Neruber nach dem Erdbeben zeigen würde. Sollte der Einsturz der Tunnel ihren Angriff nicht zum Halt bringen, würde ein Sieg über ihren Anführer in dieser Hinsicht sicherlich Erfolg haben.", sourceObjective = "Windzähmerin Barah in Taunka'le möchte, dass Ihr die nerubischen Schlundlöcher mithilfe des Horns des Elementarfurors zum Einsturz bringt und Fürst Kryxix besiegt.", progress = "Habt Ihr Alluvius losgelassen und den nerubischen Angriff zum Erliegen gebracht?", completion = "Eure Dienste gegen die Neruber haben den überwältigenden Ansturm der Geißel kurzzeitig zum Stillstand gebracht und gewähren uns eine Verschnaufpause. Dank Eurer Taten können wir die nördlich gelegene Festung der Geißel angreifen, ohne einen Angriff aus dem Westen fürchten zu müssen.\n\nWas das Horn angeht: Ich werde es einstweilen in sicheren Gewahrsam nehmen, bis wir seine Macht wieder benötigen. Sturmhuf hat sein Leben dafür gegeben, dieses Horn zu sichern, und wir können es uns nicht leisten, es noch einmal zu verlieren.", sourceObjectiveStatus = "unverified-source-field" }
quests[11707] = { id = 11707, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Notruf", description = "Oh, gut, Ihr seid {name}, nicht wahr?\n\nWir benötigen heute wiedereinmal Eure Hilfe. Es geht genauso wie gestern um die Landebahn Kurbelzisch im Norden! Die Magnatauren und die Geißel... und die Pumpstation!\n\nEs ist verrückt, sag' ich Euch, verrückt!\n\nIhr müsst dorthin gehen und mit dem alten Vollgas sprechen - und zwar dalli!", sourceObjective = "Sprecht mit Kurbelzisch Vollgas auf der Landebahn Kurbelzisch.", completion = "Wie ich sehe, hat es Himmelhopper endlich mal geschafft, Hilfe zu schicken. Und nicht zu früh, möchte ich hinzufügen!\n\nWillkommen, Bruder, wir benötigen dringend Eure Hilfe!", sourceObjectiveStatus = "unverified-source-field" }
quests[11708] = { id = 11708, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Mechagnome", description = "Nun, da Ihr hier seid, ist der Zeitpunkt gekommen, dass ich Euch die ganze Geschichte über das erzähle, was hier los ist.\n\nGeht nach draußen, sobald Ihr meinen Bericht gehört habt, und sprecht mit Jinky Flügelirre. Sie wird sich von da ab um alles kümmern.", sourceObjective = "Hört Euch Kurbelzisch Vollgas' Bericht an und sucht anschließend Jinky Flügelirre auf der Landebahn Kurbelzisch auf.", progress = "Tagchen.", completion = "Der Alte hat Euch zu mir geschickt, hm? Und er hat Euch alles darüber erzählt, was hier draußen vor sich geht?\n\nGut... dann packen wir mal die Sache an!", sourceObjectiveStatus = "unverified-source-field" }
quests[11709] = { id = 11709, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Nork Blutwahns Aufgabe", description = "Obgleich Ihr viel getan habt, um unsere Position hier in diesen gefrorenen Weiten zu festigen, lauern noch immer andere Gefahren in den Schatten. Ich möchte, dass Ihr Aufseher Nork Blutwahn helft, der im Internierungslager stationiert ist, welches gleich südöstlich der Kriegshymnenfeste liegt. Sucht Ihn auf und bietet Ihm Eure Hilfe beim Transport und beim Austausch der Gefangenen an.\n\nWegtreten, {name}.", sourceObjective = "Sprecht mit Aufseher Nork Blutwahn in der Kriegshymnenfeste in der boreanischen Tundra.", completion = "<Nork spottet.>\n\nGefangene? Das sind keine Gefangenen. Das sind feige Hunde! Seht sie Euch nur an. Wusstet Ihr, dass jeder einzelne dieser gelbbäuchigen \"Soldaten\" vor unsere Tore kam und seine Waffen und seine Rüstung niedergelegt hat?\n\nNach dem zu urteilen, was wir gehört haben, werden diese Männer und Frauen entlassen und zurück nach Hause geschickt, wenn sie von uns gefangen werden.\n\n<Nork spuckt.>\n\nErbärmlich...", sourceObjectiveStatus = "unverified-source-field" }
quests[11710] = { id = 11710, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Was ist nur los mit der Transmaterie?", description = "Überall im Osten sind Ersatzteile verstreut: in den Siedenden Teichen, den Geysirfeldern... ach, was sag ich, wahrscheinlich sogar bis zur Pumpstation hin liegt das Zeugs rum. Bringt es alles wieder zurück. Vielleicht werde ich es dann hinbekommen, mit dem Ding auch jemanden von hier wegzuteleportieren, ganz abgesehen davon, dass ich noch die eingehenden Transmatierieanschlüsse ausrichten muss.\n\nIch würde ungern einen weiteren Unfall erleben...", sourceObjective = "Sammelt 15 Ersatzteile von Kurbelzisch und liefert sie an Mordle Zahnrad auf der Landebahn Kurbelzisch.", progress = "Wir werden 'ne Menge Ersatzteile brauchen, um dieses Ding am Laufen zu halten.\n\nBitte sagt mir, dass Ihr alles dabei habt, was wir benötigen.", completion = "Das ist großartig, {class}! Diese Teile sehen aus, als wären sie in einem brauchbaren Zustand.\n\nWenn ich jetzt nur herausfinden könnte, wie man eines dieser verfluchten Dinger repariert...", sourceObjectiveStatus = "unverified-source-field" }
quests[11711] = { id = 11711, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Angsthasenlieferung... unter 30 Minuten - ansonsten gratis", description = "Mit jedem Tag, der verstreicht, kommen mehr Deserteure an unser Tor. Wir haben einfach nicht genug Platz, um all diese Maden zusammenzupferchen. Ganz besonders dann nicht, wenn wir die Schweine bei Laune halten wollen.\n\n<Nork prustet vor Lachen.>\n\nIch möchte, dass Ihr einen der Feiglinge zur Kreuzung im Osten begleitet und diese Leuchtpistole abfeuert. Einer ihrer Hauptmänner wird auftauchen, sobald die Allianz das Leuchtsignal sieht, und Euch den Feigling abnehmen.\n\nMeldet Euch bei Späher Tungok auf der Oststraße, nachdem die Lieferung stattgefunden hat.", sourceObjective = "Bringt den Deserteur der Allianz zur Kreuzung östlich der Kriegshymnenfeste und feuert die Leuchtpistole des Kriegshymnenklans ab, um der Allianz ein Zeichen zu geben.\n\nMeldet Euch bei Späher Tungok, nachdem die Übergabe des Deserteurs der Allianz erfolgreich abgeschlossen wurde.", completion = "Gute Arbeit, {name}. Das ist ein dreckiger, unnützer Allianzmistkerl weniger, den wir versorgen müssen...\n\nFalls Ihr noch mehr Arbeit wollt, die Tauren und Blutelfen hier in der Nähe bräuchten ein wenig Hilfe.\n\nNatürlich haben wir hier draußen auch unsere eigenen Probleme, mit denen wir uns herumschlagen müssen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11712] = { id = 11712, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Verflucht nochmal!", description = "Wenn Ihr dem alten Mann zugehört habt, wisst Ihr, dass manche Gnome dort draußen manipuliert wurden. Ritzelmeister Mechazod hat sie mit etwas infiziert, das den 'Fluch des Fleisches' neutralisiert, und nun sind sie Roboter!\n\nWir meinen, einen Weg gefunden zu haben, sie wieder mit einem Fluch zu belegen, der sie wieder normal macht. Dazu müsst Ihr diese fluchrekursive Transmaterieinjektion auf die Leichen der Mechagnome, über die Ihr stolpert, anwenden.\n\nWir hoffen, dass dieses Zeugs sie heilen und es uns erlauben wird, sie wieder hierher zurückzuteleportieren.\n\nWas meint Ihr dazu, {name}?", sourceObjective = "Jinky Flügelirre bei der Landebahn Kurbelzisch möchte, dass Ihr die fluchrekursive Transmaterieinjektion auf 6 der Mechagnome von Kurbelzisch anwendet.", completion = "Ihr habt es geschafft... es hat funktioniert!\n\nIch kann es gar nicht glauben, dass Ihr so viele retten konntet. Wir können uns glücklich schätzen, Euch hier bei uns zu haben!", sourceObjectiveStatus = "unverified-source-field" }
quests[11713] = { id = 11713, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Aufspüren der Schlundlöcher", description = "Kurbelzisch hat ein Luftüberwachungsteam losgeschickt, um die Schlundlöcher der Neruber im Süden der Geysirfelder zu kartieren, doch das ist noch nicht zurückgekehrt. Ich kann nicht länger auf die Informationen warten, deshalb brauche ich jemanden, der zu Fuß die Schlundlöcher sucht.\n\nIch verstehe die damit verbundenen Gefahren und werde Euch dementsprechend entschädigen. Nehmt diese Karte mit und tragt die entscheidenden Informationen über die Schlundlöcher ein, auf die Ihr dort draußen trefft.", sourceObjective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr die Karte der Geysirfelder nehmt und die Positionen des südlichen, des nordwestlichen und des nordöstlichen Schlundlochs eintragt.", progress = "Habt ihr die Positionen der Schlundlöcher eingetragen?", completion = "<Abner nimmt die Karte entgegen und studiert sie genau.>\n\nGroßartig! Das ist alles, was wir an Informationen brauchen, um mit der Operation zu beginnen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11714] = { id = 11714, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ungeziefer vertilgen", description = "Hättet Ihr vielleicht Interesse, mir dabei zu helfen, diese Felder zu säubern? Sie sind mit dreckigen kleinen Rattenmenschen übersät! Kobolde, Schneebolde oder wie auch immer Ihr sie nennen wollt, sie sind über den ganzen verdammten Ort verstreut. Der Gestank alleine ist die reinste Hölle!\n\nKümmert Euch für mich um das Ungeziefer und ich werde dafür sorgen, dass es sich für Euch lohnt, {name}.", sourceObjective = "Späher Tungok in der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr 8 Blutsporenernter, 5 Blutsporenfeuerteufel und 2 Blutsporenröster tötet.", completion = "Gute Arbeit, {name}! Ich danke Euch!", sourceObjectiveStatus = "unverified-source-field" }
quests[11715] = { id = 11715, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Öl für das Projekt", description = "Ich möchte eine Maschine bauen, die die Tunnel zum Einsturz bringt, welche die Geißel benutzt, um ihre Neruber einzusetzen. Aber da die Hauptbohrplattform außer Betrieb ist, müssen wir uns irgendwie anders Treibstoff für das Gerät besorgen.\n\nDraußen in den Geysirfeldern im Südosten gibt es kleine Öllachen, die entfernt von der Hauptplattform aus dem Boden quellen. Wenn Ihr genug Öl von diesen Lachen besorgen könnt, kann ich Treibstoff herstellen, um die Maschine zu betreiben.\n\nSetzt einfach den Sammler in der Nähe der Plattform ein und er wird das Öl in seinen Tank pumpen.", sourceObjective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mit dem tragbaren Ölsammler 8 Fässer Öl sammelt.", progress = "Habt Ihr den Treibstoff?", completion = "<Abner beginnt den Öltank des Sammlers zu leeren.>\n\nDas per Hand zu destillieren ist schwierig, doch ich werde das schon bald erledigt haben. In der Zwischenzeit brauchen wir noch eine weitere Komponente, um die Maschine fertig zu stellen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11716] = { id = 11716, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die wundersamen Blutsporen", description = "Wir sind Zeugen von etwas Außergewöhnlichem, {race}. Ein paar Schritt weit entfernt von uns existiert ein ganzes Ökosystem, das noch nicht entdeckt wurde! Ich vermute, dass die Blutsporenpflanze die Natur hier zum Sprießen bringt.\n\nIch habe ein wenig Blütenstaub der nahe gelegenen männlichen Blutsporenpflanze gesammelt, doch zur Bestäubung fehlen mir noch die weiblichen Rezeptoren. Besorgt mir einen Scheffel der Blutsporenkarpelle. Ihr könnt sie in der Nähe der größeren Pflanzen finden, die uns umgeben.\n\nNehmt Euch jedoch vor ihren Wächtern in Acht! Die Kobolde werden sie nicht ohne Weiteres aufgeben!", sourceObjective = "Blutmagierin Laurith in der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr 10 Blutsporenkarpelle beschafft.", progress = "Die Versuche müssen weitergeführt werden!", completion = "Herrlich! Einfach herrlich!\n\n<Laurith trägt ein wenig Blütenstaub auf eines der Blutsporenkarpelle auf und spricht eine Beschwörungsformel.>\n\nHmpf... ich verstehe nicht. Außer... Aber natürlich!", sourceObjectiveStatus = "unverified-source-field" }
quests[11717] = { id = 11717, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Pollen von den Motten besorgen", description = "Es liegt auf der Hand! Die Blutsporenmotten sind für die Bestäubung dieser Ebenen verantwortlich. Es muss etwas aus dem Stoffwechsel der Motten sein, das als Katalysator für die Funktion dieser Pollen dient. Es fängt jetzt alles an, einen Sinn zu ergeben, {name}. Deshalb töten die Kobolde die Motten nicht, sondern beschützen sie so gut sie können! Diese dreckigen, kleinen Ratten haben das durchschaut!\n\nNun, dann müssen wir uns einfach unsere eigenen Mottenpollen besorgen! Was meint ihr dazu? Besorgt Ihr mir welche im Namen der Wissenschaft?", sourceObjective = "Blutmagierin Laurith in der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr 5 Pollen von Blutsporenmotten besorgt.", progress = "Die Pollen sind der Schlüssel!", completion = "Ah-ha!\n\n<Laurith sprenkelt die Mottenpollen über die Blutsporenkarpelle.>\n\nSeht Euch das an!", sourceObjectiveStatus = "unverified-source-field" }
quests[11718] = { id = 11718, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein Bot im Mammutpelz", description = "Ich habe die Grundstruktur eines alten Bots so rekonfiguriert, dass er ein Erdbeben auslösen wird, das stark genug ist, die Tunnel zum Einsturz zu bringen. Doch die Maschine ist empfindlich gegenüber Nordends beißender Kälte.\n\nIch habe einen Weg gefunden, ihn mit den dicksten Bälgen einheimischer Mammuts zu isolieren. Sie streifen auf den Ebenen südlich der Landebahn und in der Nähe der Geysirfelder herum. Bringt genug Bälge mit, um die Maschine fertigzubauen und sie auf die Neruber loszulassen!", sourceObjective = "Abner Zischeldrill auf Landebahn Kurbelzisch möchte, dass Ihr ihm 6 dicke Mammutbälge bringt.", progress = "Bringt mir diese Bälge so schnell wie möglich! Ich werde die Maschine ohne sie nicht fertig stellen können!", completion = "<Abner inspiziert die Bälge. Der aufgewirbelte Staub bringt ihn zum Husten.>\n\nKörperhygiene wird bei diesen Tieren wohl nicht besonders groß geschrieben? Einige von diesen Fellen sind völlig verdreckt. Nun, ich sollte wohl besser damit anfangen, sie zu reinigen. Ist ja nicht so, dass hier irgendwer Zeit übrig hätte - oh nein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11719] = { id = 11719, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein geeignetes Versuchsobjekt", description = "<Laurith mustert Euch von Kopf bis Fuß.>\n\nSo, wir haben also diese bestäubte Blutsporenblume hier, aber niemanden, an dem wir ihre Wirkung ausprobieren könnten. Sagt mir, wäret Ihr vielleicht daran interessiert, das hier auf Eure Haut zu reiben und mich dabei zusehen zu lassen, was passiert? Was könnte schon Schlimmes dabei passieren?\n\nKeine Sorge, {name}! Schmiert Euch einfach ein wenig von dem hier ins Gesicht.", sourceObjective = "Blutmagierin Laurith auf der Blutsporenprärie in der boreanischen Tundra möchte, dass Ihr die bestäubte Blutsporenblume verwendet und sie dabei zusehen lasst, was passieren wird.", progress = "Habt keine Angst.", completion = "Ur Machthorn wird entzückt sein! Das ist besser, als ich es je erwartet hätte!\n\nWomöglich ist es an der Zeit, dass ich Euch die Wahrheit erzähle.", sourceObjectiveStatus = "unverified-source-field" }
quests[11720] = { id = 11720, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Die Invasion von Gammut", description = "Höllschrei hat Machthorn und mich mit der entmutigenden Aufgabe betraut, die Magnatauren an der südlichen Front der Kriegshymnenfeste auszurotten. Mit uns kam ein kompletter Zug erfahrener Hordesoldaten. Unser erster Vorstoß in die nahe gelegenen Magnataurenhöhlen erwies sich als recht erfolglos, da unser kompletter Trupp von den Verteidigern der Höhlen ausgelöscht wurde. Wir sind die einzigen, die übrig sind...\n\nWir sind weder Wissenschaftler noch Forscher. Wir sind Soldaten der Horde, so wie Ihr...\n\nSprecht jetzt mit Ur Machthorn.", sourceObjective = "Sprecht mit Ur Machthorn in der Blutsporenprärie in der boreanischen Tundra.", completion = "Die Blutsporen, die Ihr gesammelt habt, könnten uns einen Vorteil gegen die Magnatauren von Gammut verschaffen. Mit Eurer Hilfe versteht sich.", sourceObjectiveStatus = "unverified-source-field" }
quests[11721] = { id = 11721, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Gammutra der Peiniger", description = "Magnatauren leben in Rudeln, gleich den Löwen: ein oder zwei dominante Männchen und mehrere Weibchen gemeinsam mit ihrem Nachwuchs. Der Anführer von Gammut, der Magnataurenhöhle westlich von hier, wird Gammutra genannt. Es ist Gammutra, der über diese Magnataurenpopulation herrscht, also ist es auch Gammutra, den wir niederstrecken müssen, um jegliche Art des Aufruhrs durch die Magnatauren zu verhindern.\n\nNehmt diesen Beutel mit zerdrückten Blutsporen an Euch und geht nach Gammut. Schwächt Gammutra mithilfe der Blutsporen und erschlagt ihn! Bringt mir sein Haupt als Beweis.", sourceObjective = "Erschlagt Gammutra und bringt den Kopf von Gammutra zum Tauren namens 'Ur Machthorn' in der Blutsporenprärie in der boreanischen Tundra.", progress = "Das Pulver kann dazu verwendet werden, alle Magnatauren zu schwächen. Was auch der Grund dafür ist, weshalb das Rattenvolk in dieser Gegend es so gut behütet.", completion = "Ihr habt gute Arbeit geleistet, {name}! Würdet Ihr Laurith und mir die Ehre erweisen, zu Höllschrei zu gehen und ihm den Kopf des Biests zu präsentieren? Er wird äußerst zufrieden sein.", sourceObjectiveStatus = "unverified-source-field" }
quests[11722] = { id = 11722, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Trophäen von Gammut", description = "Der Sieg der Horde ist nicht allein uns zu verdanken, {name}. Ihr wart es, <der/die> Ihr Euer Leben riskiertet, um die Blutsporen zu testen, und Ihr seid es gewesen, <der/die> Gammutra zu guter Letzt ein Ende bereitete.\n\nErweist uns die Ehre und kehrt zur Kriegshymnenfeste zurück, um Fürst Höllschrei den Kopf von Gammutra zu präsentieren.", sourceObjective = "Bringt den Kopf von Gammutra zu Garrosh Höllschrei in der Kriegshymnenfeste.", progress = "So schnell schon wieder zurück?", completion = "<Höllschrei hebt den Kopf von Gammutra mit einer Hand auf und spuckt in sein Gesicht.>\n\nSie werden es lernen, {name}... Sie werden es alle lernen. Mit der Horde ist nicht zu spaßen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11723] = { id = 11723, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Setzt den Schüttlo-Rüttlo ein!", description = "Ich präsentiere Euch die Maschine, die uns vor der Bedrohung durch die Neruber beschützen wird!\n\n<Abner strahlt vor Stolz, als er Euch seinen fertigen Bot zeigt.>\n\nNehmt diese Fernsteuerung, geht zu einem der nerubischen Schlundlöcher auf den Geysirfeldern und aktiviert mit ihrer Hilfe den Schüttlo-Rüttlo 5000. Er wird dann den Rest von alleine erledigen.\n\nWundert Euch nicht, wenn das von ihm verursachte Erdbeben die Aufmerksamkeit eines nerubischen Anführers erregt. Genau genommen wäre es eine großartige Gelegenheit, der nerubischen Offensive den Rest zu geben.", sourceObjective = "Abner Zischeldrill auf der Landebahn Kurbelzisch möchte, dass Ihr mithilfe des Schüttlo-Rüttlo 5000 die Tunnel der Neruber zum Einsturz bringt und Fürst Kryxix besiegt.", completion = "<Abner hört Euch aufmerksam zu, während Ihr vom Erfolg des Schüttlo-Rüttlo 5000 und Euch berichtet.>\n\nKurbelzisch wird über die Nachrichten hocherfreut sein! Und wer weiß, vielleicht wird er sogar einen Mechaniker aus Euch machen!", sourceObjectiveStatus = "unverified-source-field" }
quests[11724] = { id = 11724, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Mächtiges Mottenomelett?", description = "Dieses Ei war jemandem offensichtlich sehr wichtig, wie die Leiche in der Nähe zeigt. Wenn man das Ei genauer betrachtet, merkt man, dass es bereits für den Versand in die Blutsporenprärie markiert war, an Blutmagierin Laurith. Das ist östlich von hier!\n\nNehmt das Ei und bringt es zur wartenden Blutmagierin.", sourceObjective = "Bringt das schwere leuchtende Ei zu Blutmagierin Laurith in der Blutsporenprärie in der boreanischen Tundra.", progress = "Grüße!", completion = "Alkor ist Geschichte, wie? Eine Schande... Was das Ei angeht, so haben wir keine wirkliche Verwendung mehr dafür. Wir haben wesentlich größere Probleme, um die wir uns jetzt kümmern müssen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11725] = { id = 11725, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Auf der Suche nach Trudelflug", description = "Ich hätte die Mission selber fliegen sollen. Es ist nicht so, dass ich Trudelflug nicht vertrauen würde - ganz und gar nicht. Verdammt, er war der beste Flügelmann, mit dem ich je geflogen bin.\n\nNein, es ist nur so, dass ich eigentlich dafür zuständig bin, solch eine wichtige Mission zu fliegen.\n\nIch habe Trudelflug mit unserer schnellsten Aufklärerstaffel ausgesandt, um die Teiche weit im Süden und gleich westlich der nerubischen Schlundlöcher auszukundschaften.\n\nFindet Trudelflug, {name}.", sourceObjective = "Macht Iggy \"Trudelflug\" Zinkenwechsel auf den Geysirfeldern ausfindig.", completion = "Gnom sei Dank. Es war schrecklich.\n\nDa war ein greller Lichtblitz am Boden und das Nächste, woran ich mich erinnern kann, ist, dass die komplette Staffel im Begriff war, abzustürzen! Ich bin ziemlich schwer verletzt, hatte also nicht die Möglichkeit, die Absturzstelle nach anderen Überlebenden abzusuchen. Doch irgendetwas sagt mir, dass es nicht sehr viele geben wird.\n\n<Iggy verzieht sein Gesicht vor Schmerz.>\n\nWerdet Ihr mir dabei behilflich sein, meine Mission zu beenden?", sourceObjectiveStatus = "unverified-source-field" }
quests[11726] = { id = 11726, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Ein klein wenig Würze", description = "Die Wölfe haben das Wrack nach dem Absturz durchwühlt und dabei wohl den Mikrofilm unserer Mission aufgefressen.\n\nIch habe einen Plan, wie wir diesen Mikrofilm wiederbeschaffen können, doch ich brauche Eure Hilfe, um das zu bewerkstelligen.\n\nGen Süden und Osten in den Flutebenen leben Kreaturen, die man die Gorloc nennt. Sie bereiten ihre Mahlzeiten mit üblen Gewürzen zu, die jede andere Kreatur grün anlaufen lassen würden. Wenn Ihr genug Gewürzbeutel von den Dampfrülpsern der Gorloc und den Watschlern der Gorloc sammelt, kann ich Euch daraus den Wolfsköder herstellen.", sourceObjective = "Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr 4 Gewürzbeutel der Gorloc sammelt.", progress = "Habt Ihr die Gewürzbeutel dabei?", completion = "<Iggy hält sich die Nase zu, als er die Gewürzbeutel leert, und spricht zu Euch mit einem nasalen Ton in seiner Stimme.>\n\nJetzt, wo wir alles Nötige haben, werde ich es mit den Notrationen vermischen, um daraus einen Köder für die Wölfe zu basteln.", sourceObjectiveStatus = "unverified-source-field" }
quests[11727] = { id = 11727, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Eine Zeit für Helden", description = "Es ist gut, Euch unter uns zu haben, {name}. Wir haben alle von Euren vergangenen Taten erfahren.\n\nWie Ihr wisst, ist König Wrynn dabei, große Armeen nach Nordend zu bewegen, die denen von Arthas begegnen sollen. Doch Armeen sind nichts ohne die Helden, die sie inspirieren und führen.\n\nIch möchte, dass Ihr <dieser Held/diese Heldin> für meine Männer seid. Kämpft an ihrer Seite gegen die Geißel, die unsere Festung belagert.\n\nMeldet Euch bei Unteroffizier Hammerberg außerhalb der inneren Burgwehr. Die Valianzfeste darf nicht fallen. Die Zukunft unserer Kampagne hängt davon ab.", sourceObjective = "Meldet Euch bei Unteroffizier Hammerberg in der Valianzfeste.", completion = "Bei Magnis Bart! Sieht aus, als wäre die Artillerie gekommen.", sourceObjectiveStatus = "unverified-source-field" }
quests[11728] = { id = 11728, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Lupus pupus", description = "Was auch immer Ihr macht, nehmt auf keinen Fall einen Happen von diesem Köder. Legt ihn einfach in der Nähe eines ölbeschmierten Wolfes. Wenn sie verzweifelt genug sind, den Mikrofilm zu fressen, dann werden sie sich wie wild auf den Köder stürzen, sobald sie ihn riechen.\n\nWartet einfach nur, bis die Dinge ihren natürlichen Lauf nehmen und sucht im... äh... Nebenprodukt nach dem Film.\n\nIch würde Euch ja meinen speziellen Lupus Pupus Spatus für den Job anbieten, aber ich habe ihn bei der Landebahn gelassen. Es tut mir leid, sagen zu müssen, dass Ihr die... ähhm... Suche auf die altmodische Art und Weise durchführen müsst.", sourceObjective = "Iggy \"Trudelflug\" Zinkenwechsel bei den Siedenden Teichen möchte, dass Ihr ihm 8 Mikrofilmteile bringt.", progress = "Habt Ihr den Mikrofilm beschaffen können?", completion = "<Iggy hält sich die Nase zu, als er den Mikrofilm entgegen nimmt.>\n\nIgittigitt! Nun ja, wir haben Absatz 8.2, Paragraph B des Notfallprotokolls entsprechend den Film wieder beschafft. Nichts im Protokoll deutet jedoch darauf hin, dass ich es putzen muss.", sourceObjectiveStatus = "unverified-source-field" }
quests[11729] = { id = 11729, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Der Ultraüberschallschrauber", description = "Die Einheit, die Ihr soeben in ihre Bestandteile zerlegt habt, hatte das hier in ihrem Inneren.\n\nEs sieht ziemlich kompliziert aus... bei der Landebahn wird sicherlich jemand ein Auge drauf werfen wollen. Vielleicht Pfiffi Wackelspross?", sourceObjective = "Liefert den Ultraüberschallschrauber bei Pfiffi Wackelspross ab. Sie befindet sich auf der Landebahn Kurbelzisch.", completion = "Mein Schraubenzieher... Ihr habt meinen Schraubenzieher gefunden! Hab mich schon gefragt, wo ich das Ding verloren hab'.\n\nHmm, Ihr habt es im Inneren eines ihrer Roboter gefunden, meint Ihr? Das bringt mich auf eine Idee...", sourceObjectiveStatus = "unverified-source-field" }
quests[11730] = { id = 11730, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Meister und Diener", description = "Der Ultraüberschallschrauber ist das ultimative Werkzeug, wenn es sich um das Bearbeiten von mechanischen Dingen dreht!\n\nGeht zurück zu den Teichen und zerlegt ein paar von Mechazods Robotern. Ihr müsst dann nur noch ihre Überreste mit dem Schraubenzieher bearbeiten und ich wette mit Euch, dass sie sich auf unsere Seite schlagen werden - zumindest für kurze Zeit.\n\nIch bin mir ziemlich sicher, dass er sich nicht auf die Mechagnome anwenden lässt, also könnt Ihr sie getrost ignorieren.\n\nOh, und falls die Roboter irgendwas dabei haben sollten, müsst Ihr es an Euch nehmen, bevor Ihr sie mit dem Schraubenzieher bearbeitet!", sourceObjective = "Programmiert mithilfe des Ultraüberschallschrauber 15 Roboter um und kehrt anschließend wieder zu Pfiffi Wackelspross bei der Landebahn Kurbelzisch zurück.\n\nAchtet darauf, die kaputten Roboter zu plündern, bevor Ihr sie umprogrammiert.", completion = "Juhuu! Und Ihr habt den Schraubenzieher in einem Stück zurückgebracht!\n\nDass wir diese Roboter umprogrammiert haben, wird sich noch als großer Vorteil im Kampf gegen Ritzelmeister Mechazod herausstellen. Ich meine, Ihr habt Euch eine Kleinigkeit dafür verdient.", sourceObjectiveStatus = "unverified-source-field" }
quests[11731] = { id = 11731, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Fackelwurf", description = "Ihr wollt also Feuerjongleur werden? Denkt Ihr, dass Ihr das Zeug dazu habt? Die Geschicklichkeit? Die Reflexe? ... den Mut? Wenn ja, dann wollen wir Euch mal auf die Probe stellen!\n\nNehmt diese Fackeln und rennt zum Freudenfeuer. Dort befinden sich Kohlenpfannen, über denen blinkende Markierungen schweben, die Ihr mit einer Fackel treffen müsst. Seid schnell! Um für einen Wurf Punkte zu bekommen, müsst Ihr die Fackel werfen, bevor die Markierung verschwindet!\n\nTrefft genug markierte Kohlenpfannen, bevor die Zeit abgelaufen ist, und kommt dann hierher zurück... um Eure nächste Lektion zu erhalten.", sourceObjective = "Gewinnt das Fackelwurfspiel und sprecht anschließend mit dem Feuerschluckmeister.", completion = "Gut gemacht! Die Lunte eines Feuerkreisels brennt schnell... doch Ihr werdet die Kunst des Feuerjonglierens noch schneller erlernen! Nun macht Euch bereit! Beim nächsten Test werdet Ihr so richtig ins Schwitzen kommen...", sourceObjectiveStatus = "unverified-source-field" }
quests[11732] = { id = 11732, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Entweiht dieses Feuer!", sourceObjective = "Entweiht das Freudenfeuer der Allianz im Arathihochland!", sourceObjectiveStatus = "unverified-source-field" }
quests[11733] = { id = 11733, flavor = "source-reference", locale = "deDE", source = "MultiLanguage wrath a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceFlavor = "wrath", sourceRevision = "a0a5e66931a7f13f06e4f73d1dd472215c5da5a9", sourceVersionUnverified = true, bilingualPairVerified = false, voiceUnavailable = true, title = "Reise zum Riss", description = "Ich habe Eure Taten aufmerksam verfolgt, <Sterblicher/Sterbliche>. Tut nicht so, als wärt Ihr überrascht. Mit Sicherheit habt Ihr gespürt, wie mein Auge auf Euch ruht.\n\nDie Zeit ist nun gekommen, Euch nicht mehr gänzlich im Dunkeln herumtappen zu lassen. Ihr seid nun bereit, der nackten Wahrheit ins Auge zu blicken.\n\nDoch bevor Ihr die Geschichte hört, sollt Ihr erst erfahren, womit wir es zu tun haben.\n\nTrefft alle nötigen Vorbereitungen, {class}...", sourceObjective = "Surristrasz möchte, dass Ihr die Reise nach Kaltarra antretet. Sobald Ihr dort angelangt seid, sollt Ihr mit Erzmagier Berinand sprechen.", completion = "Willkommen in Kaltarra, {class}.\n\nHinter dem Transitusschild liegen wir verborgen, nur einen Steinwurf weit vom Nexus entfernt, der Festung des großen Aspekts Malygos und seinem blauen Drachenschwarm.\n\nFühlt Euch wie Zuhause.", sourceObjectiveStatus = "unverified-source-field" }
